/* 平成15年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h15.committeeSessions.push(...[{"id":"h15-20031010-4","meetingId":"h15-c-settlement","date":"2003年10月10日","dateIso":"2003-10-10","committee":"決算特別委員会","time":"午前１０時０５分～午後５時４３分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を143件整理しています。","topics":[{"id":"topic-01","title":"◯松澤委員長 おはようございます。ただいまより決算特別委員会を開会いたします。 それでは、平成１４年度品川区一般会計歳入歳出決算","agenda":"◯松澤委員長 おはようございます。ただいまより決算特別委員会を開会いたします。 それでは、平成１４年度品川区一般会計歳入歳出決算","exchanges":[{"speaker":"伊藤委員","kind":"質問・要望","question":"私のほうからは、１３１ページ、健康づくり事業費に大きく関連して１点、それから、１３６ページのコンテナ老朽取替につきまして、質問いたします。その経過について、ご承知であれば、まず確認をここでしていただきたいんですが、わかりますか尋ねました。","respondent":"田中健康課長","answer":"全日本学校歯科保健優良校、文部科学大臣賞ということで、昨年度、全国で８校のうちの１校に選ばれたという、大変名誉ある賞だと受けとめております。","id":"exchange-001"},{"speaker":"伊藤委員","kind":"意見","question":"それから全身状況の健康の向上につながっていく可能性が十分あるわけでありますから、そのことについての見解を、改めてお聞かせください。お願いいたしますとの意見を述べました。","respondent":"田中健康課長","answer":"いろいろな関係団体とも調整しながら、地域の健康づくりに取り組む一つの方針としまして、お話し合いができたらと思ってあります。それから関係団体とも調整をさせていただいた上で、健康づくり推進の一つの形式になるかどうか、これから検討してまいりたいと思ってあります。","id":"exchange-002"},{"speaker":"伊藤委員","kind":"質問","question":"以前、なぜかということをお伺いしましたが、特許であって、この会社しかできない技術であるからということも聞いております。私がどうしてこのことにこだわっているかといいますと、新たにここにお伺いした際に、はっきりおっしゃったことがあったんですよ。","respondent":"中山清掃リサイクル課長","answer":"コンテナ取替ですが、委員からご説明があったように、東品川清掃作業所の船舶中継のコンテナです。私どもの技術部門とも連携をとって、少しでも、こういった維持の経費を削減できるような努力はしてまいりたいと思います。","id":"exchange-003"},{"speaker":"伊藤委員","kind":"意見","question":"こういうごみの中継施設、それからし尿処理場等々、いろいろなものが品川区内にあります。もう一つ踏み込んだ考え方の中で、そういうコストに対する考え方、とらえ方をお答えいただければと思うんですとの意見を述べました。","respondent":"中山清掃リサイクル課長","answer":"１台何十万円というようなコストをかけていた部分を、若干ですが、歳入も上げてあります。そういう地道な努力をしながら、一層効率的な運営を心がけてまいりたいと思います。","id":"exchange-004"},{"speaker":"嶋委員","kind":"質問","question":"私のほうから、きょうは盛りだくさんなんですが、５項目ぐらいについてお伺いいたします。それから、来れなかった方たちに対してのご配慮といいますか、どういうふうにされていらっしゃるのか、ちょっとお聞きしたいと思います。","respondent":"小林品川区保健センター保健サービス課長","answer":"それから、１歳半健診ですけれども、８５％前後、３歳児健診につきましても８５％前後。ほかで受けているかとか、あるいは、また別の日に受診されるかどうかということで把握しております。","id":"exchange-005"},{"speaker":"嶋委員","kind":"質問・要望","question":"受診率は、ほんとうに全部が大体８５％以上で、３、４カ月健診は九十五、六％ということで、大変進んでいるかと思います。ヤングママからいろいろ要望があるんですが、こういう診察をしていただけないかというご要望がありますが、いかがか尋ねました。","respondent":"小林品川区保健センター保健サービス課長","answer":"未受診者に対する対応というのは、私どもも、大変重要かと認識しております。いろいろな子育て支援、現在のところ、対応させていただきたいと考えております。","id":"exchange-006"},{"speaker":"嶋委員","kind":"質問・要望","question":"地域センターとか、移動診査をしていただきたいということがあったんですが、いかがか尋ねました。","respondent":"小林品川区保健センター保健サービス課長","answer":"保健所、保健相談所を場としてやりたいというのが、私どもの考えです。天候等で、大変ご不便をおかけすることもありますけれども、今のところ、３カ所でやらせていただきたいと考えております。","id":"exchange-007"},{"speaker":"嶋委員","kind":"質問・要望","question":"将来的に、要望をさせていただきたいと考えています。そういう方たちこそちょっと心配ということもありますので、どのように対応されていらっしゃるのか、お聞きいたします。","respondent":"小林品川区保健センター保健サービス課長","answer":"子育て支援、虐待予防という視点で、常に健診に臨んでおります。今年度から、なかなか来られない方に問題があるという認識はしておりますので、全数のお子さん方を保健所が把握できるような態勢で臨んでおります。","id":"exchange-008"},{"speaker":"嶋委員","kind":"質問・要望","question":"ぜひ、来なかった方に対して目を向けていただいて、きめ細かな健診とか、アドバイス等をしていただけたらと思いますので、要望します。祭日もやっていただけるのかどうか、そういうお考えがあるのかどうか、お聞きしたいと思います。","respondent":"小林品川区保健センター保健サービス課長","answer":"現在のところ、先ほど申し上げましたように、平日のみの健診となっております。最優先と考えておりまして、日曜日も含めてやる予定ですので、将来の課題ということで考えさせていただきたいと思います。","id":"exchange-009"},{"speaker":"嶋委員","kind":"質問・要望","question":"ふだん平日もやっと来ていただける状況かなと考えていますので、将来の要望として、よろしくお願いをしたいと思います。共通商品券５００円になっておりますが、緑化対策費になっていくようなものを考えていらっしゃるのか、ちょっとお聞きしたいと思います。","respondent":"金井環境課長","answer":"私ども、ノーレジ袋運動を進めるに当たって、そういったエコシールというものも検討してまいりました。今後の一つの大きな検討材料ではないかということで考えておりますけれども、今の制度を広めて、よろしくお願いいたします。","id":"exchange-010"},{"speaker":"嶋委員","kind":"質問・要望","question":"ぜひ、将来的なものという形でお考えをいただきたいと考えています。シールまで全部外してエコボックスに持って行くと、全然キャッチをしないということがありますので、お聞きしたいと思います。","respondent":"金井環境課長","answer":"エコスポットというのは、あくまでも回収機による回収でございまして、一般的には、はがしていただくのが正解です。区商連とも連携しながら、今後、十分検討していきたいと考えています。","id":"exchange-011"},{"speaker":"嶋委員","kind":"質問・要望","question":"２とおりの回収方法があるので、もっとわかりやすく周知をしてほしいと求めましたので、よろしくお願いいたします。子どもたちに、車が来たよという知らせみたいにオルゴール等が鳴ったらいいなというご要望があるんですが、いかがか尋ねました。","respondent":"中山清掃リサイクル課長","answer":"騒音という苦情をいただくのか、この辺はやはり、品川区の事情の中で考えていく必要があると思います。今おっしゃったような、例えばオルゴールとか、不快感のないような音で周知するようなことにつきましては、いろいろ研究してまいりたいと思います。","id":"exchange-012"},{"speaker":"嶋委員","kind":"確認","question":"安否確認をされているということで、葛飾区の考えが、将来的にあるのか、お考えをお聞きしたい。そういう場合は、どのように対応されていったらいいのか、お聞きしたいと思います。","respondent":"中山清掃リサイクル課長","answer":"１点目の、ごみの集積所を分散するだけじゃない活用という中では、いろいろ考えてまいりたいと思います。何が何でも目の前ということにこだわらず、どなたが出したか明確するのが趣旨ですので、清掃事務所で個別にご相談に応じてまいりたいと思います。","id":"exchange-013"},{"speaker":"嶋委員","kind":"質問・要望","question":"毎年Ｘ線を撮ると副作用もあるし、逆さにされて気分も悪くなるということで、区民が自分で選べる形にしていただきたいということなんです。すみません、最後にそこだけお答えをほしいと求めました。","respondent":"小林品川区保健センター保健サービス課長","answer":"ペプシノゲン法につきましては、まだ検討段階ということで、やはり、引き続きこちらのほうで検討してまいりたいと考えています。","id":"exchange-014"},{"speaker":"宮崎委員","kind":"質問・要望","question":"それとあと、つぶした缶、またはペットボトルの回収が、週に２回だったでしょうか。ちょっと工夫していかないといけないと思っているんですけれども、そこのところを、まずお伺いしたいと思います。","respondent":"金井環境課長","answer":"これについては、週にもう少し増やすとか、あるいは地域の人といろいろ協力しながら進めていくということになろうかと思います。検討していくということになっておりますので、十分検討していきたいと考えていますので、よろしくお願いしたいと思います。","id":"exchange-015"},{"speaker":"宮崎委員","kind":"質問","question":"ですから、機械自体も、ちょっと工夫しなきゃいけないと思いますけれども、改善をお願いしたいと思います。ここら辺のところについて、商店街に加入しない問題というのは、どういうふうにお考えなのか、お聞かせほしいと求めました。","respondent":"市川産業振興課長","answer":"そういう問題の組み立てをなさって、相談に来る例が、現実にあります。事を構えるぐらいのことを考えていらっしゃいますので、そういうところにご紹介をしてきた、そういった経緯はあります。","id":"exchange-016"},{"speaker":"宮崎委員","kind":"質問・要望","question":"行政として何とかできないのかと思うんですけれども、そこのところはどうなのか、ちょっとお考えをいただきたいと思うんです。これは、やっぱり何とかしなきゃいけないと思うんですけれども、行政としてどうなのかということを、ちょっとお伺いしたいと思います。","respondent":"市川産業振興課長","answer":"正直、ドラッグストアなり飲食店に、私どもが直接ものを言うというのは、なかなか難しいかと思います。納得してもらうことも、一つの手じゃないかと、そういったアドバイスをする事例もこれまでにございました。","id":"exchange-017"},{"speaker":"宮崎委員","kind":"質問","question":"ですから、国段階になるかわかりませんけれども、いずれにしても一つのそこの商店街で対応というのは非常に難しい問題だというふうに思うんです。今の答弁だと、商店街としてはまた展望が出てこないと思うんですけれども、改めてどうか尋ねました。","respondent":"市川産業振興課長","answer":"この問題、なかなか一般論として申し上げるのが、大変難しい問題のように思います。これまでもできる限りのことをしてまいりましたし、これからも、同様の姿勢で対処していきたいと考えています。","id":"exchange-018"},{"speaker":"宮崎委員","kind":"質問・要望","question":"そういうまちをつくる核になっているわけですから、ここのところに入らないというのは、やっぱり大きな問題だと思います。何とか、こういうのは対応できないものかというのは、どうか尋ねました。","respondent":"市川産業振興課長","answer":"今、ご質問にございましたケースにつきましても、これはやはり商店街の組織自身が、自治的な解決能力を発揮する場面かと考えます。現在進行形で進んでいるのか把握はできませんけれども、そのケースに応じて相談がまいりましたら、お話を聞くことになろうかと思います。","id":"exchange-019"},{"speaker":"宮崎委員","kind":"質問・要望","question":"今、もともと景気が悪い中で、どういうふうにしたらいいのか、商店街のところもみんな大変な苦労をしているわけなんです。これは民民だということではなくて、対応が必要だということを述べて、終わらせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"大沢委員","kind":"質問","question":"衛生費の１２８ページ、１３６ページにあります動物死体処理費、中小企業対策費のうちの商店街に関することをお伺いいたします。もしくは訂正がありましたら、私にちょっとお教えて願いたいんですけれども、。","respondent":"寺西品川区保健所保健サービス課長","answer":"平成１４年度の患者登録数に関しましては、２４９名で変わりありません。３２３名、３１６名ということで、減少傾向です。","id":"exchange-021"},{"speaker":"大沢委員","kind":"質問","question":"前年度の成果報告書によりますと、ここが１２８名と書いてありまして、そこのところを、ちょっとお伺いしたいと思いまして、質問させていただきました。","respondent":"田中健康課長","answer":"大変申しわけありません、保健所保健サービス課長が申し上げたとおりのものが、実際の数字です。申しわけございません。","id":"exchange-022"},{"speaker":"大沢委員","kind":"質問","question":"毎年大体４４０万円近く、措置費というからには、何か事故が起きているのか。今、医療事故が、非常に社会的な問題になっている昨今ではありますが、どのような種類の事故があったのか、ちょっとお教えて願いたいと思います。","respondent":"田中健康課長","answer":"これにつきましては、以前の事故の関係を続けているところです。事故ということで障害年金の１級を受けられておりまして、現在、このような年額での支給を続けさせていただいているものです。","id":"exchange-023"},{"speaker":"大沢委員","kind":"質問","question":"そうしますと、昭和４６年８月に出生された方の費用が、そのまま引き続き障害者の費用として払われていると理解してよろしゅうありますか尋ねました。","respondent":"田中健康課長","answer":"年金という形で、毎年、お支払いをさせていただいているものです。","id":"exchange-024"},{"speaker":"大沢委員","kind":"質問","question":"それは、大体、いつまで支給を続けられて、また、新たな事故は起こっていないのか、再度、お伺いをいたしたいと思います。","respondent":"田中健康課長","answer":"年金の形で、生涯、その方が生きておられる限り出るという仕組みです。国のほうが、法律で保障しているものです。","id":"exchange-025"},{"speaker":"大沢委員","kind":"質問","question":"朝から大変申しわけございませんが、動物の死体処理の件で、ちょっとお伺いをいたしたいと思います、申しわけございません。８件のために増加をしたということで、１件当たりの単価が上がったのか、ちょっとご答弁をお願いいたします。","respondent":"中山清掃リサイクル課長","answer":"約１８０万円が、平成１３年度は土木費で執行されておりましたが、収集はすべて清掃事務所が行ったということで、執行額の違いが生じたものです。平成１４年度以降は、すべて清掃費のほうに集約しているので、このような形になっております。","id":"exchange-026"},{"speaker":"大沢委員","kind":"質問","question":"続きまして、商店街関係のことをお伺いいたします。老舗に対して、何か目を向けられるような施策といいますか、お考えはありますか尋ねました。","respondent":"市川産業振興課長","answer":"老舗が営業を継続して、なかなかこれだという解決策というか、私どもの支援策というのはちょっと難しいところです。そういうものも一種の支援と言えば言えるのかもしれませんけれども、やれる、私どもの限界かなと感じてあります。","id":"exchange-027"},{"speaker":"大沢委員","kind":"質問","question":"私の一つの考えといたしまして、品川区内の共通商品券を扱えるようなことを条件に、入居させるような形の指導というのはできないものなんでしょうか。よろしくご答弁を、お願いします。","respondent":"市川産業振興課長","answer":"ただいまのご提案を実行できるように、区内共通商品券を流通させることが先決かと思います。確かに、商品券が一定程度流通すれば、組合員にならなければこの商品券を取り扱えないということも、勧誘の一つの動機づけになろうかと思います。","id":"exchange-028"},{"speaker":"大沢委員","kind":"質問","question":"では、次に実践的な事なんですけれども、ポイントカードについて、ちょっとお伺いいたします。そういう部分で、その費用に対して、何か区側で対象となるような助成事業というのはあるのかどうか、ご答弁をお願いいたします。","respondent":"市川産業振興課長","answer":"ただし、各商店街、１年間、２００万円という補助限度額があります。その限度額のうち、今、委員が指摘なさったような経費にどのぐらい充てるかということは、各商店街がご判断して、私どもに申請いただくです。","id":"exchange-029"},{"speaker":"大沢委員","kind":"質問","question":"さらなる、品川区の商業の発展のお手伝いを、行政の側にお願いいたしまして、私の質問を終わらせていただきます。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"山村委員","kind":"質問","question":"１２７ページの各種助成金のほうで質問します。医師会が１,０００万円を超える助成を受けているにもかかわらず、薬剤師会が４０万円と、この算定基準をご説明してほしいと求めました。","respondent":"田中健康課長","answer":"やはりそれぞれの団体に属する会員の方等の内容にもよって、それぞれ趣旨、目的に合わせまして助成をさせていただいているものです。区としても、この事業には助成をという判断を一つ一つしつつ、出させていただいているものと認識しております。","id":"exchange-031"},{"speaker":"山村委員","kind":"質問","question":"それから、次に、１３０ページの母子保健指導費のほうから質問します。地方自治として、これから何ができるのかということ、お考えのほうを聞かせてほしいと求めました。","respondent":"市岡企画財政課長、青山品川区保健所長","answer":"公益的な目的があって、補助対象とすべき事業が、どういう対象事業があるかによって決めているものです。声が大きいところにたくさん行くという性格のものではございませんので、その点だけ、ちょっと一言補足します。これを予算化することにつきまして、検討いたしておりますので、その結果を待ちたいと思います。","id":"exchange-032"},{"speaker":"山村委員","kind":"質問","question":"次の質問に移らせていただきます。１２８ページの予防費のほうで、後のケアというのはどのように行っているのかを、ちょっと教えてほしいと求めました。","respondent":"寺西品川区保健所保健サービス課長","answer":"検査の結果は、一人ひとり個別に保健所の医師が説明しております。あるいは保健師等、ほかの周辺の事情等を聞きたいようなことについても、申し送っているところです。","id":"exchange-033"},{"speaker":"山村委員","kind":"質問","question":"いわゆる性病に関するところでは、区は助成というか、補助は行ってはいらっしゃらないんでしょうか、どうなんでしょうか。エイズ等を含めて、教えてほしいと求めました。","respondent":"寺西品川区保健所保健サービス課長","answer":"民間でやればおそらく５,０００円から１万円かかると思うんですが、その他ももちろん保健所の事業ですので、無料でやっております。","id":"exchange-034"},{"speaker":"山村委員","kind":"質問","question":"次に、１２９ページの環境衛生費の猫の去勢不妊手術費助成で、ちょっとお聞きしたいんですが、たしか川崎市は１００％助成されていて、無料だったと思うんですが、品川区の現状を教えてほしいと求めました。","respondent":"田中健康課長","answer":"１１月の１カ月間に、こちらから獣医師会の協力を得まして、区民の飼っている猫の去勢不妊手術の一部助成をさせていただいているものです。助成内容といたしましては、去勢手術が３,０００円、不妊手術が６,０００円の助成ということでさせていただいているところです。","id":"exchange-035"},{"speaker":"山村委員","kind":"質問","question":"ですから、今後、あまり野良猫が増えない対策のためにも、去勢手術、不妊手術のほうは、もう少し助成を手厚くしていただければと考えています。本日は、いろいろと雑多な質問をさせていただいて、勉強不足のところがあったと思いますが、ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"藤原委員","kind":"質問","question":"私は、衛生費の１２８ページ、感染症予防費について、あと時間がありましたら１３８ページの工場等集団化共同化事業経費について、お伺いします。運転手から、エイズと行政とのかかわり合いについて、お話を伺いました。","respondent":"寺西品川区保健所保健サービス課長","answer":"エイズを発症する１０年ぐらい前にＨＩＶ感染症にかかるわけですが、このところもずっと一貫して増加傾向にありまして、６００名程度。ただ、去年から今年に関しては、ほぼ横ばいでありました。","id":"exchange-037"},{"speaker":"藤原委員","kind":"質問","question":"症状が５人に１人ぐらいしか出てこないと伺っておりますが、その次が、１５歳から１９歳になっているという現実があります。この辺の、いわゆる１５歳から１９歳に対しての対策というものは、何かお考えか尋ねました。","respondent":"寺西品川区保健所保健サービス課長","answer":"性感染症全般について、性教育と言ってもいいかもしれませんが、続けていくことが非常に大事なことだと思います。いわゆる１０代の後半からということになりますと、やはり中学校、高等学校あたりからの教育のほうをますます盛んにしていきたいと考えています。","id":"exchange-038"},{"speaker":"藤原委員","kind":"質問","question":"その知識といいますか、１０代全般に徹底的に知識を教えることによって、やはり予防というか、自分自身が対策しようと思うと思うんです。これから教育委員会とタイアップして教えていく、その辺も教えていかなくちゃいけないと思うんですけれども、いかがか尋ねました。","respondent":"寺西品川区保健所保健サービス課長","answer":"まさに委員のご指摘のとおり、私どもも、ＨＩＶの講演、その他でやっているんですけれども、今後とも、中・高校で、教育委員会等とタイアップで進めてまいりたいと考えています。","id":"exchange-039"},{"speaker":"藤原委員","kind":"質問","question":"現在、エイズの感染等は、人数等は大分わかっているんですけれども、品川区においての性器クラミジア感染に関しての人数、もしくは、検査に来られた方で、感染している割合というのがわかれば、教えていただけますか。","respondent":"寺西品川区保健所保健サービス課長","answer":"１４件、１８件ですが、決して全例報告ではありません。ご指摘のように、検査を受けられた方の５％ぐらいに見つかることがあると言われていますように、ほんとうの件数はさらに多いものと考えております。","id":"exchange-040"},{"speaker":"藤原委員","kind":"質問・要望","question":"できるだけ、検査をしてほしいという形で推奨していただくことを要望したい。どうか、これからもご努力をしていただけるように、お願い申し上げまして、質問を終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"},{"speaker":"鈴木（真）委員","kind":"質問","question":"ですから、国のほうにも多少の動きが出ているんじゃないかと思いますので、この辺、お答えを。ですから、どういうふうに考えていくのか、お答えをお願いします。","respondent":"新美保健高齢事業部長、中山清掃リサイクル課長、長田区民課長、市川産業振興課長","answer":"ここでもう１回ご答弁しますが、特別養護老人ホームとしての土地の活用については、考えておりません。現在は、社会保険庁の方針がまだ未定ですが… 約１万６,０００所帯、３万３,０００人のエリアですけれども、モデル回収事業を７月から開始いたしました。先ほどの… 最近の特徴は、事件のあった周囲に、緊急情報という形でチラシ等の配布もしています。いずれにいたしましても、被害があったときには… ２点目の、その辺のことについては、かなり検討を進めてあります。","id":"exchange-042"},{"speaker":"鈴木（真）委員","kind":"質問","question":"都南総合病院に関して、今後、保健高齢事業部が担当するということでいいんですか。では、お答えのほうを、保健高齢事業部、お願いします。","respondent":"田中健康課長","answer":"都南総合病院の跡地に関することですが、向こうが社会保険庁の財産ですので、当面は、私ども健康課のほうで情報収集の窓口に当たりたいと思ってあります。","id":"exchange-043"},{"speaker":"武内委員","kind":"質問","question":"１３３ページのリサイクル推進費、次の１３４ページの清掃総務費について、お伺いしたいと思います。環境相談費のところで、いろいろ苦情と陳情ということで、２２６件ほど寄せられておりますが、この主立った内容についてお教えください。","respondent":"金井環境課長","answer":"環境相談費の関係の相談の内訳ですけれども、２２６件のうち、騒音関係が約１００件で４５％です。次に、悪臭関係が４４件ぐらい、約２０％近く、そのほか煤煙ですとか、振動、その他もろもろというような内訳になってあります。","id":"exchange-044"},{"speaker":"武内委員","kind":"質問","question":"騒音の苦情の件で、お伺いいたしますが、例えば、工場等の音が夜間うるさい等の、こうした苦情を受けた際に、どのような対応をされていらっしゃるか、説明を求めました。","respondent":"金井環境課長","answer":"苦情の私どもの対応状況ですけれども、発生源である事業者なり、工場なり等々にきちっと指導してまいります。そういった流れで、行っているところです。","id":"exchange-045"},{"speaker":"武内委員","kind":"意見","question":"ほとぼりが冷めるといいますか、しばらくしますと、また同じようなことを繰り返すような方もいるやに聞いております。もし最終的にそれでも改善の余地がないような場合には、どのようなことをされるのか、説明を求めました。","respondent":"金井環境課長","answer":"住民のそういった方々にも均一に対応というのは非常に難しいわけですが、発生源者がはっきりしていれば、そこに指導する。ただし、私どもは、そういう事業者には、一生懸命継続してそういったことでお願いをせざるを得ない、こんな状況です。","id":"exchange-046"},{"speaker":"武内委員","kind":"質問","question":"トラブル等にならないような形で、いろいろ対応のほう、よろしくお願いいたします。それからもう１件、電車の音がうるさいというような場合に、どのような対応をしたらよろしいんか尋ねました。","respondent":"金井環境課長","answer":"まず苦情者からいただいた内容を鉄道会社にきちっとお伝えし、鉄道会社からその苦情者に対してきちっと対応していただくようにお願いをしております。基準をオーバーしていれば、在来線については、できるだけＪＲに誠意を持って対応するよう指導しています。","id":"exchange-047"},{"speaker":"武内委員","kind":"質問","question":"実際にそうしたケースで、当然経費がかかるものですから、ＪＲのほうもすぐに対応していただけないことのほうが多いかなと思うんです。区で少し助成をするとかというお考えは、今のところ、ありますか尋ねました。","respondent":"金井環境課長","answer":"発生をさせているといいますか、そういったところが、それなりの対策をするというのが基本だろうと思います。区としては発生源者でございませんので、それに対して何かというのは、大変難しいというふうに考えております。","id":"exchange-048"},{"speaker":"武内委員","kind":"質問","question":"続いて、リサイクル推進費についてお伺いしたいと思います。ああいうのはどうなっているんでしょうかということで、区でいろいろ苦情等で上がっているかどうか、説明を求めました。","respondent":"中山清掃リサイクル課長","answer":"いわゆる集積所に出されている資源物回収ですけれども、特に昨年の後半、古紙相場が上がって以降、古紙を中心に、今、委員おっしゃられたような行政回収の前の抜き取りの苦情、通報というものが、清掃リサイクル課および清掃事務所のほうに寄せられるようになってきてあります。","id":"exchange-049"},{"speaker":"武内委員","kind":"質問・要望","question":"そうしますと、具体的に何件ぐらいというのがわかれば、教えていただきたい。区のほうで、それに対する対応をどのようにされているかということを、説明を求めました。","respondent":"中山清掃リサイクル課長","answer":"対応ですけれども、実態的対応をまず強化していこうということで、集積所等への抜き取り禁止の表示をしたです。清掃事務所と私どものほうで連携を取って、抜き取り防止のパトロールを行いまして、あるいは資源の没収を行ったです。","id":"exchange-050"},{"speaker":"武内委員","kind":"質問","question":"どなたか１人管理する方の名前で申請して、もしあれば、その場ですぐにもらいたいような意識が働くんです。言われた際にすぐに対応できるようなことは、今後、お考えがいかがかお聞きしたいと思います。","respondent":"中山清掃リサイクル課長","answer":"清掃事業移管後ですが、既に３,０００枚余のカラスネットの配布も行って、対応してきたところです。これは、そういったより機敏な対応ができるのかについては、事務所との連携で検討してまいりたいと考えています。","id":"exchange-051"},{"speaker":"井上委員","kind":"質問・要望","question":"１３３ページ、１４０ページの緊急地域雇用対策費について、お伺いをいたしたいと思います。具体的には、どのようなことをされているのか、教えてほしいと求めました。","respondent":"島袋品川区保健所衛生課長","answer":"食品衛生許可監視指導というのは、飲食店等のお店の許可、それと更新のときの更新許可をしております。","id":"exchange-052"},{"speaker":"井上委員","kind":"質問","question":"品川区のほうで、表示義務づけとか、そのようなチェックをするところはどこになるのか教えていただけますか。","respondent":"島袋品川区保健所衛生課長","answer":"大変失礼いたしました。違反があるのかないのか、例えば添加物の違反とか、そのような仕事も一緒にこの事業の中でやっております。","id":"exchange-053"},{"speaker":"井上委員","kind":"質問","question":"消費者の信頼を失うような事故や事件があったわけですが、このようなことに対しまして、品川区としてはどのように対応されてきたのかお伺いします。","respondent":"島袋品川区保健所衛生課長","answer":"ＢＳＥに始まりまして、偽牛肉表示とかございまして、品川区もそうなんですけれども、国全体として、都とか保健所を通して、全体で特別に牛エキスの注意をするとか、表示の注意をするとか、こういうことを全国的にやっていまして、品川区もその中の一環としてやっております。","id":"exchange-054"},{"speaker":"井上委員","kind":"質問","question":"そういう公益的な部分であるので、全体的にということなんですけれども、品川区として、食の安全を守るという基本的な考え方は、どのようなものになっているんか尋ねました。","respondent":"島袋品川区保健所衛生課長","answer":"品川区としてといいますか、食品の場合ですと、区だけじゃなくて、広がりますね、例えば、区民がほかの区で買ったり、ほかの区の方がこちらに来たり。そうしますと、広域性の、区特別ということではなくて、通常の監視の中でやっているです。","id":"exchange-055"},{"speaker":"井上委員","kind":"質問","question":"そういったところを、今後、どのように取り組んでいかれる予定か尋ねました。","respondent":"島袋品川区保健所衛生課長","answer":"公表に値するものを、今、検討している最中です。２３区で、そういう他の関連する機関とも協力して、この辺は計画を立てていきたいと考えているところです。","id":"exchange-056"},{"speaker":"井上委員","kind":"質問","question":"そういったことが起きつつあるということで、品川区が表示の義務づけをきちんと守っているんだということを、しっかりと調査をしてほしいと思います。こういった調査する方たちがいらっしゃいますと言いましたけれども、実際には、どのぐらいの方がそういった仕事に従事されているんか尋ねました。","respondent":"島袋品川区保健所衛生課長","answer":"食品科学の技術を持っている職員は、食品衛生監視員と申しまして、保健所保健センターに１３名おります。","id":"exchange-057"},{"speaker":"井上委員","kind":"質問","question":"品川区内のそういった店舗、もしくはいろいろ販売されているところで、１３人で十分だとお考えか尋ねました。","respondent":"島袋品川区保健所衛生課長","answer":"１万軒以上になるんですけれども、３,３００件ぐらいの監視をしています、約半分ぐらいです。１３人が適当か、答えに困るんですけれども、かなりの効果が上がっているのではないかと思われます。","id":"exchange-058"},{"speaker":"井上委員","kind":"質問","question":"全体に網羅されているのかということに不安を持って、そういう資質とかいうことではなく、お伺いをしたつもりでいます。年間計画なのかもしれませんけれども、そういったところに消費者の声を直接入れる機会とか、そういったお考えはいかがか尋ねました。","respondent":"島袋品川区保健所衛生課長","answer":"個別で窓口にも相談が来ますので、アレルギー表示も結構来ます、そういうもので個別に対応しているんです。新しい食品衛生監視指導計画というものを独自でつくって、しかも公表するですので、消費者の声はもちろん入れていきたいと考えているところです。","id":"exchange-059"},{"speaker":"井上委員","kind":"確認","question":"今、指導計画をつくるということで、確認させていただいてよろしいですか。こういった中で、平成１４年度決算におきまして、ごみ収集経費というものがどのぐらいになっているのか、お知らせください。","respondent":"中山清掃リサイクル課長","answer":"平成１３年度で申しますと、非常に粗い計算ですけれども、約６５億円かかっているです。","id":"exchange-060"},{"speaker":"井上委員","kind":"質問","question":"そういった中で、自治体が容器リサイクル法にかかわる収集を担っているわけですけれども、ごみ収集の６５億円という中で、資源回収として、自治体が負担している負担割合というのはどのぐらいになるんか尋ねました。","respondent":"中山清掃リサイクル課長","answer":"これも非常に粗い計算ですけれども、容器包装にかかわるものだけでも１０億円ぐらいになっているのかなと認識しております。これは非常に精緻な計算ではございませんが、そのような認識です。","id":"exchange-061"},{"speaker":"井上委員","kind":"質問・要望","question":"今回は、７月からペットボトルの回収が拡大をされていて、大井ストックヤードもいっぱいになっているということを伺いました。このように、リサイクルを推進することで、自治体の財政が圧迫しているという指摘に対して、品川区では、どのようにお考えか尋ねました。","respondent":"中山清掃リサイクル課長","answer":"動きはありませんけれども、販売時の価格転嫁、あるいは事業者の役割づけを強化する法も出てきております。いずれにしても、区としては、そういう働きかけ、地域に則した発言をしっかりしていきたいと考えています。","id":"exchange-062"},{"speaker":"井上委員","kind":"質問","question":"平成１５年度の事務事業評価の中でも、最終的にごみ減量というのは、発生抑制を考えるべきだと思います。２期目の公募があって、こういう方たちを中心にできればいいと思いますが、今現在はどのような活動をされているんか尋ねました。","respondent":"中山清掃リサイクル課長","answer":"廃棄物減量等推進委員は、基本的に、地域でのリーダーとして実践行動と、その活動を口コミで広げていただきたいです。区で新たな施策も含めて新しい情報をお伝えしていますので、そういうものを広げていただくということを願って活動していただいているものです。","id":"exchange-063"},{"speaker":"井上委員","kind":"質問・要望","question":"今、活動を進められているということですので、この方たちを中心に、やっぱり地域でごみ抑制を考えていくということを、区と区民と、また事業者とともに、一緒に協力しながら進めるということで、ぜひ、頑張ってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-064"},{"speaker":"石田委員","kind":"質問","question":"私は１３８ページ、１３２ページ、お伺いをします。今、現状をどのようにお考えか、そこら辺から説明を求めました。","respondent":"市川産業振興課長","answer":"これまで展開してまいりましたさまざまな商店街振興支援策、今、いろいろな足元を見る必要がある時期に差しかかっているという認識があります。こういった問題、状況に対する認識を持ってあります。","id":"exchange-065"},{"speaker":"石田委員","kind":"意見","question":"それに対して、効果が上がっているのかどうか、そこら辺の点は、非常に言い方は難しいけれども、決してそうとは見えないなと思っているところがある。どうしても商店街と町会を分けて考えていく場面があるから、そこら辺の点の、お考えをお願いしますとの意見を述べました。","respondent":"市川産業振興課長","answer":"そうならないように、そういう視点に立って、スポット的なイベントに対する支援も行っているつもりです。２点目の、地域を挙げた面的な活性化の取り組みというご質問ですけれども、そういう仕掛けが有効ではないかというふうに考えてあります。","id":"exchange-066"},{"speaker":"石田委員","kind":"質問・要望","question":"どうしてももう１点お聞きしたいのは、融資制度が、町会と商店街という部分が必ず分けられているのかなという部分があります。そこら辺の点を含めて、どういう仕組みづくりがあるのかというところのお考えがあれば、お聞かせ願いたい。","respondent":"市川産業振興課長","answer":"あるいは一律に考えを述べるということよりも、商店街の振興を図るということは、十分に考えられると思います。やはり、地域特性なり、商店街の特性ということを踏まえて考えていく必要があるものと思ってあります。","id":"exchange-067"},{"speaker":"石田委員","kind":"質問・要望","question":"１台当たりの想定数、実績があって、その実績の評価をどうされているか。そこら辺を含めて、どのように評価されているか、まずお聞きしたいと思います。","respondent":"金井環境課長","answer":"区商連が考えていた地域との連携、子どもたちとの連携ですとか、こういったものがまだまだこれからかなと考えております。今、このようなものを課題として考えているところです。","id":"exchange-068"},{"speaker":"石田委員","kind":"質問・要望","question":"それが２５０枚たまるまでに、わけがわからないうちにどこかにいっちゃうということで、どうしたらいいだろうと真剣に悩んでいるところもあります。そこら辺の点を含めて、もう一度、お考えを聞かせていただきたい。","respondent":"金井環境課長","answer":"今後、十分にこの辺は検討してまいりたいと考えております。この辺についても、今後十分、その辺も踏まえながら検討していきたいと考えています。","id":"exchange-069"},{"speaker":"南委員","kind":"質問・要望","question":"そして、１９人というのはどういうふうに選ばれたのかというか、決まってきたのか、その辺の経過も含めて教えてほしいと求めました。それから、立ち上がって、来年度、運営する内容についても、準備の途中でいいですから、わかっている段階までのことで結構ですので、説明を求めました。","respondent":"田中健康課長","answer":"そこで、いろいろ私どもも加わって検討させていただいてございまして、平成１６年度末の開設に向けて、今、努力をしています。地域生活支援センターのほうは、日常生活の支援をしまして、いろいろ社会復帰のための自立のお手伝いをするセンターという考え方です。","id":"exchange-070"},{"speaker":"南委員","kind":"質問・要望","question":"その数が今どうなのかをちょっとお知らせいただきたいのと同時に、平成１４年度の派遣数は１９人対象ですから、考え方を伺っておきたいと思います。「平成１６年度を目途に」と書いてあるんですけれども、年度末かどうかを、ちょっと改めて確認したいと思います。","respondent":"田中健康課長","answer":"さっきの作業所のほうも合わせまして、必要なニーズをそういう方に届けられるように、今後とも検討していきたいと思ってあります。今度は地域生活支援センターができます、総合的にどういう形で皆さんの状況に合わせてご支援できるかということを、いろいろ検討している最中です。","id":"exchange-071"},{"speaker":"南委員","kind":"質問・要望","question":"品川区はようやく１カ所立ち上がるという段階ですから、１カ所にとどまらずに、１５万人に１人という国の基準があるそうですから。来所される方の相談がそれなんですけれども、一人ひとりの相談時間が、やっぱり３０分、１時間とかかるわけですから、非常に大変だと。","respondent":"田中健康課長","answer":"ホームヘルプも開始いたしました。いわゆる地域生活支援センターだけがそういうものを受けるのではなくて、連携のもとに、よろしくお願いいたします。","id":"exchange-072"},{"speaker":"木下委員","kind":"質問","question":"第１点に、保健衛生総務費の中の休日診療費について、質問します。受診者数８,９４８人、休日に診療をしに行かれた人数なんでしょうか、どうなんか尋ねました。","respondent":"田中健康課長","answer":"今、委員のご指摘の受診者数ですけれども、これは、私どもが内科、小児科に関しまして、休日に当番制、あるいは固定制で、品川区、荏原両医師会にお願いをしまして、開設していただいているところを、診療された方の数字です。","id":"exchange-073"},{"speaker":"木下委員","kind":"質問","question":"６年ぐらい前の話ですから、クレーム等、どのぐらいあるんでしょうか。休日診療についてご納得されていらっしゃるのか、どうなのか、ちょっとお尋ねしたいと思います。","respondent":"田中健康課長","answer":"いろいろ救急患者がたて込んで対応しきれない等々という事例も聞いてありますが、あるいは、そういうことに対応できるようにしているかと思います。そういうところで、いろいろ、今後の改善を図っていきたいと考えています。","id":"exchange-074"},{"speaker":"木下委員","kind":"質問","question":"すぐにでも行動しなければというのが人情ですから、連れて行って、そういうことになってしまった次第です。対策等をどのように考えていらっしゃるのか、どうなのか、ちょっと教えてほしいと求めました。","respondent":"金井環境課長","answer":"適正数はどのぐらいかというのはなかなか難しいらしいですが、９,０００羽とか、１万羽程度というようなことを言われております。そういったことを踏まえながら、一体的にやっていかないと、なかなかカラスは減らないんではないかと考えています。","id":"exchange-075"},{"speaker":"木下委員","kind":"質問・要望","question":"６時、いっぱい散らかしているものですから、この労力だけでも大変じゃないかなと思っています。幾つかにごみ袋を分けて、品川区指定のごみ袋をつくるような、そういうお考え等はありますか尋ねました。","respondent":"中山清掃リサイクル課長","answer":"まだ、東京都の場合の中で、ほんとうに合った分別と出し方というのは検討していかなきゃいけないと思います。いずれにしても、いろいろ情報を集めながら、今後に向けては工夫していきたいと思います。","id":"exchange-076"},{"speaker":"塚本委員","kind":"質問","question":"商店街がどうあるべきかと、人が考え出すような仕組みをつくろうではないかと、だんだんシフトしてきたように思うんです。そういうことも、やはりこの際、しっかりと見つめ直して、施策の設計をしなければいけない時期に来ているのではないかということで、お伺いします。","respondent":"市川産業振興課長","answer":"これまでの商店街の活性化支援策、いろいろ考える中で、路線型商店街の活性化というものを基本の物差しに据えてきたところがあります。商店街振興を考える必要がある、出てくるであろうということは、受けとめてあります。","id":"exchange-077"},{"speaker":"塚本委員","kind":"質問・要望","question":"こんなものがありますからどうですかということをやっておったんですけれども、それも、ままならぬというのが現状だと思います。ネットワーク社会ですから、どうですかと投げかけたり、もうまちは興ってこないような気がいたします。","respondent":"市川産業振興課長","answer":"つまり、これは活性化の事業能力なり、経営能力を商店街に求めることが無理な場面もあるんではないかという状況認識を持ってあります。そういう検討を、現在、進めております。","id":"exchange-078"},{"speaker":"塚本委員","kind":"質問・要望","question":"長浜市等があるわけですから、あれから１０年以上たっているわけですので、地域の特性に合わせて人が頑張っているところがあると思うんです。早稲田は早稲田なりにやっているところがあると思いますので、どうぞ、ネットワークを活用していただきたいということが一つ。","respondent":"市川産業振興課長","answer":"そしてまた、区内共通商品券の発行など、区内の商業振興全体に係わる事業を行ってあります。その意味で、私ども、品川区の商業振興、あるいは商店街の活性化の支援策を進めるに当たっては、重要なパートナーであるという認識を持ってあります。","id":"exchange-079"},{"speaker":"塚本委員","kind":"質問","question":"要は、パートナーという言葉しか出てこなかったわけだけれども、実際に、何を期待して、何を向こう側から願われているかということ。そのやり取りも、歴史があるわけですから、主な点は言ってもらわないと、先に話が進まないというふうに思います。","respondent":"市川産業振興課長","answer":"全体のスケールメリットを活用してやったほうが有効であろうというような、個別の単会でできないことを、一つ連合組織で行っていくことがあります。行政側からすると、そこが一番、区商連に対して期待をしているところであると、私自身、考えてあります。","id":"exchange-080"},{"speaker":"塚本委員","kind":"質問","question":"商店街所々の声では、区商連にとどまることを真剣に考えなければいけないというようなことを議論されているのはご存じのとおりです。適切な施策が打てないと思いますけれども、改めて、伺います。","respondent":"市川産業振興課長","answer":"そういう今の現状を、何とか解決したいということで、私どものほうに協力要請を行ってきた経緯があります。区商連のほうに、現在、専門家を派遣しています。","id":"exchange-081"},{"speaker":"塚本委員","kind":"質問・要望","question":"人も汗をかいて、リターンがしっかり取れるような体制になることを支援していただきたいということを願って、質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-082"},{"speaker":"川西委員","kind":"質問・要望","question":"平成１４年度の実態について、お伺いいたします。それから、今後の経緯、そういうことを伺いたいと思います。","respondent":"小林品川区保健センター保健サービス課長、田中健康課長、中山清掃リサイクル課長","answer":"現状では、診断書発行業務は、ほかでできないような方々、福祉施設に入所の方とか、障害者に限って実施しております。… 昭和４７年の種痘の第１期の接種の折に、残念ながら障害が発生した、健康被害が発生した件です。支給額、年間、４４０万円等を国のほうから受けて… ７月の区長会におきまして整理されたことは、ない区も相互に連携して、共同処理ということはうたわれておりません。","id":"exchange-083"},{"speaker":"川西委員","kind":"質問・要望","question":"それから、健康相談のことは、就職する際に診断書を取る内容のものですか。ですから、民間の医療機関でも出るから、いいんじゃないかということか尋ねました。","respondent":"小林品川区保健センター保健サービス課長","answer":"保健所での健診対象にならない方への栄養指導、相談といったことですけれども、やはりこれからは、健康づくりプランに基づきまして、地域の中でどんどん、お年寄りからお子さんまで、すべての方を対象に栄養指導、食についてのことを普及させていきたいと考えております。","id":"exchange-084"},{"speaker":"西本委員","kind":"質問","question":"来年４月から開始されるということで、今現状として、どういうところまで進んでいるのか。それから、今回、歳出のほうで、３１４万５,１００円出ているんですけれども、これはどういうところで使われているのかを、質問します。","respondent":"田中健康課長","answer":"訪問診療を必要とする区民へ対応可能な医師を紹介するなどのことを、品川区医師会、荏原医師会のほうに委託して行っているものです。最初は立ち上げのための検討費用が、その後、平成１２年度からは区独自で両医師会に委託をして進めているものです。","id":"exchange-085"},{"speaker":"西本委員","kind":"意見","question":"どういうところでこれを使われようとしているのか、現状としてどうなっているのか、ご説明をお願いいたしますとの意見を述べました。","respondent":"田中健康課長","answer":"今、委員ご指摘の東京都の事業というのは、医のほうではなくて、現在、私どもが検討中のかかりつけ歯科医のほうの事業ということでよろしゅうございましょうか。","id":"exchange-086"},{"speaker":"西本委員","kind":"意見","question":"実際、やる側では非常に怖いんだと、大きな事故につながるんだというようなことをおっしゃってました。そこら辺の考え方を説明を求めました。","respondent":"田中健康課長","answer":"いろいろな形でご支援いただいている部分も、なかなか対応しきれる方が少ないということで、検討中です。そういうことで、今の委員のご意見も含めて、これからしっかり検討してまいりたいと考えています。","id":"exchange-087"},{"speaker":"西本委員","kind":"質問","question":"ですから、品川区として、専門医というものを配置する。この情報については、入っていますか尋ねました。","respondent":"田中健康課長","answer":"ただ、今回、検討組織の中では、まだそこまで議論に至っておりません。しっかりした体制をつくりたいと考えていますので、今後の検討をということで、ご答弁にさせていただきたいと思います。","id":"exchange-088"},{"speaker":"西本委員","kind":"質問・要望","question":"ですから、しっかりと専門家の方たちと話をして、進めていただきたい。そこら辺のお考えといいますか、特に障害を持っておられる方の予防というところで、何かお考えはありますか尋ねました。","respondent":"田中健康課長","answer":"障害児、あるいは障害者の方限定でのお話ということでは、なかなかまだ具体的な事業展開をしてございません。関係のところを含めて、今後のかかりつけ医の機能も十分、そちらのほうもにらんでいかせるように検討してまいりたいと思います。","id":"exchange-089"},{"speaker":"西本委員","kind":"意見","question":"先ほどの話も含めて、治療だけではなく、予防というところにも焦点を合わせていただいて、何かしら、品川区として対策をとっていただけるように、ぜひともお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-090"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"９月末で経過措置か終了ということに対しては、改めて周知はされたのかどうかについて、１点、お聞きしたいと思います。何％ぐらいで、何人いるのかということについて、わかったら説明を求めました。","respondent":"寺西品川区保健所保健サービス課長","answer":"９月の段階、それからそれ以前の段階で、新聞等、その他、それから、区の場合も広報で説明したところです。７割近い予防接種率ですが、移行措置のときに１割前後に落ちた時期の区の状況というのは、全国と同様の状況ではないかと考えております。","id":"exchange-091"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういう悲しいことが起こらないようにということで、ぜひ、周知に努力していただきたいというのか１点。１５歳から２４歳までの方は、これをどう上げていくかというところは、取り組みを進めていただきたいと思うんです。","respondent":"寺西品川区保健所保健サービス課長","answer":"これが予防接種法に基づく９０カ月までの予防接種ができるわけですけれども、プリントをつくりまして、呼びかけたところです。ただ、法外の予防接種の費用に補助をしていくかどうかというのは、なかなか困難なところがあると思います。","id":"exchange-092"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"このことを、１点、お聞きしたいと思います。そして、どのぐらい減量になったのか、教えてほしいと求めました。","respondent":"中山清掃リサイクル課長","answer":"今後、一つ検討していかなきゃいけないのは、費用負担のあり方も考えなければいけない。こういう中で、品川区としてのごみ減量を進めていきたいと考えています。","id":"exchange-093"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"可燃ごみの４割と言われている生ごみの資源化計画を、やはり今、立てるべきなんじゃないかと思うんです。堆肥化したものをどうするかということが、こういうところから始めていったらいかがかなと思うんですけれども、いかがか尋ねました。","respondent":"中山清掃リサイクル課長","answer":"平成１２年度から、機械を設置して全校で実施をして、２８０ｔ近くの生ごみがリサイクルされてきている。これは教育委員会のほうでの施設の維持管理の対応という考えがあろうかと思いますけれども、今、回収をして。","id":"exchange-094"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"生ごみの資源化計画、これについて、やはり、今こそ立てていくべきなんじゃないかと思うんですけれども、これについては、いかがか尋ねました。","respondent":"中山清掃リサイクル課長","answer":"生ごみ処理機の助成であるとか、こういうことでの減量も、計画には入れてあります。ただ、いろいろなこれからのそういう技術的な進展だとかを見て、計画を立てることについては、こういう動向を見て研究してまいりたいと考えています。","id":"exchange-095"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"今、どんなところでできるかというところから進めて、そしてやっぱり、この中で、住民の意識も変わってきますので、できるところから一歩ずつやっていくことが、それを進めることになると思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-096"},{"speaker":"田中委員","kind":"質問・要望","question":"私は、清掃事業全般につきまして、１３４ページ以降の部分で、お伺いをしたいと思います。３年間で約２６％のごみの減量がなされたということとか、資源回収量が２倍になった、さまざまな成果を伺ってまいりました。","respondent":"中山清掃リサイクル課長","answer":"これを２０年、３０年もたせるということから、５０年近くもつのではないかと。ごみが減ったからといって、決して安心はできない、こういうふうに聞いているものです。","id":"exchange-097"},{"speaker":"田中委員","kind":"質問・要望","question":"そういった将来のことも見据えての意識づけというんでしょうか、協力の求め方として、どのように対応されているのか。それぞれの減量推進委員の方は、どこまでそういった問題を認識されていらっしゃるとお考えなのか、お聞かせほしいと求めました。","respondent":"中山清掃リサイクル課長","answer":"そもそも後処理ではなくて、いかに出てくるごみなり廃棄物を未然に減らし、リサイクル量すら減らすのかというのが重大になってまいります。なぜなのかということも含めた地道な、丁寧な広報、周知を充実させていきたいと考えています。","id":"exchange-098"},{"speaker":"田中委員","kind":"質問・要望","question":"先ほど来、お話がありますように、どうしてもコストの問題が出てきてしまいます。将来、来るであろうそういった問題に積極的に対応していくんだという、その辺のお考えをお聞かせほしいと求めました。","respondent":"市岡企画財政課長","answer":"今、委員がご懸念になったような事態が生じないように、これからの財調協議をきちんとやっていかなければいけないと考えています。自主的な財政運営が実現できる仕組みに、財調を改革していく、こういう基本姿勢で臨んでいきたいと考えています。","id":"exchange-099"},{"speaker":"中島委員","kind":"質問","question":"私は、１３１ページの「健康づくりプラン２１」策定・推進事業費、１３３ページの街角花壇維持費、ここについて質問します。ですから、健康づくりプラン２１というのは、私も非常に期待しているところなんです。","respondent":"田中健康課長","answer":"１３の地域センター管内、それを実際にこのプランに基づいて進めていこうということでございまして、進め方の協議に入りつつあるところです。今、２カ所ほど具体的に、地域センターのほうも連携しまして、まちのほうにいろいろご相談に入っている状況です。","id":"exchange-100"},{"speaker":"中島委員","kind":"質問","question":"この推進事業費として５４５万６,５７７円というふうに計上されているわけですけれども、現在、２カ所の中で、どのぐらいの方がかかわっているんか尋ねました。","respondent":"田中健康課長","answer":"特に地域センターの中のふれあいサポート活動と連携してもっていこうということで、現在のところ、進めておるところです。現在まだ皆さんと相談中ですので、これから先、具体的なところを図っていきたいと思ってあります。","id":"exchange-101"},{"speaker":"中島委員","kind":"質問","question":"これから具体的なところを図られるということなんですが、これは、たしか決算になっていますから、これだけの費用がかかっているわけですから、区民の方に波及する何らかの形というものがあったと思うんですが、それをお知らせください。","respondent":"田中健康課長","answer":"失礼いたしました。いわゆる区民会議という形で検討させていただいた中の費用、それから、いわゆる策定費用というふうにごらんいただければと思います。","id":"exchange-102"},{"speaker":"中島委員","kind":"質問","question":"一人ひとりに合った生活習慣病の予防のための支援というのが挙げられておりますが、この辺はもう既に実行されていることがあるのかなと思うんです。これは、一般質問でも、私も質問させていただいた中にも、少しご答弁があったような気がしますが、これは別の分野で、何かありますか。","respondent":"田中健康課長","answer":"１期につきまして、３カ月間で１６回という形で、食の問題での調理実習という形でメニューを組ませていただいてあります。ますます広がるように、現在、２期目の募集をしています。","id":"exchange-103"},{"speaker":"中島委員","kind":"意見","question":"その３番目に、ねたきりとか、痴呆の予防ということで事業を展開するとあります。これに対しては、どのようなことを計画されているか、お話しくださいとの意見を述べました。","respondent":"田中健康課長","answer":"これをどのような形で進めるかということで、いわゆるまだ介護までいかない方を、いかないようにするために身近で支え合う。これからいろいろ協議をして進めようということを、現在、構想中の段階というふうにご理解お願いしたいと思います。","id":"exchange-104"},{"speaker":"中島委員","kind":"質問・要望","question":"毎日そこに通っていると伺いまして、守るだけではほんとうの健康な高齢者をつくるということではないなというのを、非常に感じたんです。このことについてのご感想、また、これからの対策というものを、ちょっとお聞かせほしいと求めました。","respondent":"田中健康課長","answer":"一人でやるのはなかなか苦しゅうありますので、各地域でそれぞれ目標をつくり、向かっていっていただきたいと考えております。地域ではふれあいサポート活動もまた活発化しそうですので、地域のいろいろな事業と合わせて、健康づくりも身近に繰り広げたいと考えています。","id":"exchange-105"},{"speaker":"中島委員","kind":"提案","question":"そういったものも取り上げ質問させていただいたんですが、よくうちの藤田委員がいろいろな提案をさせていただいているんですが、これは要望します。１３３ページの街角花壇の維持費、７８５万円という予算が取られているわけですけれども、区内に何カ所ぐらいあるんか尋ねました。","respondent":"松代道路公園課長","answer":"街角花壇ですけれども、今、区内に３０カ所ほどございまして、年５回ほどの植えかえ等で、維持管理をしています。","id":"exchange-106"},{"speaker":"中島委員","kind":"質問","question":"水やりとか、そういったものは道路公園課で管理をされているんでしょうか。今後増やすとすれば、どのような条件が必要なのか、説明を求めました。","respondent":"松代道路公園課長","answer":"ふれあい花壇のほうは、みなみ児童遊園のほうで、区民から募集しました１３団体が、四季折々、皆さん花を植えていただいている。駅前花壇につきましては、先ほどの街角花壇と同じように、民間委託でやっているところです。","id":"exchange-107"},{"speaker":"中島委員","kind":"質問","question":"もう一つ、どのような条件があったら、この街角花壇ができるんか尋ねました。","respondent":"松代道路公園課長","answer":"まちのいたるところにそういった花壇があるのが望ましいだろうということで、いろいろと民間のご協力も得ながら、土地をお借りしてつくっております。今のところは３０カ所ですけれども、ご相談等に乗りまして、まちにそういった花壇を増やしていきたいと考えているところです。","id":"exchange-108"},{"speaker":"中島委員","kind":"質問","question":"ふれあい花壇というのがあるということなんですが、たしか、今、花のボランティアも募集をしていると思うんです。今後の大切な課題ではないかなと思うんですが、そういった計画というのは、考えられているか尋ねました。","respondent":"松代道路公園課長","answer":"平成１４年度から始めたばかりです。区のほうで話をつけて、自主の管理の中でどうだろうかという提案等があれば、それは相談に乗っていきたいと考えています。","id":"exchange-109"},{"speaker":"中島委員","kind":"質問・要望","question":"やはり、高齢者といっても、今はほんとうにストレスの多い社会になってきております。こういった施策というのはとても大事だと思いますので、今後またますます充実していくように要望していきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-110"},{"speaker":"土井委員","kind":"質問・要望","question":"それをフレークにしてリサイクルを図っていくという過程の中の収集ですから、そういうことを考えた上で、ちょっと聞かせてほしいと求めました。きちんと行われているべきときだったんじゃなかろうかなというふうに思うものですから、どうなっていたのかなということ、お伺いをしたい。","respondent":"中山清掃リサイクル課長、桑村人事課長、市川産業振興課長","answer":"もういろいろな比重の変更だとか、エコスポットでは新たな出し方、メーカーすら判別できるというふうな流れが出てまいりました。したがいまして… 清掃事務所に働く職員の関係です。前期３年間につきましては、本年４月からは、清掃事務所のほうに行っているわけです。いわゆる製造業のデータベースづくりということで取り組んでまいりましたが、一つには、こういうことを目的としてございました。","id":"exchange-111"},{"speaker":"土井委員","kind":"質問・要望","question":"それは全体的なものも含めて決まっていかないはずですから、その意味では、どういう形になっているのか。必ずしも、品川区だけでお話ができる代物ではないのではないかという思いもあるものですから、よろしくお願いをしたいと思います。","respondent":"桑村人事課長、市川産業振興課長","answer":"ここ数年につきましては、いわゆる定年制における退職につきましては、特に採用しなくても足りるという判断をしています。その辺は変わるわけですけれども、私どもの区としては、そういう判断をしています。 ２年前ほどから始めましたビジネスカタリストという外部の専門家を活用すること、そういったいろいろな方の協力をいただきながら、この問題に解決にチャレンジしていきたいと考えています。","id":"exchange-112"},{"speaker":"土井委員","kind":"質問・要望","question":"今のところ関係ないというので済むのか、済まないのかということも含めて、ちょっとお聞かせをほしいと求めました。その辺の方向性みたいなものも、何か一言ありましたら、お聞かせをほしいと求めました。","respondent":"桑村人事課長、市川産業振興課長","answer":"その意味で、ルールが変わらなければ、その時点での必要人数というのを、私どもの区のほうで配置せざるを得ないだろうと思ってあります。私どもの区の中でも、一定の過員がある状態ですので… 今後の基本的な方向性につきましては、委員のご指摘をいただいた点、私どもも、そういうことを考えて事業を進めてまいりたいと思ってあります。こういったことも活用しながら、進めてまいりたいと思います。","id":"exchange-113"},{"speaker":"土井委員","kind":"質問・要望","question":"助役会、２００６年にはスムーズにいけるように、その辺を進めていただきたいということを要望だけにとどめておきます。終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-114"},{"speaker":"林（宏）委員","kind":"確認","question":"東京二十三区清掃一部事務組合関係のお話をお聞きしたいんですけれども、助役でよろしいかなということを、最初に確認をします。全く白紙の状態、付則に書かれた平成１７年度末に協議をしてと、文字はなっているわけですけれども、現在はどうなっているか、簡単に説明を求めました。","respondent":"濱野助役、島袋品川区保健所衛生課長、山口品川清掃事務所長、中山清掃リサイクル課長","answer":"区長が出席をして、議論してまいりましたけれども、この中で議論をしているという最中です。現時点で、今… 今、委員がおっしゃいました特定建築物についても、これはビル衛生管理法に基づいてやっているところです。これは… 大規模建築物廃棄物の保管場所等設置指導費の関係ですが、その事業所の中で、いわゆる廃棄物をどういうような形で処理をされているか。… 大井清掃作業所に絡むご質問です。２３区の家庭から出てきている、これを中間処理し、下水放流する施設です。","id":"exchange-115"},{"speaker":"林（宏）委員","kind":"質問","question":"どこどこはやっている、どこどこはやっていないでいいですから、区の施設に対して、そういう衛生上の指導をしているかどうかだけ、後で。もうごくごくわずかしかやってないし、民間業者が持ってくるし尿は受け入れてないわけですから、その辺、あるのかどうかだけ聞かせてください。","respondent":"濱野助役、中山清掃リサイクル課長、島袋品川区保健所衛生課長","answer":"したがって、自治会館に東京二十三区清掃一部事務組合が入る必要ないというのが、私どもの認識です。東京二十三区清掃一部事務組合のああいう組織の形態が… 両清掃事務所において提出していただいた再利用計画書というのもありますので、これとの連携も含めてやっていきたいと考えています。今現在７人… 区有施設につきましても、一般施設と同様に、衛生指導をしています。","id":"exchange-116"},{"speaker":"林（宏）委員","kind":"質問","question":"それは中古物件ということになるんでしょうから、区長会での議論の中に加えてほしいと思うんで、ぜひお願いをしておきたいと思います。残った部分だけ、お願いします。","respondent":"島袋品川区保健所衛生課長","answer":"区有施設に対する衛生に関する苦情ですが、ございません。","id":"exchange-117"},{"speaker":"須貝委員","kind":"質問","question":"１３７ページ、１３８ページ、質問します。建設業とありますけれども、その経営状況の実態をどのように考えていらっしゃるか、それをお願いいたします。","respondent":"市川産業振興課長","answer":"経営状況の実態となりますと、これの捕捉というのはかなり難しい話かと思います。ただしその結果はどうかと申しますと、もうこの五、六年、お天気のマークで言いますと、ずっと曇りのマークがともり続けているという状況です。","id":"exchange-118"},{"speaker":"須貝委員","kind":"質問","question":"どんどん支援をして、品川区内でつくり、品川区内で販売するシステムを構築するような施策に対して助成をするべきではないでしょうか。その変更というお考えはどうか尋ねました。","respondent":"市川産業振興課長","answer":"スポット的なイベント支援だけに終わるのではなくて、そういう全体の仕組みの中でイベントの支援なんかも位置づけて、そういうものとして指導。今後、一層、力を注いでまいりたいと思います。","id":"exchange-119"},{"speaker":"須貝委員","kind":"質問","question":"せっかく３３万人の区民がいらっしゃるんですから、それをみんなで考えていってあげるということも、大事な時期じゃないかなと思います。何とか新しい事業をつくってあげるような、そういう取り組みの仕方も考えてほしいなと考えていますけれども、その辺いかがか尋ねました。","respondent":"市川産業振興課長","answer":"基本的な認識のところで、かなりちょっと私どもと異なるところがあると思うのが、私の実感です。そういうところをいろいろ組合せをして、実効性のある産業振興策というものを進めていきたいというのが、私どもの考え方です。","id":"exchange-120"},{"speaker":"須貝委員","kind":"提案","question":"これは第１の質問なんですけれども、現在の清掃サービスを実行できる条件で契約しまして、品川区のために働いていただく方法はないものでしょうか。品川区としては、民間でできることは民間に任せるという方向、それはまた産業振興の一環にもなると思われますが、いかがか尋ねました。","respondent":"中山清掃リサイクル課長","answer":"さらには、そもそも行政との役割分担というところを、十分に見極めていかなければいけないと考えています。役所が直接やるという部分を、できるだけ見極めて圧縮していくというのが、今後の方向性かなと考えています。","id":"exchange-121"},{"speaker":"金高委員","kind":"質問","question":"私は、成果報告書の１２８ページ、予防費、そして時間がありましたら、同じく成果報告書の１３３ページの緑化推進ということでお尋ねいたします。あるいは、そういうシステムがあるのかどうか、その辺をまずお聞きしたいと思います。","respondent":"寺西品川区保健所保健サービス課長","answer":"国の取り組みということになりますと、ＳＡＲＳと天然痘が１類感染症といいまして、一定の強制力を持った感染症に指定されております。そして、区でも、保健所を中心に、もしＳＡＲＳが発生した場合には、統一的な行動がとれるようにと、今、努力しています。","id":"exchange-122"},{"speaker":"金高委員","kind":"質問・要望","question":"ＳＡＲＳの場合には、どちらかというと、接触でなくて、たしか空気感染ではないかと思うんですけれども、その辺はどうなんでしょうか。その辺のところを教えていただいて、即対応できるような態勢がとれるかどうかも含めて、ご答弁願いたいと思います。","respondent":"青山品川区保健所長","answer":"インフルエンザと同時に流行することも考えられるものですから、１０月２１日号の区報で、区民の方々にお知らせする予定になっております。近日中に検討会を持ち、１０月末ないし１１月の初めにやりまして、そのような予定になっております。","id":"exchange-123"},{"speaker":"金高委員","kind":"質問","question":"これで質問を終わります。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-124"},{"speaker":"中塚委員","kind":"質問・要望","question":"私からは、１３０ページ、妊婦健診についてと、１３９ページ、緊急地域雇用対策費について伺いたいと思います。案内の際に、出産にかかわるさまざまな悩みが寄せられていると思いますが、主たる内容を教えてほしいと求めました。","respondent":"小林品川区保健センター保健サービス課長","answer":"具体的な妊娠の相談というよりも、やはり一般的な、これからのサービスについてとか、そういったことが主です。最初の妊娠届の段階の相談というものは、それほどまだ深刻なものはございません。","id":"exchange-125"},{"speaker":"中塚委員","kind":"意見","question":"この中には、およそ１４回ほど、定期健診を受けるように書かれておりました。そのほかにもいろいろかかってくるとは思いますが、一人の女性が子どもを出産するのに、どれぐらい費用がかかっていると把握されておりますかとの意見を述べました。","respondent":"田中健康課長","answer":"子どもさんを産む診療所といいますか、医療機関等にもよりますが、私どもとしましては、総体で２０万円から４０万円の幅の中が一般的かと考えています。","id":"exchange-126"},{"speaker":"中塚委員","kind":"確認","question":"しかし、実際に生まれてきた赤ちゃんの数は、１.３人と、この数字のことを一つ確認したい。実際に生まれた赤ちゃんの数の差ですけれども、主な理由は、どういったものが寄せられているのか尋ねました。","respondent":"榎本行財政改革担当課長","answer":"これは、実際にアンケートに答えた方の子どもの人数が１.３人です。教育費の部分が約４割ぐらい、それから出産年齢の部分が３割ぐらいで、仕事の負担というのが２割程度かなという感じです。","id":"exchange-127"},{"speaker":"中塚委員","kind":"質問・要望","question":"家ではいつも１人、臨月が近づくとますます不安になる孤独な毎日を送っておりますと、こう話してくれました。無料の妊婦健診の回数の拡大を、ぜひやってほしいと求めましたけれども、いかがか尋ねました。","respondent":"田中健康課長","answer":"いろいろな形で機能して、サービスを全体として、区として展開しているというふうにお考えいただきたいと思います。ですから、現在の妊婦健康診査助成の回数等は適当なものと、私どもは認識しています。","id":"exchange-128"},{"speaker":"中塚委員","kind":"質問","question":"妊婦健診を１回増やすだけの予算は、およそ１,３００万円ほどあれば十分可能ではないかと思います。健診の回数を拡大すべきと思いますが、再度、ご答弁をお願いします。","respondent":"田中健康課長","answer":"何回拡大をすれば少子化に歯止めがかかるかということは、ちょっと難しいといいますか、私どもの立場だけでは分析できないと思います。さまざまな要素がということですので、私は、今の健康診査の回数が、必要最小限十分だと考えております。","id":"exchange-129"},{"speaker":"中塚委員","kind":"質問・要望","question":"現行は２回ですけれども、ぜひ、回数の拡大を要望したいと思います。こういった制度があるんだということを、ぜひ改善してほしいと求めましたけれども、いかがか尋ねました。","respondent":"田中健康課長","answer":"委員のお言葉を返すようで恐縮ですが、品川区の国民健康保険に加入されている方へ、出産育児一時金支給のお知らせというのも、先ほどの母と子の保健バッグに、１枚きちっと入っておりまして、十分、水際で周知はさせていただいておるところです。","id":"exchange-130"},{"speaker":"中塚委員","kind":"質問・要望","question":"ぜひ、そこのところはよく伺っていただいて、出生届を出す際に、もう一度徹底していただければと、これは要望で結構です。助役に見解を伺いたいんですけれども、今後の子育て事業に対する見解について、一言だけ述べてほしいと求めました。","respondent":"中尾根企画部長","answer":"日本での対応をどうしていくべきなのかということで、社会の構造を、もう一度改めて考え直していく必要があるんではないかということです。その中で、さまざま施策を打つべきではないか、このような考え方から、第三次長期基本計画が成り立っているです。","id":"exchange-131"},{"speaker":"中塚委員","kind":"質問・要望","question":"１３９ページの緊急地域雇用対策について、伺いたいと思います。今日までの実績について、お伺いしたいと思います。","respondent":"榎本行財政改革担当課長","answer":"各地方公共団体が創意工夫に基づいた事業を実施する中で、雇用、就業の機会の創出を図るという目的で行われているものです。全体計画としましては、今のところ、品川区全体で５２０人の雇用を計画しています。","id":"exchange-132"},{"speaker":"中塚委員","kind":"質問","question":"５２０人の雇用増を目指していて、２４０人増えたとご説明いただいたんですけれども、２４０人についての内訳を教えてほしいと求めました。正規なのか、非常勤なのか、年齢であれば、どういったものがあるのか、職種はどうなのか、内訳をご説明を求めました。","respondent":"榎本行財政改革担当課長","answer":"この雇用の人数につきましては、要件として、６カ月未満の雇用というのが要件になっておりますので、臨時的な任用が主だと思います。事業の内容からして、電算セットアップですとか、いろいろな年代層も含めた上での雇用が図られていると考えております。","id":"exchange-133"},{"speaker":"中塚委員","kind":"質問・要望","question":"私も、この間、中小企業の方々とお話をしたり、品川区の雇用について伺いました。２４０人実績がされて、全体としては５２０人の拡大を求めておりますけれども、その辺についてはいかがか尋ねました。","respondent":"榎本行財政改革担当課長","answer":"これは、あくまでも臨時緊急的な雇用の創出を図る事業ということでやっておりますので、実際上、区が独自に創意工夫に基づいた事業で雇用を創出するというものです。","id":"exchange-134"},{"speaker":"中塚委員","kind":"提案","question":"社会全体で、雇用をどうやって増やしていくのか、社会をどうやって増やしていくのか、私たち品川区にも、大きな課題ではないかと考えています。私も、これから一生懸命勉強して、提案もしていきたいと思いますので、今後ともどうぞとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-135"},{"speaker":"三上委員","kind":"質問","question":"１３４ページ、時間がこれくらいでいけるかどうか、簡単なほうからちょっとお伺いしていきたいと思います。現状をどういうふうに分析されているのか、これをお伺いしたいと思います。","respondent":"田中健康課長","answer":"それから、野良猫の数ですが、実際上、調査の部分では、把握ができない状況です。今、いろいろな形の情報を収集しておりまして、これから何らか手を打てることを検討したいところです。","id":"exchange-136"},{"speaker":"三上委員","kind":"質問・要望","question":"だけれども、現実に、どういう結果になったのか、これをお伺いしたい。料金体系は幾らですと、こういうようなことで返事を出せばいいわけですから、そういったことについての工夫というものができないかどうか。","respondent":"上山ＩＳＯ担当課長、田中健康課長、山口品川清掃事務所長、中山清掃リサイクル課長","answer":"その成果ですけれども、平成１４年度につきましては、７月１日から９月１８日まで実施をいたしました。いずれも７月から９月の３カ月間の合計ですけ… 各地域で実施をしまして、それから、ガイドラインをつくるような考え方を持っておるようです。こういう形の流れを見ながら… 大体、１カ月程度以上待っていただいたところがあるところにつきましては、大変申しわけないと考えています。","id":"exchange-137"},{"speaker":"三上委員","kind":"質問・要望","question":"細かくお伺いしたいと思いますけれども、これは、旭川市の消費者協会に行って６００円で買ってきた袋です。お金をかけてどうのこうのとかじゃなく、取り組んでいっていただきたいなと思いますけれども、いかがか尋ねました。","respondent":"金井環境課長","answer":"レジ袋の関係については、いろいろな施策とか、いろいろな方法があろうかと思います。今現在のシステムは、まだ始まったばかりですけれども、十分、参考にさせていただいて、今後のレジ袋削減に役立たせていただきたいと考えています。","id":"exchange-138"},{"speaker":"三上委員","kind":"質問","question":"それは、よくわかりました。ですから、必ずしも空になったものを、またキャップし直せと、私言っているわけじゃありませんから、そのことだけ申しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-139"},{"speaker":"須藤委員","kind":"質問","question":"４９.８％、４０歳以上ですから、それがほんとうに品川区民の健康状態であるのかどうか。医療機関は自由診療になりますという形で宣伝をされているんですけれども、このあたりは、どういうふうに取り扱っているんか尋ねました。","respondent":"田中健康課長","answer":"一応、４０歳から４５歳まで、節目に５年間で全員の方に受けていただけるように、節目健診という形で、メニューに盛り込ませていただいております。区民健診の中で、品川区においては、節目の方は５年間ですべて検査を完了していただけるという仕組みだけは持ってあります。","id":"exchange-140"},{"speaker":"須藤委員","kind":"質問・要望","question":"ここで出ている３万６,０００人ぐらいの数字は、よく皆さんが健診をしているほうになるのかどうかということを、教えていただきたい。その辺のところ、何か因果関係があるかどうか、説明を求めました。","respondent":"田中健康課長、青山品川区保健所長","answer":"区民健診という形で位置づけていますのは、職域で受けられる方、それから医療にかかっている方は除外してカウントをさせていただいているところです。その把握がしっかりできていないもので… 肺がんについてですが、大ざっぱに分けまして２種類あります。喫煙をしている方は肺がんになる確率が、たばこを吸わない方に比べて、５倍ないし６倍というところが出ております。","id":"exchange-141"},{"speaker":"須藤委員","kind":"質問・要望","question":"ほんとうにそのあたりをどういう形でもっていって資源にしていくかということも、よく考えてほしいと求めましたが、いかがでしょうか。１０月１日からディーゼル車が規制になりましたけれども、まだ１週間か１０日じゃわからないのかなと思うんですけれども、いかがか尋ねました。","respondent":"上山ＩＳＯ担当課長、中山清掃リサイクル課長、金井環境課長","answer":"平成１４年度、初めて区が取り組みをいたしましてから、区にお住まいの家庭のほうにも声を広げております。非常に苦労するところではありますけれども… 生ごみの行き先で、なかなか土地がないと堆肥等が難しいという中では、いわゆる培養ガス化というのも大きな選択肢になってくると言われております。… ディーゼル自動車による規制の効果ですが、間違いなく効果は出ていると思います。","id":"exchange-142"},{"speaker":"須藤委員","kind":"質問・要望","question":"サマールックキャンペーンですけれども、考え方はわかるんですけれども、区民の皆さんが窓口に来たときに、そのときそのときでぴしっと。区民の方が来られて、サマールックキャンペーンの印象がいい形だということで、ＰＲしていくという方法を考えてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-143"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/623169?Template=document&Id=1218#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2003-01-01&TermEnd=2003-12-31"}],"sourceMeta":{"pages":0,"characters":113756,"voices":335}},{"id":"h15-20031014-4","meetingId":"h15-c-settlement","date":"2003年10月14日","dateIso":"2003-10-14","committee":"決算特別委員会","time":"午前１０時０６分～午後６時４２分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を139件整理しています。","topics":[{"id":"topic-01","title":"平成１４年度品川区一般会計歳入歳出決算","agenda":"平成１４年度品川区一般会計歳入歳出決算","exchanges":[{"speaker":"林（和）委員","kind":"質問・要望","question":"それから１４０ページと１４１ページにわたりまして放置自転車対策、それから、４点簡単に質問させてほしいと求めました。中高層建築物は延べ面積が１万m2以上の場合は東京都の認可が必要となっておりますけれども、２３区中、まず１点お伺いをいたします。","respondent":"浜脇住環境整備課長","answer":"この建物の建築の説明会というのを紛争条例では義務づけてありますが、その中で、東京都の場合には住民からの申し出があった場合に説明会を行うと。働きかけているというところでございまして、区としては、それについて今努力中です。","id":"exchange-001"},{"speaker":"林（和）委員","kind":"質問","question":"続きまして２点目の放置自転車対策についてお伺いをいたします。そういう中にありまして、利用率１００％の大井町、そして青物横丁、西大井の今後の対策、どのように考えているのか、お知らせ願いたい。","respondent":"奈良交通安全担当課長","answer":"今後の対応ですけれども、それからカラーコーンを固定するコーンバーを使って物理的にとめられないような措置を今とる予定をしております。あわせて、どういう方がそこへとめているのか実態調査をする予定にしております。","id":"exchange-002"},{"speaker":"林（和）委員","kind":"意見","question":"それと同時に、この大井中央公園の周辺の放置自転車ですけれども、年に１回か２回注意があってやったのでは、効果は全然ないわけですよ。","respondent":"奈良交通安全担当課長","answer":"もしそういうのが事実であれば、私のほうから管轄の警察署のほうに要望してまいりたいというふうに思っております。多いところは月７回から８回ぐらい撤去作業をしておりますけれども、従来は、台数的には撤去はかなり増えているというような状況です。","id":"exchange-003"},{"speaker":"林（和）委員","kind":"質問・要望","question":"次の屋外広告物の取り締まり、違反ポスター等撤去、そして違反看板の撤去につきまして質問をさせてほしいと求めました。平成１６年度の品川区の予算編成に関する政策要望の中にも、このことにつきまして、区の考え方をお聞かせを願いたいと思います。","respondent":"奈良交通安全担当課長","answer":"区は平成６年から五反田駅と大井町駅につきましては、それからＮＴＴ、警察と合同で年１回パトロールを実施しています。今、私どもも平成１６年度から実施できるように、今実施要綱の作成を急いでいるところです。","id":"exchange-004"},{"speaker":"林（和）委員","kind":"質問・要望","question":"時間がなくなりましたので、最後の道路占用物件、袖看板につきましてお尋ねをいたします。その結果の５０％の違反についてはどういうふうに考えているのか、その不公平さはどういうふうに今後考えていくのか、ちょっとお知らせいただきたい。","respondent":"岩田管理工事課長","answer":"現在調査中ですので、正確な数値はまだ出ておりませんけれども、委員ご指摘のような数値になっております。社会的な不公平感を是正するために、今後も催促してまいります。","id":"exchange-005"},{"speaker":"中島委員","kind":"質問","question":"そして１４５ページ、それとともに１４７ページ、大体この辺のところから関連した質問をします。高齢社会における対策、またすべての人に優しいまちづくり対策としてはどのような協議がなされているか、簡単にご説明ください。","respondent":"奈良交通安全担当課長","answer":"今委員ご指摘の、高齢者に対する安全教育というお話ですけれども、区は年１回、高齢者の対策会議というのを設けておりまして、その中で、高齢者を守るためにいろいろな安全教育とか、それから高齢者の安全教室等を一生懸命実施をしています。","id":"exchange-006"},{"speaker":"中島委員","kind":"質問・要望","question":"最近、高齢者の方で難聴になっている方、こういったことに対しての対策はどのようにとられているのかなということを一つ後でお伺いしたいと思います。こういった点も考慮を今されて、街の中を点検されているのかどうか、お答えしてほしいと求めました。","respondent":"奈良交通安全担当課長、岩田管理工事課長","answer":"今、委員ご指摘の高齢者対策ですけれども、確かに高齢者の方で難聴の方もいらっしゃると思います。管内には２８カ所の高齢者に優しい信号を設置しておりますので、事故に遭わないように通っていただくためにも… 車いすの方からの強い要請に基づきまして、平成１０年代からもう既に設置しておりまして、区でもほとんどの部分でゼロcm段差が行われております。","id":"exchange-007"},{"speaker":"中島委員","kind":"質問・要望","question":"ほんとうにあそこは悩みの種だということで伺っておりますので、しっかりと品川区の住民のために点検のほうもよろしくお願いしたいと思います。その空気抜き塔の真ん前のマンホールが２カ所ともそれが飛ばされて、この辺のところは、まだ区としてはつかめてないんか尋ねました。","respondent":"矢部下水道河川課長","answer":"それが建設されますと、暫定貯留量ですけれども、３万ｔ貯留できる予定になっております。それが平成１５年度末ということになっておりますので、その対策が今後待たれるかなと考えております。","id":"exchange-008"},{"speaker":"中島委員","kind":"質問","question":"もうその真ん前からこうマンホールが噴き出しちゃったわけですから、ぜひ説明をしてほしいと、このように言われました。自分で自費で買ってきたという、そういった声があったんですが、これは自分で買うしかないんか尋ねました。","respondent":"矢部下水道河川課長、松代道路公園課長","answer":"最初に説明会の質問ですけれども、原因を調査しまして、地元の方にわかりやすい形で説明していきたいと考えています。 土のうは、従来各地に設置をしてまいりました。再度調整をさせていただきまして、設置の方向で取り組んでまいります。","id":"exchange-009"},{"speaker":"中島委員","kind":"質問・要望","question":"やはりその先まできめ細かに行き届いているのかどうかというところまでぜひ確認をしていただきたいなと、一つは要望しておきたいと思うんです。ぜひそのようにしてほしいという要望があるんですが、いかがか尋ねました。","respondent":"岩田管理工事課長","answer":"現在の道路は、東急線の大井町線の線路の振った関係で、１０ｍちょっと北側の団地側に寄った仮設道路になっております。現在、東急線の架台の撤去作業を行っておりますけれども、これが全部撤去をされますと、もとの位置に戻って区道化される、こういう計画です。","id":"exchange-010"},{"speaker":"中島委員","kind":"質問","question":"続きまして、先ほど林和也委員が駐輪場のことで、違法駐輪のことで触れておられたんですが、それに関連して１問質問します。商店が新しく建設をする場合、大きな商店なんかの場合は、駐輪場を設置する指導はされないんか尋ねました。","respondent":"浜脇住環境整備課長","answer":"私どものほうで規模に応じて、商店ビルあるいは事務所ビルあるいはマンション等の設置のときには中高層にかかわる分として開発指導上で駐輪場の設置を義務づけてあります。","id":"exchange-011"},{"speaker":"菊地委員","kind":"質問・要望","question":"確認申請が７４１件というふうになっていますけれども、これに即したものかどうか、この辺ちょっと具体的な名称として教えていただきたい。ちょっと教えていただきたいというのと、これが民間の確認会社はどのように確認をしていくのか、この辺の流れについて教えていただきたい。","respondent":"片田建築課長、浜脇住環境整備課長","answer":"委員ご質問の条例と建築確認、あと民間との絡みについてご説明いたしたいと思います。民間ができたときは、そういう事前の一応協議をどのように対応していくか。 日照阻害、やっぱりどうしても今２階、３階建てのところにマンション等の高い物が建つと日照被害があるのではないかというようなことです。そんなことが今一番多く出てあります。","id":"exchange-012"},{"speaker":"菊地委員","kind":"確認","question":"実際に関東近県１７社あるということですけれども、例えば品川区ですと、ちょっとその辺の考え方を教えていただければというふうに思います。開発環境指導要綱の第２条の中に、きちんとした条例化ができないのかどうか、この２点についてお願いをいたします。","respondent":"片田建築課長、浜脇住環境整備課長","answer":"そのうち、株式会社形式をとっているのは１０社ほど、あと、財団が７社ほどありますけれども、いずれも技術的な審査だけで対応しているです。認識していただいた上で、私どものほうも既存の条例あるいは要綱について… それから、建築のそういった説明会を代行して行うという業者が今ここのところ増えているといいますか、そういうケースが増えてまいりました。","id":"exchange-013"},{"speaker":"菊地委員","kind":"意見","question":"解体ですとか代行会社、代行業者、ぜひ条例そのものが持っている精神が生きるような指導をぜひ強化をしてほしいと求めました。それから、ここもぜひシステム上もきっちりと強化をして、あいまいな形で条例が適用されることがないような方策をぜひ練ってくださいとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-014"},{"speaker":"大沢委員","kind":"質問","question":"私は、１４６ページの公園についてお伺いをいたしたいと思います。緑豊かなまちづくりという区のスローガンのもとで、どのような公園像というのを行政の区の側がお持ちなのか、まず最初にお伺いをしたいと思います。","respondent":"岩田管理工事課長","answer":"これは、あるいは説明会をしまして、地域の声を吸い上げながら要望に基づいてつくってまいりました。いろんな住民の方の意見もありますので、その時代時代のニーズに応じた公園へと私どもは大規模改修時には公園を変化させていくという考えです。","id":"exchange-015"},{"speaker":"大沢委員","kind":"質問","question":"今、幅広い層のニーズに合ったというお話の上からお伺いをいたしますと、例えば子どもの遊び方も変わってきております。そのような、そのような方向性というのは区の側でお持ちでしょうか、ご答弁をお願いいたします。","respondent":"岩田管理工事課長","answer":"私どもは住民説明会の中で、この公園はじゃあこういうふうにしたほうがいいんじゃないかという一致点を見つけ出すように努力をしております。区はそういう説明会の場や、皆さん方の議論の素材として使っていただいて、いろいろ考えていただくという手法を現在とっております。","id":"exchange-016"},{"speaker":"大沢委員","kind":"質問","question":"次に、しながわ水族館のことで二、三お伺いをいたしたいと思います。２回のリニューアルを経ましたが、その２回のリニューアル後の収支といいますか、費用に対する効果はどのような状況になっておりますか尋ねました。","respondent":"松代道路公園課長","answer":"リニューアルを平成１３年に行いまして、その後の収支等の関係ですけれども、入館者数で申し上げますと、平成１３年６８万人になってあります。平成１３年のときにはサメ水槽ということで新たに設けたものですけれども、非常に好評を得まして入館者が増えたという状況にあります。","id":"exchange-017"},{"speaker":"大沢委員","kind":"質問","question":"入館者数を、その流れでお伺いしますが、入場券の販売という部分で、コンビニで売ったりＪＲの駅、また私鉄の各駅で売っているようなことを見受けられますが、そこで一番売れるといいますか、効率のいい、一番出のいい場所をちょっとお教え願えればと思います。","respondent":"松代道路公園課長","answer":"通販といろいろやってありますが、やはり一番水族館本館の次に多いのが、今言いましたＪＲ東日本の駅頭です。非常にこういった意味では重要な販売網だというふうに承知しています。","id":"exchange-018"},{"speaker":"大沢委員","kind":"質問","question":"次に、バスの件なんですけれども、当該荏原地区、差し当たりまして平塚中学校前に、昔巡回バスの停留所があったんですが、それが廃止されました。改修といいますか、修理のご予定または新たにつくり直す予定がおありなのでしょうか、ご答弁をお願いいたします。","respondent":"松代道路公園課長","answer":"いろいろとバスの運行に当たっては検討してまいりますけれども、当面は直行便の運行でまいりたいというふうに考えてあります。したがいまして、当面はこのボンネットバス２台を中心としまして運行を継続してまいりたい、このように考えておるところです。","id":"exchange-019"},{"speaker":"大沢委員","kind":"質問","question":"いずれにいたしましても、トロリーバスにしてもしかり、施設にしてもしかり、我が区が持っている、唯一の水族館、ここの水族館の今後のあり方の議論をさらに行政の側でもお願いをいたしまして、質問を終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"大西委員","kind":"質問","question":"私は、成果報告書１４１ページの土木管理費、駅周辺放置自転車対策事業についてお尋ねします。この放置自転車撤去返還等の委託費というのは、これは毎年のランニングコストということで理解してよろしいか尋ねました。","respondent":"奈良交通安全担当課長","answer":"そのとおりです。","id":"exchange-021"},{"speaker":"大西委員","kind":"質問","question":"その時点でＪＲ側に６２台、そして阪急のところに約１１２台、そして丸井側に２００台を超える不法駐輪がありました。一体それはどのような調査をして、特定の小売業者のために不法駐輪しているということを思われたのか、説明を求めました。","respondent":"奈良交通安全担当課長","answer":"今、委員のほうからるるご指摘がございましたけれども、私どもは今年の２月に職員を出しまして、朝の１０時から夜の８時まで実態調査をいたしました。そのときに調べた調査結果が、いわゆるほとんどが特定の商店を利用する買い物客というふうにお話を申し上げたところです。","id":"exchange-022"},{"speaker":"大西委員","kind":"質問","question":"そうすると、その８時以降に残っている自転車というのは、特定の小売業者じゃないという考え方でよろしいか尋ねました。","respondent":"奈良交通安全担当課長","answer":"確かに今委員ご指摘の８時以降に残っている自転車については、あるいは付近に来ているパートとか、いろいろな近くのお店に来ている方がおとめになっているとは当然考えられるというふうに思います。","id":"exchange-023"},{"speaker":"大西委員","kind":"質問","question":"夕方にＪＲ前のエスカレーター、そこに不法駐輪されているものがあって、人一人通るのがやっとというのが毎日毎日繰り返されるわけです。これは未必の故意に当たるのではないか、刑事事件にもなり得るものだと思いますけれども、その見解はどうか尋ねました。","respondent":"奈良交通安全担当課長","answer":"確かに私どももそこに放置されている自転車があるのは承知をしております。午前３時間、午後２時間配置をして、今そこをとめさせないようにというような措置もとっていきたいなと今考えているところです。","id":"exchange-024"},{"speaker":"大西委員","kind":"意見","question":"そういうときにけがをするということが起こり得る、そんなように思っているわけですね。そのまま放置しておくということは、行政による未必の故意に相当するのではないかと思うわけですけれども、その見解を聞かせてくださいとの意見を述べました。","respondent":"奈良交通安全担当課長","answer":"今、委員ご指摘のように、未必の故意というお話がございましたけれども、確かに私どもは道路管理をしております。そういった委員ご指摘のように、これはいろんなご議論もあるでしょうから、今ここでコメントは差し控えたいというふうに思っております。","id":"exchange-025"},{"speaker":"大西委員","kind":"質問","question":"ちょっと質問の形を変えますが、それは一体いつどのような形でお話をされて、どういう回答が帰ってきているのか尋ねました。","respondent":"奈良交通安全担当課長","answer":"本年の２月にその経過を確認したところ、いまだ検討しておりますというお話でございました。したがって、区として何かできるのか、まだ早急にいろいろな面で検討して、何らかの対応策をとっていきたいというふうに思っているところです。","id":"exchange-026"},{"speaker":"大西委員","kind":"質問","question":"２月からずっと私が一般質問するまでの約半年間、阪急が考えますと言った後に、行政がそのものを放っているというふうに私は思うわけですね。それを撤去しないと子どもが危ない、６カ月間もそのまま問題を放置しておくというのはどういうふうな観点から６カ月間も置いておくんか尋ねました。","respondent":"奈良交通安全担当課長","answer":"委員ご指摘のように２月から全然交渉していないんじゃないか、そういうことで６カ月間放置したわけではございませんけれども、交渉はしていなかったです。","id":"exchange-027"},{"speaker":"大西委員","kind":"質問・要望","question":"だから、これは着実に着手していかないと、ぜひ前向きに真摯に対応していただきたいというふうに思います。これは要望でございまして、お答えは結構です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"藤原委員","kind":"質問","question":"１５０ページの区民住宅費についてお伺いしますが、こういうことがわかりましたというのがあったら、担当課として教えていただけますか。","respondent":"田村住宅課長","answer":"やはり今回募集、また今回既存の区民住宅大体５０m2から６０m2台、主に間取りも２ＬＤＫから３ＤＫと画一化したものが既存の区民住宅でした。","id":"exchange-029"},{"speaker":"藤原委員","kind":"質問・要望","question":"この募集に当たってですが、在住の方プラス在勤の方を募集したと思うんですけれども、在住の方と在勤の方の割合というのがわかれば教えていただきたいのと、あと、なぜ在勤も募集の中に入れたのかということを説明を求めました。","respondent":"田村住宅課長","answer":"親在住者で約１５％ということで、やはり品川区に１回住んで、そのような状況です。","id":"exchange-030"},{"speaker":"藤原委員","kind":"質問","question":"ちょっと質問が戻っちゃうんですが、今ファミーユ下神明は何人の方が住んでいらっしゃるんでしょうか。まだ入居して間もないんですけれども、現在の時点で家賃の滞納者はもう出ているんか尋ねました。","respondent":"田村住宅課長","answer":"現在、全体の世帯数を合算しますと４００名弱という人数が住んでいるです。３カ月の方が出てきたということで、条例上３カ月ということなので、現在のところは滞納者については聞いておりません。","id":"exchange-031"},{"speaker":"藤原委員","kind":"質問","question":"募集のときに、たしか入る方の収入によって何段階かに分けられて家賃が決まっていると思うんですけれども、何段階か分かれた今の人数の構成がわかれば教えていただけますか。","respondent":"田村住宅課長","answer":"現在、申込時点の分布でお答えしますが、１５年間社会情勢が変化なければ同一の家賃という設定をファミーユ下神明にはしております。第４、第５がそれぞれ１２％から１９％ということで、そのように思います。","id":"exchange-032"},{"speaker":"藤原委員","kind":"質問","question":"それによって安定した税収も期待できるということが１点あると思うんですけれども、世帯主が３８歳から３９歳が多いということで、地域とのかかわり合いということについてはいかがか尋ねました。","respondent":"田村住宅課長","answer":"ご存じのとおり、ファミーユ下神明建設に当たっては、いろいろ近隣の関係からご要望等ございました。自治会を入れて、相互に連携・協力しながら地域に溶け込んでほしいというような形で、現在調整を進めているところです。","id":"exchange-033"},{"speaker":"藤原委員","kind":"質問","question":"新しく募集が始まりました西五反田の住宅ですが、今の応募状況はいかがでしょうか。地域とのかかわり合いということにおいて、西五反田の場合はどのようにやっていこうと思っていらっしゃるか尋ねました。","respondent":"田村住宅課長","answer":"東館のほうを９月１日から１６日ということで、規模が４００戸規模ですので倍率的には４倍でしたが、そのように思っております。先ほどのファミーユ下神明と同様、それを区が支援をして地域の町会と連携を密にして図っていく必要があるんじゃないか、このように考えております。","id":"exchange-034"},{"speaker":"原委員","kind":"質問・要望","question":"それから１４４ページ、１４５ページ、河川費との関連でお伺いをいたします。第２回定例会のときに一般質問させていただいて、非常に大切なことなんで、その後の状況を教えていただきたい。","respondent":"矢部下水道河川課長、中島街路事業担当課長、松代道路公園課長、奈良交通安全担当課長","answer":"それから戸越幹線流域であります西品川地区、それから南大井地区、こういうところが浸水被害が発生しております。ただ、道路の本格的な整備ということになりますので、年度内につきましては多少ご不便をかけるようになるのかなというふうには考えてあります。ただ… 道路冠水のご質問ですけれども、西大井五丁目が１件、南大井六丁目が１件です。","id":"exchange-035"},{"speaker":"原委員","kind":"質問・要望","question":"昨日も時間にすると１００mmに近い雨が降ってきているという話ですから、その辺はどうなっているのか、お伺いします。夜間の無灯火は５万円以下の罰金という罰則がついているんですけれども、これは摘発なり注意なりはできるんか尋ねました。","respondent":"矢部下水道河川課長、中島街路事業担当課長、奈良交通安全担当課長","answer":"先ほど委員のご指摘のとおり、東京都からは今財政的に非常に厳しいということで、実はそれの工事の延伸の可能性について打診を受けております。… 現在契約して更地になっている部分は約１０カ所あります。植木だとか花を入れられるようなものを全部設置してあるんですけれども、花が咲かない… それから２人乗りとか無灯火、それについては道路交通法上罰則は担保されておりますので、十分それで取り締まりは可能です。","id":"exchange-036"},{"speaker":"原委員","kind":"質問・要望","question":"有効活用される方法を考えていただきたいのと、２０５号線の中でもかなり空地があるんですが、何とか方法がないものなんですか。その要望をどういう形で行ってきているのかというのは、これはどういうふうに生かされるのか、というのをちょっと質問させてほしいと求めました。","respondent":"中島街路事業担当課長、矢部下水道河川課長、奈良交通安全担当課長","answer":"当面は暫定整備になりますけれども、そこをなるべく歩行者の方にご利用いただくというようなことがまず使命かなというふうに思ってあります。… 昨年の８月４日、各建設事務所、管理事務所に要望文を出しております。今２３区に声をかけて２３区全体で何か要望ができないか… やっぱり繰り返し繰り返し注意することはほんとうに大切だと考えています。","id":"exchange-037"},{"speaker":"武内委員","kind":"質問・要望","question":"私は、１４１ページの交通安全対策費と、１４２ページの道路維持費、それから１４７ページの大井町駅周辺地区再開発事業に関連してお伺いします。所管されるのか、鉄道会社のほうがやられるのか、その辺をちょっとお聞かせほしいと求めました。","respondent":"岩田管理工事課長","answer":"踏切の中の維持管理につきましては鉄道側が行うということになってありますので、至急現地のほうを確認をいたしまして、補修するように対策をとるように指示しておきます。","id":"exchange-038"},{"speaker":"武内委員","kind":"質問・要望","question":"西大井駅から列車の本数も非常に増えたものですから、１５分や２０分では大したことはないと思うんですが、非常につながってくるんですね。非常に危険なようなことを現場で目にしたものですから、そこら辺も含めてどのような感じで対策をお考えになっているか、お願いしたいと思います。","respondent":"岩田管理工事課長","answer":"ご指摘の場所につきましては、なかなか鉄道の下に地下道を後から建設するというのは大変な難工事になります。踏切の遮断時間、これの解消が運行の工夫によってできないかどうかも含めて、鉄道事業者のほうと調整を図ってまいりたいと思います。","id":"exchange-039"},{"speaker":"武内委員","kind":"意見","question":"やっぱりどうしても１０分、そういったことは可能なのかどうか、説明を求めました。","respondent":"奈良交通安全担当課長","answer":"通学路は現在８時から９時が通学時間となっておりますけれども、ただ単に例えば１５分延長するにしても、地元の警察を通じて公安委員会のほうにもお話をしていきたいなと考えています。","id":"exchange-040"},{"speaker":"武内委員","kind":"質問・要望","question":"大井町の駅周辺地区再開発事業に関連してお伺いしたいと思いますが、やはりこれもちょっと車いすの方からいろいろ要望がございまして。そういった要望をいただいているんですけれども、そういった対策は、今後どのように検討されるか教えてほしいと求めました。","respondent":"岩田管理工事課長","answer":"あるいはタクシーに乗ったりするのに、ちょうどその１５cmの段差が乗りやすいというふうに言われて、東京都内でこれは統一基準でやっております。乗るということになりますので、そこら辺のところはひと工夫できないかどうか、少し検討させていただきたいと思います。","id":"exchange-041"},{"speaker":"武内委員","kind":"質問・要望","question":"今、そういったお話を伺って、私も全然そういうものを知らなかったものですから、またそういうお伝えをするとともに、また何らかの対策をしていただけるということで、ご要望させていただいて終わらせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-042"},{"speaker":"井上委員","kind":"質問","question":"私からは、１４１ページの土木総務費と、１４６ページ、公園管理費についてお尋ねをいたします。自転車道の整備もあわせて考えていかなければいけない課題なんですけれども、この辺につきまして、区のご見解を伺いたいと思います。","respondent":"奈良交通安全担当課長、岩田管理工事課長","answer":"いろいろな面でキャパシティをつくることが非常に大切だと考えていますけれども、そういう適切な場所もなかなか確保できないという面もあります。… いわゆる自転車道の整備の検討ですけれども、ただ、品川区道は平均幅員が５ｍ程度です。ただ、物理的にそのような空間をつくるというのは極めて困難ですので、今のところ一般道についての検討というものは難しいものと考えております。","id":"exchange-043"},{"speaker":"井上委員","kind":"質問・要望","question":"そういった状況の中で、ちょっと具体的なことになるんですけれども、有料駐輪場の登録について伺いたいと思いますが、大崎駅西口周辺には第１、第２、第３と３カ所の有料駐輪場がありますが、各登録状況を教えてほしいと求めました。","respondent":"奈良交通安全担当課長","answer":"それから、第２駐輪場につきましては８５％です。第３駐輪場、これは道路の高架下ですけれども、これにつきましては２５％の利用です。","id":"exchange-044"},{"speaker":"井上委員","kind":"質問","question":"駅から離れた第３駐輪場、そちらのほうでは当日利用車が３台というがらがらの状況で、閉鎖されていました。片方は１００％で、また今後この有効利用にどのような対策をお考えになっているのか、お伺いをいたします。","respondent":"奈良交通安全担当課長","answer":"今年の５月ごろから試験的運用で当日運用に変えようということで、今現在も実施しておりまして、午前中に１名を配置をしております。大体平均すると４０台から５０台ぐらいの利用はありますので、引き続きこういった試験的実施を引き続きまた実施していきたい。","id":"exchange-045"},{"speaker":"井上委員","kind":"質問","question":"駅から離れていても、少し料金的な付加価値をつけるとか、そういった対策で利用率が上がるかもしれないというようなことも考えられると思うんです。それで、違法駐輪対策にも一助にはなると思うんですが、そういった付加価値をつけるような対策につきましてはいかがか尋ねました。","respondent":"奈良交通安全担当課長","answer":"一応３カ年で終わる予定になっております。見直す時期が来れば、当然見直しすべきだと思いますけれども、今の段階では料金の見直しについては考えておりません。","id":"exchange-046"},{"speaker":"井上委員","kind":"提案","question":"自転車道路整備の先行事例調査を提案しましたけれども、高松市では、今回は建設委員会でも視察を予定しております。品川区では１６３号線を初め道路整備が進んでいますが、これらの道路整備に、区のお考えを説明を求めました。","respondent":"岩田管理工事課長","answer":"自転車帯として２.５ｍ、最低４.５ｍの幅員が要るですので、そのような道路というのは品川区内には残念ながらほとんどない。歩道幅員は３ｍしかございませんので、ルールを守って自転車と歩行者が共存していただくということしかなかろうと考えています。","id":"exchange-047"},{"speaker":"井上委員","kind":"質問","question":"自転車利用者が、駐輪場がなくて、歩道や駅前のスペースに駐輪せざるを得ない状況が今あるわけです。そういった中で、自転車利用者ともに協議会を設置しながら対策を練るべきだと思いますが、そういった協議会の設置についてはいかがか尋ねました。","respondent":"奈良交通安全担当課長","answer":"基本的な３本柱がございまして、それから撤去活動を強化しましょう、こういった３本柱で今品川区はこの放置自転車対策に取り組んでおります。改めていろんなグループが集まっての協議会をつくる必要性は少ないんではないだろうかというふうに考えておるところです。","id":"exchange-048"},{"speaker":"井上委員","kind":"質問・要望","question":"駐輪保管所を整備するという税金の使い方ではない、根本的な対策を市民参加で行っていただきたいということを要望して次の質問にします。こういったことへの対応が図られているのか、また利用者自身が点検する仕組みをつくってはどうかと思いますが、いかがか尋ねました。","respondent":"松代道路公園課長","answer":"私も速やかにできるものから対応して、常に安全に安心して使っていただけるように日々行っております。したがいまして、委員お申し出のとおり、いろいろなそういった改善等の声には私どもも積極的に対応してまいりたいと思っているところです。","id":"exchange-049"},{"speaker":"井上委員","kind":"質問","question":"時間が足りなくなりましたので、少し具体的にお伺いいたします。１６、１７年と公園、この長期的な公園の改修計画というのはどのようになっているのか尋ねました。","respondent":"岩田管理工事課長","answer":"午前中のお答えにもちょっとありましたけれども、やはり時代時代によって区民の方々の公園に求めるニーズというのは変化してきております。","id":"exchange-050"},{"speaker":"川西委員","kind":"質問・要望","question":"成果報告１４４ページ、それから２番目は公共溝渠境界確定事務に関連して、やります。平成１４年度の実績件数、それからこの事業は目的というのは何なのか、おさらいをさせてほしいと求めました。","respondent":"片田建築課長","answer":"道路については、私道、公道これは問いませんけれども４ｍです。それ以前に４ｍ未満であった道路、一応４ｍの道路として整備するといったような内容でございまして、道路の拡幅整備を行っているという内容です。","id":"exchange-051"},{"speaker":"川西委員","kind":"質問","question":"それから４ｍにすべき対象の道路が拡幅されて、ここで時間がないので１点だけ伺っておきたいのですが、戸建て住宅の開発があります。ああいうのはどうなんでしょうかね、警察の取り締まりの対象にはならないんですかとご質問をしたこともありますが、お伺いいたします。","respondent":"浜脇住環境整備課長","answer":"開発指導のほうでは、今の委員がおっしゃったように４ｍ道路を入れて、それが全部接するようにという指導をさせてもらっています。そういう宅地開発の場合、５区画以上あった場合には、車がちゃんと入るように開発者のほうにご指導しております。","id":"exchange-052"},{"speaker":"川西委員","kind":"質問・要望","question":"ですから、ここは要望でとめますけれども、ぜひ今後の対策をお願い申し上げます。あるいは売却等の要請があって、それを何件ぐらいこの平成１４年度中に処理されたのか、伺います。","respondent":"岩田管理工事課長","answer":"あるいは払い下げを行いますので用地を買っていただくか、どちらかの選択肢になりますので、今後順次計画的に払い下げを中心に行っていく予定です。平成１４年度につきましては、売却しました件数としては２件あります。","id":"exchange-053"},{"speaker":"川西委員","kind":"質問","question":"今のご答弁の中で、中断されている場所について放置しておかないで、境界確定が協力していただけない場合、低木を植えるとか植栽をするとかという処置について、調査をなされるかどうか、それだけでいいですから。","respondent":"岩田管理工事課長","answer":"境界確定が確定しているところについては、委員ご指摘の件につきましては対応してまいりたいと思いますが、境界でもめているところにつきましては、さわること自体が交渉の妨げになる場合も中にはありますので、ケース・バイ・ケースで対応してまいりたいと思います。","id":"exchange-054"},{"speaker":"川西委員","kind":"質問・要望","question":"低木でも植えて、やはり少しでも緑の地帯をつくってほしいと求めました。常設的に週に１回あるいは月に２回、２カ月に１回程度、ぜひよろしく。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-055"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"それからもう１点、まず、今の細街路の問題から続けさせてほしいと求めました。自宅部分は自費負担で整備している、ここら辺の兼ね合いというのはどうなっているのかなということからまずお答えをほしいと求めました。","respondent":"片田建築課長","answer":"ただ、その部分が協議をして空間としては４ｍ下がっていただくんですけれども、そういう実態としての現況もたまに見受けられるところがあります。ただ、要綱での整備でございましたけれども、条例化ができないだろうかといったような検討を始めたというような状況です。","id":"exchange-056"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"これは要望にしておきます。ただ、道路に常に置きっ放しにしてしまうということの問題も絡んでくると思うんですけれども、そこら辺の考え方を教えていただければ。","respondent":"岩田管理工事課長","answer":"したがって不法行為になりますので、不法行為で料金を取るということもできません。したがいまして、区では徹底した取り締まりに努力しています。","id":"exchange-057"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"５０cmずつぐらい両側に商品がせり出して、通るところが真ん中１ｍぐらいしかない、そこに自転車がすれ違うときにどうするのか。その辺はどうなんか尋ねました。","respondent":"奈良交通安全担当課長、岩田管理工事課長","answer":"ただ、区としましても、昨年度年４０回ほど警察と合同でパトロールを実施しております。これはもちろん警察との調整も必要ですし、今申し上げたとおり、そういった告発については最後の最後の手段だというふうには考えております。 最近やけに多くなってまいりまして、東京都の２３区の管理担当課長会でも問題にしておりまして、今検討中です。近々結論が出てまいりますが、今のところ非常にグレーなものです。","id":"exchange-058"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"ですから、先ほどおっしゃっていた告発という内容まで考えていってもいいんじゃないかなと、私は個人的には思います。それは、まちづくりの中で安全性を考えても大事な部分ではないかなと思いますので、ぜひその辺もこれから考慮していってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-059"},{"speaker":"南委員","kind":"質問・要望","question":"１４６ページの都市開発費に関係してご質問したいと思います。そして既に完了したもの、この三つに分けて、延べ床面積とヘクタールも教えてほしいと求めました。","respondent":"上野都市開発課長","answer":"それから、開発中のものが３カ所ございまして、約６５万７,０００m2、６５.７haです。１０９.８haでございまして、合計１３地区で２０３万７,０００m2、約２０３.７haです。","id":"exchange-060"},{"speaker":"南委員","kind":"質問・要望","question":"延べ床面積はそのとおり伺いたかったんですけれども、ヘクタールのところは、開発の敷地面積でちょっと教えていただきたかったんです。ちょっとそこのところをもう一度伺いたいのと、いろいろな排熱の関係でどういうふうな、ぜひこれを教えてほしいと求めました。","respondent":"上野都市開発課長","answer":"排熱関係につきましては、個別の数字は申しわけございませんけれどもわからないところがございまして、今のところは出ておりません。開発中のもので約２万９００台、１日当たりトリップエンドと、合計で２万６,７００台となっています。","id":"exchange-061"},{"speaker":"南委員","kind":"質問・要望","question":"ぜひ見解を求めたいと思うんですが、むしろ９月のほうが暑いぐらいでしたが、大変な苦労が私たちが暮らしている中でありました。ですから、改めて見解を伺いたいと思いますし、ちょっと見解を伺いたいと思います。","respondent":"上野都市開発課長","answer":"都市の発展にとって開発事業は不可欠と考えていますが、一方で、ご指摘のように都市再生の重要なテーマというふうに認識しています。大崎駅東口第３地区の開発におきまして、各区画の環境負荷軽減対策に取り組んでございまして、環境に配慮したまちづくりを進めているです。","id":"exchange-062"},{"speaker":"南委員","kind":"質問","question":"どういうふうに考えているのか、省エネ対策、全体的な地球規模の関係で見たときにどうなのかということをちょっと改めて見解を伺いたいと思います。１,４００haに対して、品川区は１.９％程度ですから小さいというふうに認識して、その点について見解をちょっと簡単に。","respondent":"上野都市開発課長","answer":"個々の建物でそういう対応をしていくというふうに申し上げましたけれども、今ヒートアイランド対策の取り組みに関しての検討をしています。そういった取り組みをやりまして、環境負荷の低減に向けた取り組みを進めていきたいというふうに考えてあります。","id":"exchange-063"},{"speaker":"南委員","kind":"質問","question":"大崎地域の６０haとさっきおっしゃったんですけれども、その辺疑問が残るんですけれども、後で伺いたいと思います。膨大な規模のお金をかけて環境を壊して、そしてまた膨大なお金でその対策をとるという、最大の問題だということを指摘して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-064"},{"speaker":"木下委員","kind":"質問・要望","question":"それから１４６ページの都市開発費、１４９ページの住宅費、時間があれば質問させてほしいと求めました。それから要望という形で三、こちらのほうに４,１６４万円というような金額を使ってありまして、この点どうなのかちょっと説明を求めました。","respondent":"松代道路公園課長、市岡企画財政課長","answer":"非常にごみが出やすい、非常に地域から清掃の要望が高いところ、そういったところを主に民間に委託して清掃をしています。特に大井競馬場のほうは、競馬場自体でも清掃等を主にやっておりまして… 競馬会社と話がついておりまして、そういう意味では明確にこの特定財源をきちんと周辺の道路清掃に充てている、こういうことを明示するためにここに記載しているものです。","id":"exchange-065"},{"speaker":"木下委員","kind":"質問・要望","question":"これは要望なんですけれども、車道と歩道との段差２０cmほど違うんですけれども、また歩道のところに電信柱が立っているわけですよ。その現状をどのように考え、また改善のほうをどのようにやっていこうとされていらっしゃるのか、ちょっとお聞かせほしいと求めました。","respondent":"岩田管理工事課長","answer":"通常速度４０kmのスピードで、１５cmの段差があれば、歩行者の生命が守られるという考え方に基づいてこういう構造に全国的になっております。","id":"exchange-066"},{"speaker":"木下委員","kind":"質問・要望","question":"その後、平成５年、これは平成元年からやっています旗の台・中延地区の事業展開の中で含めてやっているという理解をしていいんでしょうか。やはり、密集住宅市街地整備促進事業というのはかなり長いスパンで考えなければならないことですから、実行に移していただければと考えています。","respondent":"浜脇住環境整備課長","answer":"ところが平成１０年の１２月になりまして、危険度が高い地域として二葉三・四丁目等が出てまいりました。そういったものを国や都に申請をすることによって、今後とも精力的に地元の中に入って話し合いを進めてまいりたい、こういうふうに考えてあります。","id":"exchange-067"},{"speaker":"木下委員","kind":"質問・要望","question":"ですからこそ、対策をとっていただけるように、ほんとうにこの決算特別委員会の中でも震災面のことを各委員がいろいろとお話をされています。公園を要望される住民の方々が大勢いらっしゃいますから、こういう事業を絡ませて、ちょっとお聞かせ願えればと思います。","respondent":"岩田管理工事課長","answer":"区では、１人頭公園面積を確保するために公園の新設というのは積極的に行っていきたいとは考えております。ただ、実態上は１ha以上の用地でないと補助金がつかないという制約も一方ではありますので、鋭意検討してまいりたいと思います。","id":"exchange-068"},{"speaker":"木下委員","kind":"質問・要望","question":"前向きなお答えをいただきましたので、ちょっと難しい部分もあるかとは思いますけれども、今後ともひとつよろしくお願いいたします。ちょっと要望を含めて、私はこれで質問を締めします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-069"},{"speaker":"山路委員","kind":"質問・要望","question":"私のほうからは、２点ほどお伺いいたします。１点目は１４５ページ、もう１点は１４６ページ、北品川二丁目京浜急行の新馬場駅北口周辺の整備事業についてお伺いいたします。","respondent":"上野都市開発課長、岩田管理工事課長","answer":"かつてコミュニティ道路があったところかと思いますが、ちょっとその整備に合わせてそのコミュニティ道路を整備するという話を今伺っております。そのコミュニティ道路についてはそういうことです。八ツ山歩道橋から上空を通って品川駅の東口の再開発事業の中で南北に貫通するデッキが駅広のデッキにつながるようになっております。","id":"exchange-070"},{"speaker":"山路委員","kind":"質問","question":"品川区民の方が駅に行くのに多くの方が渡っているんですが、事故があっては絶対いけないと思うんですね。今警察のほうで渡れないようにしてあるということはお伺いしたんですが、もっと高い、その辺はどういうふうにお考えか尋ねました。","respondent":"上野都市開発課長","answer":"地元の町会から、設置についての要望を区長あてにいただきまして、今ご指摘のところあたりにつくるのは非常に難しいというような話を受けてあります。","id":"exchange-071"},{"speaker":"山路委員","kind":"質問","question":"その立っているのが中途半端じゃないですか、どんどん渡っているところがかえって危険じゃないですか、渡れないなら渡れないように。こういう安全対策をやっぱり考えていかなきゃいけないんじゃないかと思いますが、いかがか尋ねました。","respondent":"岩田管理工事課長","answer":"ただ、警視庁本庁との交渉が極めて難航しまして、区としては全責任は警視庁が負うのかということで追及しております。これについては、ここに信号つきの横断歩道を設置してほしいということは言い続けておりますので、様子を見させていただきたいと思います。","id":"exchange-072"},{"speaker":"山路委員","kind":"質問・要望","question":"そのお願い、住民の要望どおりにしていただきたいんですが。この辺はどうなっているか、この辺についてもどういうふうになっているか、ご説明をほしいと求めました。","respondent":"奈良交通安全担当課長、松代道路公園課長","answer":"ただ、いろいろな角度から今検討をしております。その一環として、駐輪場についても検討材料には入っておりますというお話でございましたので、私のほうでも今後ともつくるように。 新馬場駅前の清掃です。よく調査して対応してまいります。","id":"exchange-073"},{"speaker":"西本委員","kind":"質問","question":"１４６ページの公園管理費、それから１４１ページの駅周辺放置自転車対策事業を、またまた質問します。１８７カ所というふうに書いてあるんですが、どういう方がどういうふうに管理されていて、具体的にちょっと説明を求めました。","respondent":"松代道路公園課長","answer":"基本的には規模等も含めまして、大きな民間と直営の区分けはございません。注意の要するところは現在のところは直営であり、比較的民間に付せるもののところについては民間でやっている、そういったところが現状です。","id":"exchange-074"},{"speaker":"西本委員","kind":"質問","question":"比較的大きな公園については管理業者が入ったりということは存じているんですけれども、小さいところの管理はどのようになっているんでしょうか。それはどのように管理をされているんか尋ねました。","respondent":"松代道路公園課長","answer":"若干違いますけれども、もしくは必要に応じて週に４回というふうにしていますけれども、平均して大体週に２回程度はやってあります。先ほどちょっと答弁漏れがありましたけれども、今直営体制でやっている清掃等、順次今見直しをしまして民間委託に移行しています。","id":"exchange-075"},{"speaker":"西本委員","kind":"質問","question":"一時期、管理のほうを地域の方たちにとか、そういうふうに頼んでいるケースもあるというふうにお聞きしているんですけれども、それはどうなんか尋ねました。","respondent":"松代道路公園課長","answer":"公園の清掃等、区民参加の維持管理という形に今年度あたりから少しずつ地域にお願いをしてお話をしています。地域の方々にボランティアを募集しまして、花壇管理、今いろいろ問い合わせも含めて２０件ぐらいがそういった形で進めたところです。","id":"exchange-076"},{"speaker":"西本委員","kind":"質問","question":"公園のところに管理者の名前をきちんと提示をして、品川区はそういうボランティアの申し込みの中でしていただいている方をこれから広げていこうという段階なのか、それと町会等との方たちへの協力体制というのはどのようにされているのかをお聞きしたいと思うんですが。","respondent":"松代道路公園課長","answer":"後者のほうの、地域の方々が近くの公園をできる範囲で維持管理をしていただく、そういった方法で進めていければなというふうに思ってあります。","id":"exchange-077"},{"speaker":"西本委員","kind":"質問","question":"３回と見回ったりということがあるんですが、それがどういうふうな管理になっているのか、そこら辺はどのように対策をしているんか尋ねました。","respondent":"松代道路公園課長","answer":"週に２回程度の清掃をする中で、返して中のいろんなもののごみをとるとか、ネットをかぶせるというようなこともしております。少し特定の人だけではなくて、複数の方々にそういったことをお願いしながら管理をしていければ、このように考えているところです。","id":"exchange-078"},{"speaker":"西本委員","kind":"質問・要望","question":"今後、教育も含めてそういう推進をしていただけると、もっと地域としての動きが活発になるのではないかなというふうに思っております。公園といいますと、子ども用のトイレというのもつくっていただければありがたいなというふうに思いますが、その辺いかがか尋ねました。","respondent":"岩田管理工事課長","answer":"いわゆる一般の公衆トイレとか公園トイレの大便器については、子ども用というのは設置しておりません。車いすの方もその他の方もみんなが使えるトイレ、これは大規模に面積をとりますので、まずそっちを優先して整備しています。","id":"exchange-079"},{"speaker":"西本委員","kind":"質問・要望","question":"そうすると、どういうことになったかというと、路上のほうに自転車を全部並べるような形になってしまいました。ほかのところにどうしても置かざるを得ないという状況になりますので、区のほうとしてはどういうふうにお考えになっているのか聞きたいと思います。","respondent":"上野都市開発課長","answer":"その配置関係とか、より工夫して、そういう苦情が出ないような形での対応や方策を今後のものについては考えていきたいと思います。","id":"exchange-080"},{"speaker":"西本委員","kind":"質問","question":"どういうお客が来るのかというのは当然考えられるわけですから、区としては何らかの指導が必要ではないかなというふうに思います。その努力されているところというのもあるわけですから、再開発という中では、ある程度区のほうもかかわっているわけですから。","respondent":"奈良交通安全担当課長","answer":"私どもに書類が回ってまいりますので、駐輪場をつくっていない、建物であれば……。","id":"exchange-081"},{"speaker":"伊藤委員","kind":"質問","question":"私のほうからは１４１ページの道路公園河川等の監察事務費に関連をして、それから１４５ページの水防対策費に関連して質問をいたします。ですから、こういう事態に関しては品川区が対処すべきだと思いますが、改めてその品川区の考え方を説明を求めました。","respondent":"奈良交通安全担当課長","answer":"管轄する警察と連絡、連携をとりながら、早急に指導警告してまいりたいというふうに考えております。","id":"exchange-082"},{"speaker":"伊藤委員","kind":"質問・要望","question":"先ほどの質問に重なってまいりますが、対処すべきところと、改めて対処方をよろしくお願いいたします。何回か区のほうに要望したようなことも聞いてはおりますけれども、いかがでしょうか、お答えをお願いいたします。","respondent":"奈良交通安全担当課長","answer":"今、子どもの通学路になっている関係もありますので、違法駐車は一列の駐車であっても交通上大きな多大な障害が出るわけです。非常に悪質ですので、よく地元の警察と連携をとって二重駐輪がないように、早急な指導をしてまいりたいというふうに思っております。","id":"exchange-083"},{"speaker":"伊藤委員","kind":"質問・要望","question":"品川区の責任の範囲の中で具体的にどう対処していくのか、そのことをお聞かせいただきたいのと、予想以上の雨量というふうなお話を聞きます。ですから、それから最近のこういう異常気象に対処した上での東京都の下水道の計画の変更はしておりますでしょうかということを説明を求めました。","respondent":"矢部下水道河川課長","answer":"その原因がわかった段階で説明をしてほしいという内容かと思いますけれども、この辺につきましては、報告していきたいというふうに考えております。","id":"exchange-084"},{"speaker":"伊藤委員","kind":"質問・要望","question":"私が質問した内容といいますのは、その範囲の中でどのような対応をなされるのかということをお伺いしたので、改めて答弁をお願いします。そのことをぜひ課長のサイドからも伝えてほしいと求めましたので、品川区の責任の範囲の中でどう対処するかということを改めて説明を求めました。","respondent":"矢部下水道河川課長","answer":"午前中の質問でもお答えしましたけれども、品川区としても、東京都に対して早急に整備を進めてほしいということを申し上げ続けております。そういう中で、引き続き要望を伝えていくという形にしたいと思います。","id":"exchange-085"},{"speaker":"伊藤委員","kind":"質問","question":"それを１００％進めていっていただくことのほうが、これはやっぱりどこかできちんと２３区も、ものを言い続けていかないといけない。もう少し切り分けの部分で踏み込んだ対応を働きかけてほしいと求めましたが、いかがか尋ねました。","respondent":"中谷まちづくり事業部長","answer":"今後ともこの下水道促進の要望については、これは区民の生命と財産を守るという大事な事業であると認識しておりますので、引き続き要望していきたい。こういうことも含めまして、さらに努力を重ねてまいる所存です。","id":"exchange-086"},{"speaker":"伊藤委員","kind":"質問","question":"それはそれでお願いしたいんですが、それからいろいろな網の目のように走っている下水道網とか非常に複雑でわかりにくい部分もあります。ですから、その説明の工夫をお願いしますということをお願いして、答弁をいただければありがたいです。","respondent":"矢部下水道河川課長","answer":"下水道の整備の計画等、街づくり特別委員会の中で説明していますけれども、その説明の仕方、方法等について、また工夫をしていきたいと思いますので、よろしくお願いいたします。","id":"exchange-087"},{"speaker":"中塚委員","kind":"提案","question":"このままでは大井町と同じような状況が西大井でも起きるのではないか、こういった不安も伺っております。ぜひ西大井駅周辺に駐輪場の増設を提案いたしますけれども、いかがか尋ねました。","respondent":"奈良交通安全担当課長","answer":"そこの建物につきましては、来年の３月に区のほうに返ってまいります。現在の台数よりもかなり増えるように、今、中に台数が増えるような設備を導入して台数を増やすつもりで検討をしています。","id":"exchange-088"},{"speaker":"中塚委員","kind":"質問・要望","question":"そちらは要望で結構です。今後も本数が増えると伺っておりますけれども、ＪＲに対しては、どんな働きかけをしているのか尋ねました。","respondent":"奈良交通安全担当課長","answer":"正直に申し上げて、鉄道事業者が放置自転車対策について前向きに取り組んでいるのか、私はほとんど果たしていないというふうな感じはしております。その規定が非常にあいまいであるということで、これは２３区の区長名で、今国土交通省等に要望書を出しています。","id":"exchange-089"},{"speaker":"中塚委員","kind":"質問・要望","question":"Ｊタワーのつくるときの現場だったのでしょうか、物を置いていたんでしょうか、ニコンの駐車場になると伺いましたけれども。ぜひ西大井駅周辺に対して、さまざまな要望が上がっておりますので、今後ともＪＲに対して強く要望することを強く求めますけれども。","respondent":"中谷まちづくり事業部長","answer":"西大井駅につきましても、これは働きかけて駐輪場用地として提供させて、区が駐車場整備センターと協力して駐輪場を設置したという経緯があります。区といたしましては、これは必要な都度鉄道事業者にはおのおの働きかけはしてまいりたい、このように考えております。","id":"exchange-090"},{"speaker":"中塚委員","kind":"質問","question":"動きましたかと伺っていたんですけれども、当然動かないで困っているわけですから、水を排水することができました。排水ポンプがなぜ動かなかったのか、その予備を準備する、こういう体制は整っていなかったのか尋ねました。","respondent":"久保田防災課長","answer":"それから、必ずメンテナンスを１年に１回やっていまして、そこの部分が原因ではないかというふうには思っております。したがって、迅速な対応じゃないというふうなお話ですが、私どもは目いっぱい迅速な対応をやっておりますので、どうぞご理解ください。","id":"exchange-091"},{"speaker":"藤田委員","kind":"質問・要望","question":"それからもう１点は、１４７ページの都市景観形成事業、これについて、お伺いをいたします。第１点の道路際のＬ字構でしょうか、その形状を変えることができるのか、この辺のお伺いをまずしたいと思います。","respondent":"岩田管理工事課長、藤田都市計画課長","answer":"従来は５cmと１０cmが主でございまして、一般的には１０cmの段差のコーピングを使うことになっております。一般的には１０cmを使っておりますが、駐車場等の場合ですと５cmのものを一般的に使っております。 国のほうでは現状認識と課題をこの後どうしていくのか、政策展開をどうやっていくのか、それらの検討を今進めているところです。その動向を踏まえながら、景観ガイドプランの作成につなげていきたいというふうに考えてあります。","id":"exchange-092"},{"speaker":"藤田委員","kind":"質問・要望","question":"ちゃんと認めていらっしゃるのでしょうか、この認識をされているかどうか、お伺いをしたいと思います。そういうことについて、区として何か対策なりお考えがあるでしょうか、バックアップ体制ですね。","respondent":"岩田管理工事課長、藤田都市計画課長","answer":"ご指摘の商店や何かにＬ型の上に鉄板をひいている件ですけれども、私どもも十分認識しております。Ｌ型の０cm段差というのを開発しまして、中延の病院に設置して、こういう０cmのＬ型を採用して設置しています。専門家の派遣制度とか、私どものほうにはそういった事業もありますので、そういった形でサポートをしていきたいというふうに考えております。","id":"exchange-093"},{"speaker":"藤田委員","kind":"提案","question":"私は本会議の一般質問でこのＬ字構の段差を解消して、車いすでも通れるようにしてはどうだと、そういう提案を１年前にやりました。そこの一角でも、一隅かもわかりませんが、区が認定してあげたらどうか尋ねました。","respondent":"岩田管理工事課長、藤田都市計画課長","answer":"その０cmのＬ型を設置しておりますし、これは簡単なんですが、それに伴って民地側のほうのすり付け工事が必要になってまいります。なかなか個々に出た場合に、委員のご趣旨はそのとおりだと私も認識していますので… しゃれたストリート等の認定ですけれども、百景とか緑化顕彰制度を活用して今後もやってまいりたいと思います。","id":"exchange-094"},{"speaker":"山村委員","kind":"確認","question":"ちゃんと駐輪場として使われているかどうかの確認をなされているのかどうか、確認されているのかということを質問させてほしいと求めました。確認されているかどうかで、要するに駐輪場として使っていない場合、その場合の指導はどのようになされているかということをお聞きしたい。","respondent":"奈良交通安全担当課長","answer":"そういった小売店につきましては、大体店舗面積が３００m2を超える場合には２０m2ごとに１台を設置しなさいというような規定にはなっております。","id":"exchange-095"},{"speaker":"山村委員","kind":"質問","question":"そうしますと、このスーパーの駐輪というものは、区が撤去をするということでよろしいんでしょうか。区の撤去でということでよろしいか尋ねました。","respondent":"奈良交通安全担当課長","answer":"区域外につきましては、今の区のやり方としては警告シールを張って１週間以上そこに同じようにとまっているものについては撤去をしております。そういった区域外の撤去につきましても大体年間３,５００台ぐらいの自転車等を撤去をしているのが現実です。","id":"exchange-096"},{"speaker":"山村委員","kind":"確認","question":"確認をしに行かれているということなんですが、今後とも確認の作業は大変だと思いますが、頑張っていただければと考えています。今後、そういう品川区は道が狭いところが多いですから、店舗の前の駐輪で道が半分以上埋まってしまうということが多くあると思います。","respondent":"奈良交通安全担当課長","answer":"当然もう区のほうから強力に義務づけはさせますけれども、例えばそういった義務づけのなされない商店等、あるいはお店等もあります。当然建設業者あるいはそういった施行の主体にぜひ駐輪場をつくるように強く要望はしていきたいというふうに考えております。","id":"exchange-097"},{"speaker":"山村委員","kind":"意見","question":"前向きの答弁をほんとうにありがとうございました。正田邸の跡地の公園でも、その熱意をもって駐輪問題も頑張っていただければと考えていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-098"},{"speaker":"石田委員","kind":"質問・要望","question":"それから、都市景観形成事業１４７ページをちょっと先ほど藤田委員が触れたんですが、触れさせていただきたい。今、最初にお聞きしたいのは、なぜ放置自転車対策を区がやらなくてはいけないのかということを教えていただけますか。","respondent":"奈良交通安全担当課長","answer":"なぜ区が駐輪場を設置しなくちゃいけないんだろうというご指摘ですけれども、こういった自転車駐車場の設置の主体は、いわゆる駐輪場を設置をして。","id":"exchange-099"},{"speaker":"石田委員","kind":"意見","question":"５条の６項のことを言っていらっしゃると思うんだけれども、鉄道事業者まで含めて、地方公共団体も含めて放置自転車等の撤去に努めるなんだよね。条文はいいんだけれども、なぜそれを品川区が今やっていらっしゃるかということを説明を求めました。","respondent":"中谷まちづくり事業部長","answer":"これは、昭和４０年ごろまでの高度成長以前は自転車というのは非常に貴重品で、放置などというものはまず考えられなかったわけです。そして平成５年の改正、平成６年の施行でこれが一層強化されて、こういういきさつがあります。","id":"exchange-100"},{"speaker":"石田委員","kind":"質問","question":"平成６年ではないけれども、昭和５５年から進めてきた、もう１回やめてみたらいい。１回もう放置自転車だらけにして、区民意識をもう一度高めて、そういう発想をもう一度持つということの考えはどうか尋ねました。","respondent":"中谷まちづくり事業部長","answer":"ずっと放置自転車対策を進めてきた、啓発、そして２３区でも今荒川区に次いで品川区は２番目に放置自転車が少ないというような区になっております。そういうふうに考えるところもありますので、警察とも協力しながらその辺進めていきたい、このように考えているところです。","id":"exchange-101"},{"speaker":"石田委員","kind":"質問・要望","question":"そういうことをどうぞ、じゃあしゃれ街とさっきあったけれども、１,０００m2の制度はできてきた。どういうことができる、これは進んでいかないと思うんだけれども、そこら辺の考え方を教えていただきたい。","respondent":"中谷まちづくり事業部長、藤田都市計画課長","answer":"区議会全員の皆さん、あるいは区民の大方の皆さんが区が放置自転車対策を一度やめるということを支援するというような合意形成がなされるのであれば。しっかりと今委員の言葉に気を引き締めて、そして対策に当たっていきたい… それらの動向を見きわめながら、来年度具体的な検討を行っていきたいというふうに考えてあります。","id":"exchange-102"},{"speaker":"石田委員","kind":"質問","question":"それから、ガイドラインのほうはもう１点お聞きをしたい。ああいうものとの整合性というのをどこまでとるかだけちょっとお聞かせ願いたい。","respondent":"藤田都市計画課長","answer":"既存のまちづくり協議会等との連携ですけれども、本年度まだ内部での調整を進めているところですけれども、今後、国の動向を見きわめながら、地域の方と連携できるところについては連携しながらガイドプランの取りまとめを行っていきたいというふうに考えてあります。","id":"exchange-103"},{"speaker":"嶋委員","kind":"質問・要望","question":"私のほうからは３点お伺いいたします。二つ目には１４２ページの交差点改良についてお尋ねいたします。","respondent":"田村住宅課長","answer":"いわゆる管理支援の中で、品川区では例年平成１４年度で言いますと、区分所有者を対象に講演会を実施しております。住宅全体の中の一形態というような考えでおりますので、あるいは課題を検討していきたい、そのように考えております。","id":"exchange-104"},{"speaker":"嶋委員","kind":"質問・要望","question":"１戸建てよりか７.５倍ぐらいの固定資産税を払っているというお話もお聞きをしております。今の私のほうにご相談の方は、いろいろ区のほうにも要望書をお出ししたと聞いておりますし、区のご見解をお聞かせいただきたいと考えています。","respondent":"片田建築課長","answer":"それに合わせて整備プログラムといったものを今後ちょっとまた検討していくといったようなことで認識をしております。特に木造等については、財産だけではなくて地域の問題ということも考えてありますので、その辺を中心に検討を進めたいということで考えてあります。","id":"exchange-105"},{"speaker":"嶋委員","kind":"質問・要望","question":"非木造もあるかと思いますけれども、安心のまちづくりという意味でぜひご検討をいただきたいということと、よろしくお願いいたします。その間を縫って歩道に入っていかなくちゃならない構図になっていますので、ちょっとご検討ほしいと求めましたが、お考えを説明を求めました。","respondent":"奈良交通安全担当課長","answer":"車いすの方が通れない、それからベビーカーも通れない、何とかうまい対応を考えてもらいたいというご要望が昨今参りました。そういった車いすの方、今、横断歩道橋があってもできるだけ横断歩道をつけようというふうに前向きに検討はしているというふうに聞いております。","id":"exchange-106"},{"speaker":"嶋委員","kind":"意見","question":"実際問題今自転車とかそういう車いすの方たちが車道から歩道に入っていくという対応になっていますので、ぜひ一日も早くまた歩道のほうに入れるように安全対策をよろしくお願いをしたいと思いますので、お願いいたしますとの意見を述べました。","respondent":"奈良交通安全担当課長","answer":"今、委員ご指摘のように、私どものほうもやっぱりあそこにきちんとした、エレベーターはかなり時間はかかると思いますので、せめて横断歩道は早急に対応をするように、また国土交通省あるいは地元警察と強力に協議してまいりたいというふうに思っております。","id":"exchange-107"},{"speaker":"嶋委員","kind":"質問・要望","question":"トイレは、今管理組合、皆さんが役所の職員がいらっしゃるところの真裏にありまして、今トイレの入り口を日本風な竹の目隠しがされています。目隠しが必要かと思いますが、目隠しをぜひとっていただきたいというご要望がありますが、ご所見をお伺いたいと思います。","respondent":"松代道路公園課長","answer":"区民公園のトイレの目隠しの件です。でああいう目隠しをぜひつくってほしいということもございまして、もう一度そういう観点から調査をして検討をしたいと思います。","id":"exchange-108"},{"speaker":"嶋委員","kind":"質問・要望","question":"ぜひ目隠しは絶対とってほしいと求めましたので、ぜひとってほしいと求めましたが、もう一度お答えほしいと求めました。","respondent":"松代道路公園課長","answer":"前向きに検討してまいります。","id":"exchange-109"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"１４３ページ、１４５ページに書かれています水害問題についてお聞きしたいと思います。昨日の浸水被害について報告がされたんですけれども、そこら辺のところをどういうふうに考えられているのか、お聞かせほしいと求めました。","respondent":"矢部下水道河川課長","answer":"申しわけありません、トータルで３３件の床上床下浸水ということで、トータルで品川区全体で３３件の床上床下浸水が出てあります。集計しますので。","id":"exchange-110"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"も１件は防水板で地下駐車場のほうが、脇のコンクリートのほうからしみ込んできちゃって、浸水しちゃったというふうな状況みたいなんですよね。ちょっと今朝もお話を伺いにいったらそういうふうなことで言われたんですけれども、そこの部分については、いかがか尋ねました。","respondent":"矢部下水道河川課長","answer":"ですから、２本の管を１本に結んじゃいますと、逆に被害が広がる可能性というのは十分あります。そういうことで、これにつきましては、引き続き今回の状況も見ながら、下水道局のほうと検討していきたいと思います。","id":"exchange-111"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"改めて今回の被害状況も調査していただいて、地域の方のお話もお聞きほしいと求めましたので、よろしくお願いいたします。ぜひここの対策を一日も早く立てていただきたいということで何度かお聞きをしているんですけれども、わかったら教えてほしいと求めました。","respondent":"矢部下水道河川課長","answer":"中延幹線の水位低下をする工法について、ちょっと検討をということで、下水道局のほうに調査依頼をしております。その中で何か方法がないかということで検討をしているということで、申しわけありませんけれども、今この場でご紹介できるような内容はございません。","id":"exchange-112"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"さらに来年度は第２次財政再建推進プランの関係もあって１０％削減という、ほんとうに今２１世紀なんだろうかというふうに思うんですよね。ぜひ中延五・六丁目の立会川上流までの対策についてもとられていくように頑張っていただきたいというふうに思いますけれども、いかがか尋ねました。","respondent":"矢部下水道河川課長","answer":"その中で、手をこまねるだけではなくて何かできないかということで、２３区に、区長のほうのいろいろ努力もありまして声をかけております。その中で、東京都のほうに再度その辺要望を強力にしていきたいというふうに考えております。","id":"exchange-113"},{"speaker":"須貝委員","kind":"質問","question":"１４１ページ、あと１４６ページ、公園管理費について質問します。そういうことを、どうでしょう、区として考えていませんか尋ねました。","respondent":"浜脇住環境整備課長","answer":"それによって私どもとすれば、ある意味では建て替えによる不燃化建物によって、これは一つの協力というふうに考えている部分があります。","id":"exchange-114"},{"speaker":"須貝委員","kind":"質問・要望","question":"ここに表示されておりますけれども、私ももうほんとうにここ三、四カ月の間にもう数件の苦情が寄せられております。ほんとうに突然でびっくりしてどうしようもないというような現状なので、ただの説明会ではなくて、今後何かいい方法を考えてほしいと求めました。","respondent":"浜脇住環境整備課長","answer":"私どもも、そういう住民と建築主とのお話ができればというようなことで、場をつくったこともあります。住民あるいは建築主にそういう指導といいますか、お話をしていきたい、こういうふうに思ってあります。","id":"exchange-115"},{"speaker":"須貝委員","kind":"質問・要望","question":"防水対策として、台風や集中豪雨に強い、やはり透水性のアスファルトをその地域だけでも使うようにしていったらどうなんだろうか。何かでもやってほしい、そういうようなアクションということは必要じゃないかなと思うんですけれども、その辺いかがか尋ねました。","respondent":"矢部下水道河川課長","answer":"できませんけれども、歩道部分とか交通量が少ない車道部分等につきましては、透水性舗装に取り組んでおります。あわせて、むしろ下に浸透させようというような浸透桝なんですけれども、そういうものも道路改修等にあわせて積極的にやっているところです。","id":"exchange-116"},{"speaker":"須貝委員","kind":"質問","question":"次に、境界確定事務費についてお伺いいたします。官民の境界ですか、区内にある測定原点、道路上にこれをやはり早くつくるということが要求されると思うんです。","respondent":"岩田管理工事課長","answer":"まず３級基準点をきちっと設置をすることが公共基準点の原点ですので、行政の責任としては、まず３級基準点の整備に努めているところです。残りが約１０３地点ですが、実施計画では平成１５年度から３５地点ずつ設置する計画ですので、今年度を含めて３年で終了する予定です。","id":"exchange-117"},{"speaker":"須貝委員","kind":"質問","question":"その辺いかがでしょうかということが１点と、現在毎日のように使用しているわけですから、あの芝生はもたないはずです。芝生をなくすか、今後人工芝の対応等ということを考えられているのか、その辺ちょっとお伺いいたします。","respondent":"松代道路公園課長","answer":"今後も引き続きそういった取り締まりをしてまいります。今後もそういった管理を続けてまいりたいと考えています。","id":"exchange-118"},{"speaker":"林（宏）委員","kind":"質問","question":"あるいは世の中、家の中で自転車をどこへ置こうとそれは自分の家ですから勝手ですけれども、なかなかそれがうまくいかないのが人間社会だろう。一つ今日話題にならなかったレンタサイクルというんですか、それについてはどうなっているのか、その辺をちょっとご説明をください。","respondent":"藤田都市計画課長、奈良交通安全担当課長","answer":"もう少し詳細を詰めれば設計のほうは完了いたしますので、今年度中には住民説明会あるいは工事への着工という運びになる予定と聞いてあります。それで、全体の行程ですけれども、今の行程といたしましては… このケースの場合にはあちこちにとめられて非常にうまくいかなかった、大体３ないし４カ月ぐらいでうまくいかなかったというふうに聞いております。","id":"exchange-119"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"まだ行使していないけれども、ああいう考え方も一つ品川区もあっていいと思うんですけれども、その辺についてのお考えがあれば聞かせていただきたい。では、前段の部分だけ。","respondent":"高橋区長","answer":"特に鉄道事業者に対しまして１台幾らの新税を設けよう、そうすると、今鉄道業者と交渉しておりますと大変難しいという状況です。２３区の中で呼びかけてみたいと考えています。","id":"exchange-120"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"穏便に事はなるべく進んでいただきたいなというふうに思いますし、２３区で力を合わせて何とか、便利なことは便利なわけですよ。しかも品川区の場合は２３区一の駅の数があるということですから、そしてお互いの責任を認め合った上で、これは強くお願いをしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-121"},{"speaker":"金高委員","kind":"質問","question":"成果報告書の１４４ページ、道路緑化整備事業等について、それから同じく成果報告書１４７ページの都市再生総合整備事業についてお尋ねいたします。伺ったのは、実際にこの遊具を使う３時ごろといいますと、あるいは学校の子どもたちは今少子化ですから非常に少ない。","respondent":"松代道路公園課長","answer":"２点目の木製遊具の件ですけれども、すぐに調査をして対応をしたいと思いますが、安心して使っていただけるようにしています。最近比較的少なくなっておりますけれども、たまたまかちょっと別なところに遊びにいったのか、そういった状況かなと考えています。","id":"exchange-122"},{"speaker":"金高委員","kind":"質問・要望","question":"終点の五反田駅、これについては多くの方々から要望があるんですけれども、いわゆるＪＲとの関係がどうしても出てまいります。結構多くの方々からいろいろな要望を聞いて、なぜできないのだと、お聞かせ願いたいと思います。","respondent":"上野都市開発課長","answer":"五反田駅に、これは東急は今４階レベルに電車が入ってきておりますが、そこのつなぎのところのバリアフリーも検討の俎上に乗ってあります。","id":"exchange-123"},{"speaker":"金高委員","kind":"質問","question":"そういう話も当然来るでしょうから、その時点でもってはっきりと大体いつごろになるかという、その青写真ができると思うんですね。どういう進行状況が出ているかということを非常に興味深く見守っているわけでありますので、その辺も含めてお願いをして質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-124"},{"speaker":"宮崎委員","kind":"質問・要望","question":"私は成果報告書１４６ページの都市開発費に関連しまして、大崎駅西口中地区の問題で、お伺いしたいと思います。前回だったでしょうか、今時点でどういうふうになっているのか、その後の動きも含めてこの計画についてお聞かせほしいと求めました。","respondent":"上野都市開発課長","answer":"予定者を含めて協議をしてまいりましたところ、現在の段階では、その都市計画決定をした内容の計画見直しの検討を今着手したところです。その中で、今まで業務棟２棟、それを全体的に住宅へより比重を置いた形で検討をしていったらどうかという方向で今検討しています。","id":"exchange-125"},{"speaker":"宮崎委員","kind":"質問・要望","question":"そこら辺のところがどうなっているか、今お伺いしてびっくりしたんですけれども、ほんとうにこの計画はどうなるんだろうというのを改めて思いました。あわせてちょっと事業費がどうなっているか、あわせて補助金がどういうふうになっているのか、これについてもお聞かせほしいと求めました。","respondent":"上野都市開発課長","answer":"もう一つは、それは足元周りに張り出しを設けて、そこにも住宅などを配置したらどうかというようなことでの案を地元に提示して説明しています。今後は地元と協議しながら、そういった面についての方向性が決まった段階で、さらにその辺の具体的な検討をしていくという段階です。","id":"exchange-126"},{"speaker":"宮崎委員","kind":"意見","question":"そこら辺の補助金の仕組み、当然当初は５５億円ぐらいの補助金かというふうに言っていたんですけれども、これが当然増えるわけですよね。そこら辺のところのその仕組みがどうなっていくのかということを、簡単に仕組みをお聞かせほしいと求めましたけれどもとの意見を述べました。","respondent":"上野都市開発課長","answer":"補助をするに当たっては、それに対して国費が３分の１ですとかが入ってくるわけですけれども、住宅型のプロジェクトということで扱ってあります。","id":"exchange-127"},{"speaker":"宮崎委員","kind":"意見","question":"私ども２００３年問題で、確か次長だったと思うんですけれども、ここでこういうふうな計画が変わったということはどうしてなのか。この関係で、こういう変更になったのかどうなのか、そこら辺のことをお聞かせほしいと求めました。","respondent":"岩野まちづくり事業部次長","answer":"この大崎周辺６０ha全体でもって、そういったような中では、この地区は住宅のほうがいいだろうといったような形がございました。やはり立地的に事務所にしたほうが、この地区にとってより望ましい、そういったような判断をしたです。","id":"exchange-128"},{"speaker":"宮崎委員","kind":"質問","question":"要するに、業務棟としては事業が成り立たないというふうな判断だということじゃないですか。そこの見通し、それも含めてどうなのかというのが教えていただければと思うんですけれども、どうか尋ねました。","respondent":"岩野まちづくり事業部次長","answer":"そういったような点からいって、例えば明電舎でも１６万m2のほとんどを事務所にするということは、それは事業者が専門家として判断したです。もう１０年以上前の建物ですから、ゲートシティは今考えているところで、そのように報告を受けております。","id":"exchange-129"},{"speaker":"宮崎委員","kind":"意見","question":"今考えているということを私は聞いたのではなくて、見通しはどうなんだと。どうでしょうとの意見を述べました。","respondent":"岩野まちづくり事業部次長","answer":"それは、私どもでなくてゲートシティのほうで判断する問題ですが、ゲートシティからは見通しは明るいというように聞いてあります。","id":"exchange-130"},{"speaker":"宮崎委員","kind":"質問","question":"ですから、入り手がないという問題はほんとうに深刻。これは時間がありませんので言って終わりですけれども、やっぱりこういう巨大ビルづくり、こういう問題は経済の点からも見直すべきだと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-131"},{"speaker":"三上委員","kind":"提案","question":"それから１４９ページ、それから１４５ページ、若干お伺いしたいと思います。こういう状況が起きていると伺ったので、これもやはりせっかくこういう施設をつくっているわけですから、こうも思うわけですとの意見を述べました。","respondent":"矢部下水道河川課長、奈良交通安全担当課長","answer":"当地区につきましては目黒川右岸雨水排水施設ということで管渠整備しておりまして、今年の４月から暫定貯留を開始しております。その結果、たびたび浸水被害が起きる商店街の方に電話で確認をしたところ… 委員がご指摘のように、その辺の周辺にとめざるを得なくなるという部分がありますので、それについてはよくまた検討してまいりたい。どういう対応がとれるのか検討してまいりたい、そういうふうに思っております。","id":"exchange-132"},{"speaker":"三上委員","kind":"質問・要望","question":"その車両ナンバーを確認するということも非常に確認しづらいという、こういう状況になってくるわけですから、人命を大事にすることを考えたら。これについて、どういう状況だったのか、時間内でちょっとご説明いただきたいなと。","respondent":"田村住宅課長","answer":"環境住宅リフォーム助成事業ですが、区内の団体から請願が上がりまして、各会派趣旨採択ということで、新規に平成１４年度から立ち上げた事業です。","id":"exchange-133"},{"speaker":"三上委員","kind":"質問・要望","question":"ですから、そういう街もつくっているとかいうこともありますので、ぜひともそういうまちづくりをやっていっていただきたい。お願いしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-134"},{"speaker":"須藤委員","kind":"質問・要望","question":"そういった、単に下水道に流すということだけではなくて、その辺の構成はいかがお考えでしょうか、教えてほしいと求めました。８割をやってきましたよという、その辺の改修についてはどういう次元でやっていらっしゃるか、聞かせてほしいと求めました。","respondent":"矢部下水道河川課長","answer":"東京都のほうでも治水対策の考え方、指針を昭和６３年に出しまして、そういう施設をつくっていくという方針に変わっております。それで、今暫定計画という形で、そういう貯留とか浸透施設を使いながら、早く５０mm対応ができるような形で今計画を進めている状況です。","id":"exchange-135"},{"speaker":"須藤委員","kind":"質問・要望","question":"ここのところ数年で来ているわけですから、その辺を踏まえていろいろな計画をつくってほしいと求めましたんで、よろしくお願いします。それから、区営住宅、区民住宅についてお伺いします。","respondent":"田村住宅課長","answer":"借上型区民住宅の関係ですが、借上型区民住宅は委託契約と、当初は借上契約をするのが２０年契約で、すべてのそれぞれのオーナーと契約しております。やはり２０年間の契約ということで、区のほうでちょっと調査分析を開始して、そのように考えております。","id":"exchange-136"},{"speaker":"須藤委員","kind":"質問","question":"朝の質問で、ファミーユ下神明は２カ月ぐらいしてすぐ対応したということですけれども、その後のちゃんと支払いがなされているかどうかを聞かせてください。","respondent":"田村住宅課長","answer":"区長の方針決定をしまして、出した方が３件、自主退去していただいているという形が多いです。やはりその場合には速やかに和解条項違反ということで、立ち退きの訴えを起こすという形の手続をとろう、そのように考えております。","id":"exchange-137"},{"speaker":"須藤委員","kind":"質問・要望","question":"今後いろいろ年限があって、ある程度２０年ということで複雑な状況があると思うんですけれども、しっかりその辺も見ていってほしいと求めました。それとも今言ったように、大きな政策の中で考えを少しずつ変えていってもらう方向性はできるかどうか、ちょっと聞かせてください。","respondent":"田村住宅課長","answer":"それで、やはり平成１０年度から実施した中では、二世帯住宅の取得助成事業という新規事業で、やはり持ち家の方についての助成を開始した。やはり時代に合わせて住宅の支援の仕方はそのときどきに具体的に検討していく必要があるのかなと、そのように考えております。","id":"exchange-138"},{"speaker":"須藤委員","kind":"質問・要望","question":"ですから、できるだけそういうことでクリアしてきて入居条件という形になろうかと思うんですけれども、そのあたりの考え方はいかがでしょうか。それから滞納に対しては、やはりしっかりと対処をしてほしいと求めましたけれども、いかがか尋ねました。","respondent":"田村住宅課長","answer":"やはり公的な証明書あるいは物が、収入基準に合致する所得証明等がとれれば、当然審査決定して入居できるという形になります。入居のときはそうなりますけれども、やはり民間のノウハウを十分活用して連携をとりながら滞納処理に努めていきたい、そのように考えております。","id":"exchange-139"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/623169?Template=document&Id=1220#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2003-01-01&TermEnd=2003-12-31"}],"sourceMeta":{"pages":0,"characters":119873,"voices":324}},{"id":"h15-20031015-4","meetingId":"h15-c-settlement","date":"2003年10月15日","dateIso":"2003-10-15","committee":"決算特別委員会","time":"午前１０時０５分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を176件整理しています。","topics":[{"id":"topic-01","title":"◯松澤委員長 おはようございます。ただいまより決算特別委員会を開会いたします。 それでは、平成１４年度品川区一般会計歳入歳出決算","agenda":"◯松澤委員長 おはようございます。ただいまより決算特別委員会を開会いたします。 それでは、平成１４年度品川区一般会計歳入歳出決算","exchanges":[{"speaker":"大沢委員","kind":"質問・要望","question":"最初に、学校教職員被服貸与規程についてお伺いをしたいと思います。昭和３８年から平成１３年の規程の改正に至るまでの、事情があると思いますが、そこらのところを簡単にご説明をほしいと求めました。","respondent":"鷹倉庶務課長","answer":"あるいは学校教職員の部分で調査を行いまして、平成９年に、貸与の仕方を少し見直してまいりました。その後、さらに改正の、規程の整備という形で、今回至ったということで、平成１１年に改正をした、こういう経過です。","id":"exchange-001"},{"speaker":"大沢委員","kind":"質問","question":"被服貸与の必要性、改正の必要性が十分であったということを今認識をいたしまして、次の質問に移らせていただきます。数字的なものになりますが、本年、歳出のほうで２倍弱増えているわけありますが、これはどのような要因によるものか、ご説明をお願いいたします。","respondent":"鷹倉庶務課長","answer":"今ご質問の、平成１４年度決算で２倍にはね上がっているのはなぜかというのは、教員の３年のサイクルがこの年に当たったです。前年は教員の部分がなかったですので、そういう形で数字がはね上がったです。","id":"exchange-002"},{"speaker":"大沢委員","kind":"質問","question":"貸与規程の第９条に、これは年にどれぐらい、またはどのぐらいの期間で実施されているのかということが一つ。給食、用務の方は十分分かるんですが、一般の教職員、いわゆる先生について、どのような制服を貸与しているのか、具体的にお伺いしたいと思います。","respondent":"鷹倉庶務課長","answer":"先ほどの平成９年の見直しにつきましても、この規程を使いながら大々的な調査を行ったものです。こういうものを具体的に発注するときに先生方の要望を聞く、こういうような形で着用率を高めていきたい、こういうふうに行っているところです。","id":"exchange-003"},{"speaker":"大沢委員","kind":"質問","question":"被服といいますのは、俗に私たちの認識としては、紺の制服を認識しておったわけですが、それではないということでよろしゅうありますか尋ねました。","respondent":"鷹倉庶務課長","answer":"そのとおりです。","id":"exchange-004"},{"speaker":"大沢委員","kind":"質問・要望","question":"要望になりますが、表現の自由というものに係わってはまいりますけれども、教育を与えるにふさわしい服装というものもあります。１５７ページの給食費のうち食材費が書いてございませんが、これは消耗品等に入るのでございましょうか、お答えを願います。","respondent":"谷田部学務課長","answer":"１５８ページに消耗品等がありますが、学校が保護者の方から集める私費の会計ですので、この決算書の中には食材費の購入費用というのは出てまいりません。","id":"exchange-005"},{"speaker":"大沢委員","kind":"質問","question":"端的な質問でしたので、よく分かりました。残った場合、どのように対処をされているのか、お答え願いたいと思います。","respondent":"谷田部学務課長","answer":"教材、ドリルの関係とか、そういった分がやや残るというような話も伺ってあります。その年度で集めたお金はその年度に使い切るというのが基本です。","id":"exchange-006"},{"speaker":"大沢委員","kind":"確認","question":"次に２点ばかりまとめて最後に質問をします。これからに向けまして、小学校と中学校はもちろん献立は違うのではないかと思うんですが、そこのところを確認の意味でお答え願いたいと思います。","respondent":"谷田部学務課長","answer":"基準が違っておりまして、小学校の献立を中学生に出せるかどうか、今併せて検討をしています。必要なエネルギー摂取量、ビタミン等々の栄養の摂取量等も十分検討をしながら、今後十分な検討をしてまいりたいというように考えてあります。","id":"exchange-007"},{"speaker":"大沢委員","kind":"質問","question":"いずれにしましても、次代を担う子どもたちの土台を、区当局の方、また、栄養士の方、一生懸命献立を考えていただきまして、より充実した給食、また給食という教育のもとに行われる所作を充実していただくことをお願い申し上げまして、質問を終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"武内委員","kind":"質問","question":"私のほうからは、成果報告書の１５９ページ、小中一貫校基本計画策定費に関連をしましてお伺いをします。初めに、小中一貫校基本計画策定費ですが、具体的にどのようなことで支出されているか、教えてほしいと求めました。","respondent":"鷹倉庶務課長","answer":"小中一貫校基本計画策定費ですけれども、平成１４年度につきましては、大崎地区における小・中一貫校、第二日野小学校と日野中学校の小・中一貫校ですけれども、これの基本計画の策定費が主なものです。","id":"exchange-009"},{"speaker":"武内委員","kind":"質問","question":"２校目になる小・中一貫校が決定されたというふうに伺っておりますが、１０月１日に説明会が開かれたというふうに伺っておるんですが、その中でどういった質疑応答があったかを教えてほしいと求めました。","respondent":"鷹倉庶務課長","answer":"１０月１日に伊藤中学校におきまして、大井第一小学校、大井地区における小中一貫校の開設の説明会をさせていただきました。１０月１日の説明の中で、その間の体育館、プール等はどういう形になるんだろうということの質問がかなり占めておりました。","id":"exchange-010"},{"speaker":"武内委員","kind":"質問","question":"こういったことはどうなんだろうというような、不安の面でのご質問等がもしありましたら、教えてほしいと求めました。","respondent":"鷹倉庶務課長","answer":"そのときに会場でも具体的な話が１１月末ぐらいに見えてくるだろうという話を申し上げましたけれども、それでは１０月末の選択に間に合わない。","id":"exchange-011"},{"speaker":"武内委員","kind":"質問・要望","question":"なるべく情報を分かり次第、当てはまる保護者の方にお知らせいただきたいというふうに、要望としてお願いしたいと思います。私も具体的には伺っていないんですけれども、地元の方に少しお聞きした中で、その辺のところで何か展開がありましたら教えてほしいと求めました。","respondent":"鷹倉庶務課長","answer":"原小学校の跡地は普通財産に戻る。これを踏まえながら、区民の方々の意見も十分踏まえながらやっていかなければいけない、こういうお話をさせていただいているところです。","id":"exchange-012"},{"speaker":"武内委員","kind":"質問・要望","question":"特に地元の方が一番関心、特に地元の方のご意見をよくお聞きいただいて、方向性をお示しいただければというふうに考えております。説明会のほうも随時開いていかれるということで伺っているんですけれども、日程が決まっているようでしたら教えていただきたいんです。","respondent":"鷹倉庶務課長","answer":"今のところ日程は決まってございませんけれども、教育委員会、文教委員会にそれぞれ諮りながら、情報を提供していくという段取りですので、そういう段取りを踏まえながら今後日程を決めていきたいなと、このように考えてあります。","id":"exchange-013"},{"speaker":"武内委員","kind":"意見","question":"小・中一貫校ということでお考えになっているのか、もしお考えになっているようであれば、もしあればお教えくださいとの意見を述べました。","respondent":"古川教育次長","answer":"今年度予算を本年２月にプレス発表等を実施していく中で、各地区において小・中一貫校の必要性ということに言及いたしました。こういうことを十分に慎重に調査した上で、将来的な考え方を整理していきたい、このように考えてあります。","id":"exchange-014"},{"speaker":"飯沼委員","kind":"質問・要望","question":"１５１ページの教育指導費のところで性教育の関係でお伺いするのと、１５４ページの学校図書について、よろしくお願いいたします。小学校６年生の少女４人が部屋の掃除のアルバイトをしてほしいという、もう１点は、この二つの観点で質問をしていきたいと思います。","respondent":"中島指導課長","answer":"今回の小学生の事件がありました直後、こちらの対応ですけれども、夏休みの生活指導に係わる１学期の最後の段階での指導と徹底を依頼したところです。その状況を踏まえながら、その都度調査をして、対応を考えているという状況があります。","id":"exchange-015"},{"speaker":"飯沼委員","kind":"質問・要望","question":"そのことを１点お伺いしたい。その辺を伺いたいのと、保護者との協力を大変重視してほしいし、その辺お答えほしいと求めました。","respondent":"中島指導課長","answer":"毎月実施しております生活指導主任の研修会、各学校の情報、学校が知り得ている範囲での情報を認識しています。東京都が作成しているパンフレット、こういったものを使いながら、主任会の中でも子どもたちの安全についての研修会を実施しております。","id":"exchange-016"},{"speaker":"飯沼委員","kind":"質問・要望","question":"私はこの間父母の方から気になったことを伺ったのは、保護者会の回数が少なくなってきているというご意見があったんです。授業が１学期に１回もなかったとか、そういう話も聞くので、保護者会のことも具体的にお答えほしいと求めました。","respondent":"中島指導課長","answer":"小学校においては三、四年生で８時間、そして五、六年生で１６時間という形の実施です。ただ、一つ一つの内容を十分に実施するには総合的な学習時間等との関連をした指導が重要になっているという状況です。","id":"exchange-017"},{"speaker":"飯沼委員","kind":"質問・要望","question":"出産をするのは３割ぐらい、医療から見た思春期の性はセックスに無防備で、受け身である。子どもをどう守っていくのかということでは、とにかくとりかかって始めていただきたいと思うんですけれども、この点はいかがか尋ねました。","respondent":"中島指導課長","answer":"これまでにも保健学習の授業等で学校医とか、また保健所等との連携を図りながら指導を展開している状況はあります。今、地域で子どもを育てていくという視点は、性教育にかかわらずすべての部分で大切になってくる条件ではないかなと考えております。","id":"exchange-018"},{"speaker":"飯沼委員","kind":"質問・要望","question":"１２学級以上の学校に司書教諭の配置、特に専任の図書の職員を配置していただきたい、こういう要望が書かれておりました。学校図書館の充実のためにぜひ専任の図書館司書教諭の配置を要望するんですけれども、いかがか尋ねました。","respondent":"中島指導課長","answer":"そのうち１人に司書教諭が発令されるという中で、司書教諭は兼務という形で発令がされております。平成１４年度では１２学級以上の学校数が１６校ございまして、１２学級以上のところに兼務発令という形で設置していきたいと考えております。","id":"exchange-019"},{"speaker":"飯沼委員","kind":"質問・要望","question":"平成１４年度の小中学校の学校図書館実態調査を行っていて、要望が一番強いのが、こう言っています。司書の資格を持ったり、ぜひこの点で充実を願いたいんですけれども、再度。","respondent":"中島指導課長","answer":"各学校におきましては、図書館司書１人の力でもって図書館の運営をするわけではございません。","id":"exchange-020"},{"speaker":"大西委員","kind":"質問・要望","question":"私のほうで、成果報告書の１５３ページ、教育指導費のすまいるスクールについてお尋ねいたします。６,９３１万１,９７０円、これは具体的にはどういう工事に供された費用なのかということと、少し分かりやすくご説明ほしいと求めました。","respondent":"富田教育改革担当課長","answer":"９月開設ですので、７カ月分の運営費ということで、主に人件費が該当するものです。初度調弁につきましては、開設にあたりましての備品ですとか、あるいは椅子等単価の低いものの初度調弁の費用です。","id":"exchange-021"},{"speaker":"大西委員","kind":"質問","question":"大体分かりました。これからすまいるスクールを品川区全校でやっていくということですから、その辺はどうか尋ねました。","respondent":"富田教育改革担当課長","answer":"この辺の改修費用と、備品、また一般需用費でもって初度調弁というのが必要になってまいります。昨年は、これに初度調弁を加えた金額で実施しているところでありまして、来年度以降も同様の予算でもってやっていくことになろうかと思います。","id":"exchange-022"},{"speaker":"大西委員","kind":"意見","question":"区民がどういう不安を持っているのか、それについて検討する余地があるんじゃないかということを考えられたのは大変良いことでないかなと。今度は教育委員会にすまいるスクールで移ってくる、問題点を把握されているか、ちょっとお尋ねしたいと思いますとの意見を述べました。","respondent":"富田教育改革担当課長","answer":"こういったものを基本に据えながら、また、さまざまな問題については、児童課と調整しながら検討を進めてまいりたいと思っているところであります。こういったものを踏まえながら、児童課とも調整しながら、調整できる部分については調整してまいりたいと考えています。","id":"exchange-023"},{"speaker":"大西委員","kind":"質問","question":"には、親との情報の相互通行というんですか、こういったものも必要かなというふうに思います。国際理解教育というのがまたあるわけですが、この二つ分けている理由がちょっとわからないんですけれども、これはどういう違いがあるんか尋ねました。","respondent":"中島指導課長","answer":"これはやはりＡＬＴを使いますけれども、そのほかに交流都市のポートランド市とかオークランド市から招いた講師が入るという部分もあります。こういったような予算の内訳になってあります。","id":"exchange-024"},{"speaker":"大西委員","kind":"質問","question":"低学年からの教育ということに、要するに、１年生ぐらいからの教育についてはどのようにお考えか尋ねました。","respondent":"中島指導課長","answer":"には、そしてまず小学校低学年の段階では聞くということを基本にして英語に触れていく、こういったような環境づくりが大切だと考えます。そのための施策です。","id":"exchange-025"},{"speaker":"大西委員","kind":"質問","question":"４カ国語、もう１カ国語はちょっと忘れたんですけれども、そういうものを伝えるための情報手段としてのインターネットの使い方という点に関してはいかがなものか尋ねました。","respondent":"中島指導課長","answer":"こういう発達的な取り組みというものは必要になってくる部分だろうと考えております。今後のコンピュータを使った指導のあり方等を踏まえながら、こちらのほうも見ていく必要があると考えます。","id":"exchange-026"},{"speaker":"大西委員","kind":"質問・要望","question":"ぜひ品川区は率先して国際人を育てるためにも、子どものときから英語教育を力を入れてやっていただくことを要望いたします。私の質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"就学援助費、それと、先ほど大沢委員のほうから質問をいたしました学校教職員被服に係わる部分でお聞きしたいと思います。服装についての指導的なもの、また教育委員会としてどういう形が好ましいと思っているか、その辺のお答えをほしいと求めました。","respondent":"中島指導課長","answer":"学校の教職員の身だしなみ、姿勢ですけれども、子どもたちの教育に当たるという職務からも、これはきちんとした、そして批判をあびないような身だしなみが必要になってくると考えます。","id":"exchange-028"},{"speaker":"鈴木（真）委員","kind":"質問","question":"その考え方に対して、教育委員会として指導的なものはなさっていらっしゃるんでしょうか。その点をもう一度お願いいたします。","respondent":"中島指導課長","answer":"これは教職員の服務とも関連させて常に厳正なる態度で職務に臨むように指導をしています。","id":"exchange-029"},{"speaker":"鈴木（真）委員","kind":"意見","question":"それとプール改修が１,９００万円、これもなかったと思うんです。予算書と決算でずれている部分、大きな部分が出ているんですが、その点についてお答えをお願いいたしますとの意見を述べました。","respondent":"鷹倉庶務課長","answer":"そして、大井地区の中でどこにあるかというものにつきまして選定していかなければいけないということが出てまいりました。したがいまして、二重投資を避けるという意味で、せっかくいただいた予算ではありますけれども、執行を中止させていただいたという事情です。","id":"exchange-030"},{"speaker":"鈴木（真）委員","kind":"質問","question":"６００万円というのは、平成１５年度の予算の中の６００万円の使い道というのはどこに出ているのか。これは冨士見台中学校なんか尋ねました。","respondent":"鷹倉庶務課長","answer":"先ほど６００万円と申されましたのは、６,０００万円で、第三日野小学校の擁壁改修工事だと思いますので、確認させていただきたいと思います。今年度予算擁壁改修いただいているのは、第三日野小学校の擁壁改修ということで、６,０００万円を計上しています。","id":"exchange-031"},{"speaker":"鈴木（真）委員","kind":"質問","question":"中学校はないということは、昨年の予算の段階で改修が必要だということで１,１１０万円計上していて、今年度やらないでいいんですか。その時点で間に合わなかったんでしょうけれども、今年度どういうふうに考えていくのか、その点についてお願いいたします。","respondent":"鷹倉庶務課長","answer":"桜の木の根が張っておりまして、低い擁壁なんですけれども、若干傾いているというような部分があります。この点につきましては、来年度に向けて検討を進めていきたいなと思ってあります。","id":"exchange-032"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"そのまま来年度に回すというのはちょっと疑問もあるんですが、事故が起きないような態勢をきちんととっておくことを要望しておきます。それと１人当たり幾らぐいが基準になっているのかをお答えほしいと求めました。","respondent":"谷田部学務課長","answer":"２年生が５万９,５４８円、６年生になりますと移動教室の関係が出てまいりますので、８万４,３９８円。今申し上げましたのはすべて準要保護世帯の支給額です。","id":"exchange-033"},{"speaker":"鈴木（真）委員","kind":"質問","question":"なぜ基準額の２分の１と、実際に出ている金額が違うのか。一般財源になってきているんだと思うんですが、そこら辺のところをもう一度教えてほしいと求めました。","respondent":"谷田部学務課長","answer":"単純に国庫補助の歳入の部分と、実際の決算額と比較しますと、歳入が大体１０％前後しか国からはきてございません。それを全国都道府県に配分するという関係があって、非常にバランスが悪くなっているです。","id":"exchange-034"},{"speaker":"鈴木（真）委員","kind":"質問","question":"歳入の中で国庫補助基本額が出てくる。一般財源の中で補助しているんでしょうから、この金額を減らせということではないですから、一般財源との兼ね合いをお答えをほしいと求めました。","respondent":"市岡企画財政課長","answer":"区のほうで一般財源で３億１,０００万円ぐらい負担しているわけですが、これが１億２,７００万円ぐらいありまして、ここが制度上の問題です。この辺はしっかり国も改革をしていただかなければいけないというふうに認識をしています。","id":"exchange-035"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"財調に入っているんですかということをお聞きしたかったんですが、２分の１入っているということですけれども、支給額は決まっているんですから。もう１点、プラン２１に関連してのＣＡＴＶの放送という部分に絡めて質問をさせてほしいと求めました。","respondent":"富田教育改革担当課長","answer":"学校紹介のケーブルテレビの番組作成につきましては、企画部のほうでケーブルテレビのほうに委託をして行っている事業です。打ち合わせを重ねながら、できるだけ多く各学校の事業内容とか、さまざまな活動の取材をしていただくということで行っているものです。","id":"exchange-036"},{"speaker":"鈴木（真）委員","kind":"意見","question":"各学校、外国でもチャータースクールとか、イギリスなどでもかなり特色を出している学校もあります。そういう点でもいろいろな特色を出すべきだと思うんですが、最後お答えをお願いいたしますとの意見を述べました。","respondent":"山田広報広聴課長","answer":"２月の段階で翌年度の学校紹介のあり方について、会社と、私ども企画部と合わせてやってあります。それぞれの学校に校長を含めまして、各学校に伺いまして、学校の中でどんな事業を取り上げたいかを含めてやってあります。","id":"exchange-037"},{"speaker":"藤原委員","kind":"質問","question":"私は１５７ページの特殊学級就学奨励費と、１５８ページの児童・生徒健康管理費についてお伺いします。心障学級整備などが載っておりますが、心身障害学級と、特殊学級の違いがあれば教えていただけますか。","respondent":"谷田部学務課長","answer":"学校教育法第７５条において小中学校などに知的障害、できる規定ですけれども、これは法律上の呼称です。品川区におきましては、特殊学級という名称は使いませんで、心身障害学級というふうに称しています。","id":"exchange-038"},{"speaker":"藤原委員","kind":"質問","question":"同じということでいいと思うんですけれども、現在区立の小中学校に設置されている心障学級の学校数と、学級数、通われている児童・生徒の人数を説明を求めました。","respondent":"谷田部学務課長","answer":"それから、情緒障害の関係で１校に設置しまして、２学級編制で１２人が通っております。通級学級といたしまして、情緒障害の学級が１校で、１学級、１０人が通っていらっしゃるという状況です。","id":"exchange-039"},{"speaker":"藤原委員","kind":"意見","question":"こちら側も凄く勇気や元気がもたらせるような気がしていた矢先ですけれども、その中で９月２７日の新聞の見出しを見て本当に驚きました。９月２７日の時点で、このような発言に関して何か感想があれば、お聞かせいただけますかとの意見を述べました。","respondent":"谷田部学務課長","answer":"これは人権の問題、障害者等々に対する差別の問題、偏見の問題等あります。私どもも一言一言の発言というのは常に慎重で、そのような発言があったとしたら、非常に残念なことだというふうに思ってあります。","id":"exchange-040"},{"speaker":"藤原委員","kind":"質問","question":"続きまして、１５８ページの児童・生徒健康管理費についてお伺いします。希望する小学校で就学児の健康診断が行われると思いますが、これはどのような内容で行っているか、説明を求めました。","respondent":"谷田部学務課長","answer":"就学児の健康診断につきましては、学校保健法第２条に基づきまして実施しているというものです。診断の検査項目ですけれども、栄養状態ですとか、脊柱、胸郭の疾病、そのような異常があるかないか等々の状況を学校医の先生方が診断するです。","id":"exchange-041"},{"speaker":"藤原委員","kind":"質問","question":"適切な治療が行われていると思うんですけれども、にもかかわらず、現在でも健康診断というのは必要なんでしょうか。教育委員会の見解をお伺いいたします。","respondent":"谷田部学務課長","answer":"学校保健法の規定によりまして、教育委員会が実施する健康診断という法律上の義務付けがあります。例えば保護者と子どもが考えるきっかけになるという場面もありますし、〔時間切れにより、答弁なし〕。","id":"exchange-042"},{"speaker":"藤田委員","kind":"質問","question":"私からは１５１ページの、学校教育費の中に入るのかどうかわかりませんが、周年行事のあり方につきまして１点だけご質問をいたします。周年行事の意義と、１校に対して教育委員会から各学校に補助金なり助成金を出されていると思いますが、その辺をまずお伺いしたいと思います。","respondent":"鷹倉庶務課長、谷田部学務課長","answer":"周年行事の意義です。誇りと威信をもって地域、母校の発展を誓う、祝うという意義があるものです。 周年行事に該当する学校につきましては、消耗品の関係、記念品、記念誌ということで、平成１４年度決算額で約１７０万円ほど行ってあります。昨年は５校が対象になってありますので、３０万円ぐらいです。","id":"exchange-043"},{"speaker":"藤田委員","kind":"質問","question":"この１日のために、１日といっても、そしてその日を迎えるわけです。毎年やってきますけれども、その辺の感想をまず伺いたいと思います。","respondent":"鷹倉庶務課長","answer":"出席者のほうからは会費という形で徴収されながら、全体の経費を賄っておられると思います。どういう順序でやっていけばいいか、当事者は初めてですので、私どもが懇切丁寧に指導をしています。","id":"exchange-044"},{"speaker":"藤田委員","kind":"質問","question":"ですから、例えばお金をそんなにかけなくても、見直す一つではないかなと、こういうふうに思います。これは課長では大変かなと思いますので、それなりの方に、教育委員会としてきちっとお願いしたいと思います。","respondent":"若月教育長","answer":"周年行事の考え方です。出ないとか、これを教材としてどう活用するかということを見直していきたいという、その部分については十分に理解をするところです。","id":"exchange-045"},{"speaker":"藤田委員","kind":"質問・要望","question":"趣旨をきちっとやっているんですよ。この問題は引き続き私は別な機会でやらせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"},{"speaker":"三村委員","kind":"質問","question":"１５９ページ、１５１ページ、お聞きしたいと思います。非常勤職員の研修状況、またボランティアの方の集まり具合はどうだったのか、お聞きをしたいと思います。","respondent":"富田教育改革担当課長","answer":"９月２９日の杜松小学校ならびに清水台小学校ということで、無事に１５校で、それぞれ説明会を行った後に開設をさせていただいたところであります。既設の４校のほうに見学、すまいるスクールそれぞれ立ち上げるにあたっての準備を、研修も含めて行ったです。","id":"exchange-047"},{"speaker":"三村委員","kind":"質問","question":"すまいるスクールでは、その健全な育成を図る事業とされておりますけれども、これは条例化をされるのかどうか。目的としてきちんと遊びというものを第一の目的として入れるのかどうか、その辺のところをお聞きしていきたいと思います。","respondent":"富田教育改革担当課長","answer":"来年４月以降はすまいるスクールが、現在実施要綱で行っておりますが、要綱上にもうたってまいりたいというふうに思っております。放課後児童健全育成事業が、その辺につきましては、さまざまな面での児童の全体的な健全育成が目的であるというふうに捉えているところであります。","id":"exchange-048"},{"speaker":"三村委員","kind":"質問・要望","question":"自発というものは遊びを通して育てられていくものだと考えておりますので、ぜひこの点についてもう一度、要望という形で述べします。次に、現在すまいるスクール事業の見直しが行われていると思いますけれども、進捗状況を説明を求めました。","respondent":"富田教育改革担当課長","answer":"すまいるスクールは学童保育クラブと全く同じものではなくて、先ほど申しましたように、さまざま学童保育クラブを上回る内容を持ってあります。来年４月の、今年度の実施内容、来年以降改善していけるものがないかどうかという点で検討を進めているというところであります。","id":"exchange-049"},{"speaker":"三村委員","kind":"意見","question":"３月の時点で学童保育クラブを受け入れをしていかないという方針が出されております。今検討中ということですけれども、結論が出るのは大体いつぐらいになるか、お聞かせほしいと求めました。","respondent":"富田教育改革担当課長","answer":"現在こういった内容で検討をしている、あるいはこういった方向でやっていきたいと思っているよといったようなことにつきましては、保護者の方々には早い時期にお示しをできるものというふうに考えております。","id":"exchange-050"},{"speaker":"三村委員","kind":"質問","question":"川崎市民局のわくわくプラザの運営の手引きというものが作成されておりましたけれども、こういったものを作成されていく予定があるのかどうか。保護者の方たちにとっては、そういったときにきちんと専任指導員の方の手助けがあるのかどうか、そういったところのお考えをお聞きしたいと思います。","respondent":"富田教育改革担当課長","answer":"川崎市で実施をいたしました、現在２年間にわたり実施してきている第二延山小学校におきましては。あるいは学校により違う部分も若干出てまいりますが、運営の決まりのようなものを作成してまいりたいと考えております。","id":"exchange-051"},{"speaker":"三村委員","kind":"質問","question":"プラン２１の推進、子どもたちが遊べている、充実した場にはなっていると思います。ただ、そういった点ですまいるスクールの運営の手引きがつくられていくのかどうかだけお聞きをしたいと思います。","respondent":"富田教育改革担当課長","answer":"すまいるスクールは確かに学校との強い連携のもとに実施しておりますが、９月に開設したばかりの学校からも感謝の声というのが届いております。","id":"exchange-052"},{"speaker":"三村委員","kind":"質問","question":"先日もお聞きをしたんですけれども、その中には骨折などの大きいけがなども含まれているということをお聞きしております。４月以降、具体的にどういうような対処がされていくのか、お聞きをしたいと思います。","respondent":"富田教育改革担当課長","answer":"すまいるスクールは学校の連携のもとに行っている事業ですので、速やかに学校に連絡をして、養護の先生などと相談をすることが多くあります。その上で保護者にも連絡をした上で、救急なり、あるいは近くの校医なりに指導員が連れて行くといったような対応をしてきております。","id":"exchange-053"},{"speaker":"三村委員","kind":"質問","question":"そういった対応についても、マニュアルのほうで定められていくかと思うんですけれども、その辺のお考えについてもお聞きをしたいと思います。","respondent":"富田教育改革担当課長","answer":"各すまいるスクールごとに危機管理のマニュアルは作成をしております。けがと事故が起きた場合の対応ということでのマニュアルをつくっておりまして、この中で緊急連絡先、校医。","id":"exchange-054"},{"speaker":"三村委員","kind":"確認","question":"学童保育クラブの関係で質問をしたときに、教育委員会のほうでも児童課との連名でのＱ＆Ａの作成および公表ということでご確認をしたいんですけれども、その辺のお考えについてお聞きをしたいと思います。","respondent":"富田教育改革担当課長","answer":"すまいるスクール、１５校開設したばかりですけれども、さまざまなお問い合わせ等々が寄せられております。一つ一つお答えするように努めておりますけれども、これから学校に上がる、ホームページ等々の手段を使ってお知らせをしてまいりたいと考えています。","id":"exchange-055"},{"speaker":"三村委員","kind":"質問・要望","question":"第２校目、各地区の区割りというものはどういったものであるのか、お聞きします。八潮地区と分かれておりますけれども、小・中一貫校における各地区とはどういった地区のことを指しているのか、お聞きをしたいと思います。","respondent":"鷹倉庶務課長","answer":"そして、今年度につきましては、大井地区における小・中一貫校という形で進めしています。各地区に展開ということにつきましては、今後検討を進めてまいる予定です。","id":"exchange-056"},{"speaker":"三村委員","kind":"質問","question":"各地区がどういった地区割になっているのかをお聞きしたいんですけれども、もう一度。","respondent":"鷹倉庶務課長","answer":"各地区をどのように捉えるかによって学校の小・中一貫校の数というものが裏腹に決まってまいりますので、そこのところも含めて、検討を進めてまいりたいと思います。","id":"exchange-057"},{"speaker":"三村委員","kind":"質問","question":"地区が決まっていないということの理解でよろしいのか尋ねました。","respondent":"鷹倉庶務課長","answer":"学校選択のブロックを基本に進めているわけですけれども、いろいろな地区が数的には考えられるわけですけれども、今検討を進めているです。","id":"exchange-058"},{"speaker":"三村委員","kind":"質問・要望","question":"やっぱりわからなくて、地区が決まっていないような気がして、ちょっと理解ができないんですけれども、時間がないので、要望だけ。大井地区、第二日野小学校と第二日野中学校の決定の際、情報の出され方等をもう少し父兄に配慮した情報の出し方をお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-059"},{"speaker":"伊藤委員","kind":"質問","question":"すばらしい人間関係を築いていくことが目的であると私は思っておりますので、改めてこのすまいるスクールの目的をお伺いします。ですから、必要以上に囲む必要はないと思いますが、いかがか尋ねました。","respondent":"富田教育改革担当課長","answer":"地域のボランティアの方々、保護者の方々、そういった多くの方々との人間関係の中でさまざま学ぶものが多いというふうに考えております。","id":"exchange-060"},{"speaker":"伊藤委員","kind":"意見","question":"今教育改革担当課長がおっしゃった、目的を達成するために、いわゆる指導員の確保策はどういうふうにされていくのかということ。保護者の皆さんが必要以上に混乱することのない体制はぜひ構築していくべきと思いますので、その対処方法をもう一度説明を求めました。","respondent":"富田教育改革担当課長","answer":"２点目に、指導員の確保ですけれども、例えば教員免許を持っている者を各すまいるスクールに２名配置するなどの対応をしております。","id":"exchange-061"},{"speaker":"伊藤委員","kind":"質問・要望","question":"努力、そういう思いを持つ職員をどう確保していくかが、もう少しその部分の補完する答弁をいただきたいのが一つ。ですから、指導員の確保策についてもう少し補完する答弁をほしいと求めました。","respondent":"富田教育改革担当課長","answer":"そういった児童に対する若いパワーを活用していくとか、そういったことについても心がけてまいりたいというふうに思っております。そういったものをきちんと認識し、児童に意欲を持って当たれる、そういった指導員を育てていくということにも心がけてまいりたいと考えています。","id":"exchange-062"},{"speaker":"伊藤委員","kind":"質問・要望","question":"ですから、お伺いしたいのは、そういうふうな必要とされる皆さん、いろいろな方々が意見をお持ちです。そういう方々に対して、限られた時間の中、限られた予算の中で、執行していく責任と、説明責任をどうお考えですかということを、答えるよう求めました。","respondent":"富田教育改革担当課長","answer":"すまいるスクールは今年度１５校開設ということで、そういったものにつきましてもぜひ区民の皆様方にも十分に説明をしていきたいと考えております。ご意見、そういったものにも教育委員会といたしましての考え方なり、説明を十分に尽くしてまいりたいと考えています。","id":"exchange-063"},{"speaker":"伊藤委員","kind":"質問","question":"何でもそうですけれども、一つの事業を進めていくと、賛成する方もあれば、そうでない方もいて、これは民主主義ですから当然なわけですね。もう一言、すまいるスクールの事業の進展と、併せて説明責任の部分をもう少し補完する答弁をいただければありがたいんです。","respondent":"古川教育次長","answer":"しかしながら、行政が実施している事業についての一定の責任の範囲ももちろんあります。今までのすまいるスクールの実施内容に加えて、新たな視点を来年４月に見据えながら、このように考えてあります。","id":"exchange-064"},{"speaker":"金高委員","kind":"質問・要望","question":"私は成果報告書の１５４ページ、学校環境整備事業について、２点目に成果報告書の１５８ページ、学校保健費についてお伺いします。１８校のうち何校が砂地なのか、オールウエザーというんですか、その辺のところの区分けをまず教えてほしいと求めました。","respondent":"鷹倉庶務課長","answer":"校庭の舗装の状況です。全校の部分ですけれども、全天候校型が７校、全天候プラスダスト型が２校、人工芝が戸越台中学校で１校、ダスト舗装が４８校、こういう流れです。","id":"exchange-065"},{"speaker":"金高委員","kind":"質問・要望","question":"ちょっと質問を変えまして、雨が降ったときに、砂地が流れ出てしまうというふうに整備されている学校は中学校で何校ありますか。それを教えてほしいと求めました。","respondent":"鷹倉庶務課長","answer":"小学校が３１校で、中学校が１７校、これがダスト舗装という形です。","id":"exchange-066"},{"speaker":"金高委員","kind":"意見","question":"それから、それに対して近所の方々の評価がどういうふうになっているか。掌握しているところをお答え願いたいと思いますとの意見を述べました。","respondent":"鷹倉庶務課長","answer":"さらに、砂ぼこりがいくというようなことであれば、防砂ネットというようなものも考えていかなければいけないということを考えてあります。","id":"exchange-067"},{"speaker":"金高委員","kind":"意見","question":"音は別としまして、砂ぼこり等風が吹いて舞ったときの被害といいますか、そういうのが発生したときどうするか。住民の方々が苦情を申し立てる場所がどこにあるのか、その辺のところをお答え願いたいと思いますとの意見を述べました。","respondent":"鷹倉庶務課長","answer":"ただ、本当に困った状況ということであれば、ほかの事例ではありますけれども、当然私ども宿直を通じて責任者のほうに通報がくる場合もあります。そのときにつきましては、適切な指示、あるいは行動を起こすということで考えてあります。","id":"exchange-068"},{"speaker":"金高委員","kind":"意見","question":"そうしますと、内容的には後日という形になると思いますけれども、後日ですと、その場は間に合わないという形になるわけですね。後日どういう形でそれを処理するのか、それが納得できるような形での説明責任ができるのかどうか、その辺も併せてお答え願いたいと思いますとの意見を述べました。","respondent":"鷹倉庶務課長","answer":"水やり等を学校にきちっと指導してくださいという、こういう苦情の電話が、施設の責任者ということできてあります。そういう声も踏まえながら、学校ときちっと対応をしながら、近隣に砂ぼこり等ができるだけ入らないような形の対応をしていきたいと考えています。","id":"exchange-069"},{"speaker":"金高委員","kind":"質問","question":"今までどういう形のときに、そういうのがあるのかどうか、どのような形で処理されているのか。そういう管理方法、あるいは管理マニュアルというものがあるのかどうか、それの活用ができるのかどうかということもお伺いしたいと思います。","respondent":"鷹倉庶務課長","answer":"文書的なマニュアルというものはございませんけれども、基本はそこにあるというふうに考えてありますので、その点は学校等にも十分徹底しています。今の基本的な考え方、水道を使いながら、それぞれ使われる方が散水を心がけていただきたいなというふうに考えているところです。","id":"exchange-070"},{"speaker":"金高委員","kind":"質問","question":"ですから、すぐそれがある程度抑えられるというようなことができるのかどうか、どう思っているのか。学校側はどういうふうにして受け入れているのか、その吸い上げる意見の窓口があるのかどうか、その辺もお聞かせ願いたいと思います。","respondent":"鷹倉庶務課長","answer":"そして、それが近隣に迷惑をかけるということは、なかなか解決しがたい問題だと考えています。学校、具体的な状況がつかめますので、ぜひ私どものほうにおっしゃっていただければと思います。","id":"exchange-071"},{"speaker":"金高委員","kind":"質問・要望","question":"既になくなってしまって、住民の人たちが受ける印象とまた違うと思いますので、その辺のところの差をどういうふうに思っているのかということ。これは実際に道路公園課のほうでやっているのかどうか、どういう形で植栽に対しての管理をしているのか、お知らせ願いたいと思います。","respondent":"古川教育次長","answer":"ご近所の方々とさまざまな検討をしながら、良好な環境づくりに努めていく、こういう方向で今後とも取り組んでいきたいと思ってあります。そして学校でできる状況につきまして、教育委員会がその辺につきましては調整をしながら対応をしていきたい、このように考えてあります。","id":"exchange-072"},{"speaker":"金高委員","kind":"質問・要望","question":"１５９ページに学校保健費の中の心臓検診、腎臓検診がそれぞれあります。あるいは三次までいった事例に対してどのような指導をしているか、簡単で結構ですので、その後のことをお知らせ願いたいと思います。","respondent":"谷田部学務課長","answer":"疾病を予防するための検診をやってありますので、当然これは最終的に治療が必要だという判断が出れば、その子どもの治療をしていただくという関係になります。","id":"exchange-073"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"どういうふうになっていくのかということでお聞きしたいんですけれども、中学校で何クラスになっているかということを教えていただきたい。それをすべて全学年で３０人以下学級にする場合に、どういうふうになっていくかということで、中学校別に教えていただきたい。","respondent":"谷田部学務課長","answer":"中学校におきましては、６３人の増になるということでございまして、１人当たり１,０００万円前後それぞれ掛けていただければというふうに思います。","id":"exchange-074"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"改めて３０の道府県が始めたということで、かなりいろいろな県の評価というか、成果についてのまとめというのが出されております。教育委員会のほうでも読まれていると思うんですが、これについての感想と、評価についてお聞かせほしいと求めました。","respondent":"谷田部学務課長","answer":"それと、私ども生活集団と学習集団ということで、さまざまな取り組みをしておりまして、生活集団の場面では４０人学級が適切だろうと。","id":"exchange-075"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"長野県とか山形県の評価というのでまとめているのはご覧になられておりますでしょうか。そしてまた、４０人学級がいいという根拠はどういうところからきているのかについてお聞かせほしいと求めました。","respondent":"中島指導課長","answer":"いわゆる担任の持ち上がりのための考慮、これは先ほども学務課長が答弁いたしましたように、東京都においても実施しています。今後ともこちらの習熟度別学習の充実を図っていきたいなと考えております。","id":"exchange-076"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"このことについても改めて答弁をいただきたいと思うんです。それと、県のまとめでもそういうふうに出ているんですけれども、これについてどのような認識を持たれているかについても説明を求めました。","respondent":"谷田部学務課長","answer":"私どもの取り組みはもっと幅広くやってありますので、品川区は品川区の効果が相当出ているのではないかというふうに自負しています。それから、４０人を割った場合については、２学級だったのが１学級になるというのはやむを得ない制度だということで考えてあります。","id":"exchange-077"},{"speaker":"嶋委員","kind":"質問・要望","question":"初めに１５２ページの心の教育相談員活用、１５３ページの福祉教育の内容に関して、朝の読書運動の推進状況についてお伺いいたします。そのときには小学校では２８校、中学校では５校となっていますということで、その後の推進状況をお聞かせをほしいと求めました。","respondent":"中島指導課長","answer":"さまざまな方との連携の中で授業を実施したり、そういう状況がありますが、私どもが実施しておりますスチューデント・シティにも見られますように。学校での実施も大変増えてきている状況があります。","id":"exchange-078"},{"speaker":"嶋委員","kind":"質問・要望","question":"今学校へ行っていない」と言っていたものですから、どういうふうな係わり合いが、ぜひ学校からもいろいろな事情があると思います。もし映画のすばらしいなと思うときには、ぜひそのときには児童・生徒を映画館に鑑賞をさせていただきたいなと思って、要望をします。","respondent":"中島指導課長","answer":"朝とかお昼の時間帯を使いまして継続的に行っていく部分、例えば必読書とか、また高学年が低学年に読み聞かせをしているというような状況もあります。","id":"exchange-079"},{"speaker":"嶋委員","kind":"質問・要望","question":"ぜひ継続をして進めていただきたいと考えていますので、よろしくお願いいたします。ご質問をさせていただきたいんですが、１０億３,３００万円、イメージ的なものでお聞きをしたいと思います。","respondent":"上川内生涯学習課長","answer":"最終的には国は市区町村に２０１０年まで１カ所という目標を持っておりますが、品川区はその前に、全域１７地区でさまざまな活動をしております。","id":"exchange-080"},{"speaker":"嶋委員","kind":"質問・要望","question":"いろいろな要望が出てくると思いますが、また１７地域でこれから進めていく品川区ですが、お聞きをしたいと思います。","respondent":"上川内生涯学習課長","answer":"品川区の場合は学校が全区域にありますので、１７の地域に分けて、夜間照明もスポレク推進委員会の活動の拠点、１７カ所ということで進めております。ただ、シャワールームという点では、学校の体育館等を使っておりますので、シャワールームまではまだいっておりません。","id":"exchange-081"},{"speaker":"嶋委員","kind":"質問・要望","question":"そういう施設もどんどん必要になってくるかと思いますので、要望をしておきたいと思います。ご見解と、それから、少し会場が広く使えることになったのかお聞きをしたいと思います。","respondent":"上川内生涯学習課長","answer":"現在のところまだオープンして半年ぐらいですが、２６団体の方たちに利用されております。","id":"exchange-082"},{"speaker":"林（宏）委員","kind":"質問","question":"何点かお伺いしていきます。時間があれば、プラン２１全体についてのことを最後にお聞きしたいと思います。","respondent":"市岡企画財政課長、上川内生涯学習課長、谷田部学務課長、古里品川図書館長","answer":"いずれにしても、例えば各年度１校ないし２校ずつの改築が入ってきても、それに１０年タームで大体耐えられるような積み方をしております。… ６月頃国土交通省のほうから首都高速の東京港のトンネルの交通渋滞解消のために、トンネルを両側につくるという計画があるという説明がされました。… 中学校の衛生管理につきましては、学校保健法に基づきまして、学校環境衛生の基準に基づいて衛生管理維持運営をしているです。","id":"exchange-083"},{"speaker":"林（宏）委員","kind":"質問","question":"それから、安全、衛生の部分ですけれども、３,０００m2以上だけしか見ないんですか。それ以下の小さいところは消毒もしなくていいんか尋ねました。","respondent":"古里品川図書館長、市岡企画財政課長、上川内生涯学習課長","answer":"法律ではそう定められておりますけれども、品川図書館の中にある９つの図書館については規模が小そうあります。定期清掃等については毎月１回していますし… 中学校１校当たり、例えば２５億円とか、毎年の財源対策を頭に置いております。この辺を勘案しながら、できるだけ着実に今後の需要計画を円滑にできるよう… 野外活動広場ですが、工事のことですので、まちづくり事業部と調整しながら、要望書も取りまとめ、代替施設等の要望をしております。","id":"exchange-084"},{"speaker":"林（宏）委員","kind":"質問","question":"それから、衛生は年に１回クリーニングじゃ相当ひどくないですか。年に一遍クリーニングをやっていますから大丈夫ですという答えができますか。","respondent":"古川教育次長、古里品川図書館長","answer":"今回こういう工事が予定されている中で、野外活動広場に代替できるような、そういう運用面における工夫というものを所管のほうと今調整をしています。そういう中で、限られた環境の中でも何とか活動のできる場の確保に努めていきたい… 自分の家に置き替えて考えてみたらどうかという、非常に厳しいご叱責でございましたけれども、確かにそのとおりです。","id":"exchange-085"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"スポーツ全般的に言う広場の確保ですから、必ずや見つかると思うので、その辺強くお願いをしておきます。現状は、もちろん教育というのはエンドレスですから、７合目ぐらいまで到達するよというようなことをぜひ発表を今度はしてください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-086"},{"speaker":"西本委員","kind":"質問","question":"私のほうから１５９ページの小中一貫校基本計画策定費、１６０ページ、二葉幼保一元化施設費、この二つについて質問をしたいと思います。その辺どういう感じなのか、それから子どもたちの感想でもいいし、そちらのほうが何か分かりましたら説明を求めました。","respondent":"富田教育改革担当課長","answer":"この後、小・中一貫校の教育内容についての説明を保護者向けに行っている最中でございまして、第四日野小学校で今月中に行う予定になっているです。","id":"exchange-087"},{"speaker":"西本委員","kind":"質問・要望","question":"これから質問をしますけれども、保護者の方、ＰＴＡの方たちと一緒に考えていただきたいというふうに私は思っているところです。その中で、いろいろな不安な気持ちもあるでしょうけれども、前向きにといいますか、そういうご意見というのは何か聞いてありますか尋ねました。","respondent":"富田教育改革担当課長","answer":"保護者の方向けの説明会の中では、第二日野中学校と模擬授業での交流をするとか、そういった試みをしていってもらえないだろうかといったような声もいただいているところであります。","id":"exchange-088"},{"speaker":"西本委員","kind":"質問","question":"当事者なものですから、私が感じたところによると、なかなか理解が難しいという弁が多々あったかと思います。なぜその話をしてくれなかったのかという、全部を決めてから言ってほしい、そういう方も結構いらっしゃったと思います。","respondent":"鷹倉庶務課長","answer":"今度は、１０月末日の学校選択が迫っている中で、具体的に決めた形で説明会を開いてほしかったという話があったのは事実です。子どもたちへの説明も学校を通じて、あるいは何らかの方法で子どもたちの気持ちも受け止めていきたいな、このように考えているところです。","id":"exchange-089"},{"speaker":"西本委員","kind":"質問・要望","question":"むしろプリスクールという、西五反田でする内容、この兼ね合いというのは今後どういうふうになっていくのかなと。今後、就学前の学習ということに対してどういうふうに捉えていこうとしているのか、ご答弁をお願いいたします。","respondent":"谷田部学務課長","answer":"幼保一元化に向けての検討をしてまいりまして二葉幼稚園が従来６学級で編制していた経緯がございまして、空き保育室が二つ生じたと。０歳から３歳までの認可保育所を設置し、６年間を見通した教育保育をやっていこうというのが、二葉幼保一元化の趣旨です。","id":"exchange-090"},{"speaker":"西本委員","kind":"質問","question":"内容は分かりましたが、今後全国的に広がっているという中で、品川区においては幼保一元化をどういうふうに進めようと考えられているのか。それと、別にここでなくても構いませんが、これからの品川区の幼保という形でどういうふうな流れにいこうとしているかをご答弁をお願いします。","respondent":"谷田部学務課長","answer":"区立幼稚園を設置してきた幼稚園の位置づけというんでしょうか、今後の子育て支援との関係も出てまいりますし、今後の子育て支援を検討する上での区立幼稚園の議論というのが必要になってくるだろうというふうに考えてあります。","id":"exchange-091"},{"speaker":"西本委員","kind":"質問","question":"これは小学校１年生、学級というのかどうかわかりませんけれども、就学前の教育ということもある程度考えていかなければならないだろう。非常に興味があるところではあるんですが、その見解はいかがか尋ねました。","respondent":"谷田部学務課長","answer":"例えば良い面で言いますと、幼稚園は４歳から入ってまいります。幼稚園は通常午後２時まで行いますけれども、午後２時に幼稚園が終わって、幼稚園の場合はそうじゃないという部分で。","id":"exchange-092"},{"speaker":"西本委員","kind":"質問・要望","question":"今後いろいろな視点で子どもたちのために頑張ってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-093"},{"speaker":"木下委員","kind":"質問・要望","question":"まちを歩いておりまして、二、三気になった点とか、要望ですとか、ご質問をします。仮称市民科、中身はどんな学習をさせようというふうに思っていらっしゃるのか、ちょっとお聞きしたいと思います。","respondent":"中島指導課長","answer":"小・中一貫校でただいま考えております市民科の基本的な内容と考え方です。プレゼンテーションという場面で自己表現の場面のコミュニケーション能力を高めるとか、こういったような内容がその中に組み込まれていく予定です。","id":"exchange-094"},{"speaker":"木下委員","kind":"質問","question":"１年生から４年生まで、その学校が自主的にやっているということで、学校のほうが手当てをしているのかどうなのか。それについてのご意見をお聞かせ願えませんか尋ねました。","respondent":"中島指導課長","answer":"六年生１クラスに５時間というような形で基本的配当を考えてありますけれども、１日当たりでＡＬＴを派遣するとか、さまざまな対応をしています。","id":"exchange-095"},{"speaker":"木下委員","kind":"質問","question":"正規じゃない部分について、区のほうの手当は出ているのか、出ていないのか。そういうところでなくても、品川区内で何校ぐらいがそういう形で１年生から授業をやっているのか、ちょっと教えていただけますか。","respondent":"中島指導課長","answer":"要望、こういったものをヒアリングいたしまして、その部分のＡＬＴを多く配置している状況があります。１年生から取り組んでいるという状況ですけれども、平成１４年度の段階ではおよそ半分の学校で取り組んでいる状況があります。","id":"exchange-096"},{"speaker":"木下委員","kind":"質問","question":"１年、２年と先生が変わらず続けたほうがいいんじゃないかなというふうにも思っているんですが、そういう状況はどうなんでしょうか。〔時間切れにより、答弁なし〕。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-097"},{"speaker":"山路委員","kind":"質問・要望","question":"１６１ページ、１６７ページ、お伺いいたします。そして多くの区民の方に見ていただきたいと思ったわけですが、どれくらいの拝観予定者を見込んでいらっしゃるか、お伺いいたします。","respondent":"上川内生涯学習課長","answer":"それから、予定者数ですが、１０月５日から始まりまして、現在１,０８４名の入館者がございました。課を上げていろいろな係で区民大学の講座でも江戸４００年の下屋敷にちなんだ講座を催したり、追い越せという意気込みで行っているところです。","id":"exchange-098"},{"speaker":"山路委員","kind":"質問・要望","question":"私が住んでいる地域はどうなんだろうと思って、数多くの方にも見ていただきたいと、まず感動したわけです。今後の運営についてどういうふうに考えていったらいいかということにつきまして、この３年ぐらいの経緯を紹介していただけますか尋ねました。","respondent":"上川内生涯学習課長","answer":"「ヨーロッパのレース展」が６,３７０人、平成１２年度が、３,００９人です。特別展の内容によって、かなり入館者数が違ってくるという傾向です。","id":"exchange-099"},{"speaker":"山路委員","kind":"提案","question":"ガイダンスのご提案を申し上げたら、観光協会でやられているということで、非常に喜ばれているわけです。一体的な運営をされているということはお伺いしているわけですけれども、今後の何かお考えがあったらお聞かせをほしいと求めました。","respondent":"上川内生涯学習課長","answer":"委員ご指摘の歴史館につきましては、小さいお庭ですけれども、かなり皆さんの目を癒すお庭もあります。一体的に、伝統文化の普及を目的にした歴史館ですので、これから若い人たちにもいろいろな事業展開をしながら進めていきたいと考えています。","id":"exchange-100"},{"speaker":"山路委員","kind":"質問","question":"いろいろ考えていらっしゃるみたいですけれども、伝統文化保存はまだたくさんあると思うんです。歴史館の貸し出し、あるいは小グループの会社などの、この辺についてはどのようにお考えか尋ねました。","respondent":"上川内生涯学習課長","answer":"茶室、講堂、小講堂等をお貸ししております。貸し出し時間も朝の９時から夜の２１時までということでやっておりますが、今後お茶室等のＰＲもさらに一層進めてやっていきたいと考えています。","id":"exchange-101"},{"speaker":"山路委員","kind":"質問・要望","question":"もちろん文化財保存という立場がありますので、歳出が多くなると思いますが、もっと多くの方に来館いただくように要望しておきます。ここ数年情報教育についてはいろいろな角度からお伺いしてきたわけですけれども、昨年お伺いしたときは、その辺の状況についてお伺いいたします。","respondent":"谷田部学務課長","answer":"４２台、１８校全校に整備し、ＣＡＴＶの回線を利用いたしましてインターネットのほうに接続できるという状況になってあります。調べ学習に使ったり、基本的なパソコンの操作の授業ですとか、さまざまな教育の場面で使われているという状況です。","id":"exchange-102"},{"speaker":"山路委員","kind":"提案","question":"事業情報データベースと学校ヘルプ、これは一般質問で提案したことがあるんですが、その辺についてはどういう活用をされていますか尋ねました。","respondent":"谷田部学務課長","answer":"今、学校ヘルプというソフトの関係でございましょうか。具体的に私のほうで詳細をつかんでおりませんので、これ以上のことはご説明申し上げられませんが、一応そういう状況になっているということです。","id":"exchange-103"},{"speaker":"山路委員","kind":"質問・要望","question":"いろいろなソフトがありますので、いろいろ研究をされて、生かしてほしいと求めました。情報のモラルについては指導課長のほうから先ほどお話がありましたけれども、この辺についてはどういう指導をされているか、聞かせてください。","respondent":"中島指導課長","answer":"一つには、情報というものが多様に存在しておりまして、それらを保護する必要性の部分ですとか、情報自体の考え方を指導する場面があります。それを指導しております。","id":"exchange-104"},{"speaker":"山路委員","kind":"質問・要望","question":"情報倫理教育というのが今言われておりますが、この辺についても研究をして、指導の中に入れてほしいと求めました。３点目の、〔時間切れにより、答弁なし〕。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-105"},{"speaker":"須藤委員","kind":"質問・要望","question":"その辺の学校、地域とのなじんでいったりとかというのはどういうふうに教えていらっしゃるのか、お教え願いたいと思います。どうしても、その辺をどうやって私学に負けない形の対応をしようと考えていらっしゃるのか、教えてほしいと求めました。","respondent":"中島指導課長","answer":"その中で、この地域をめぐる研修というものを位置づけてございまして、そこで自分たちが勤める品川区を認識してもらうという足掛かりにしています。この一つの流れを身をもって体験して身につけてもらう、これが何よりも資質向上につながる部分というふうに考えてあります。","id":"exchange-106"},{"speaker":"須藤委員","kind":"質問・要望","question":"その中で合うようにしていっていただきたい、こんなふうに思うので、よろしくお願いいたします。社会体育費というふうにあるわけですけれども、社会教育費の意味合いというのはどういう意味合いかなと思うんですが、ちょっと説明を求めました。","respondent":"上川内生涯学習課長","answer":"社会教育費、社会体育費とありますが、社会教育につきましてはスポーツの部分と文化的な部分、それぞれ社会教育の活動支援をするものですが、社会教育費につきましては、スポーツのところを除きました全体的な附属機関等の経費、そういうものが付加されたものです。","id":"exchange-107"},{"speaker":"須藤委員","kind":"質問","question":"社会教育費のほうには、片や文化振興事業団という形で区民の生涯学習を含めて、文化教養という形で、一つの財団ができているわけです。その辺はどういうふうに考えていっていいかなというので、社会教育費の意義というのを聞かしてもらったんですけれども、いかがか尋ねました。","respondent":"上川内生涯学習課長","answer":"社会体育費のほうはスポーツ協会に入ってあります。基礎的なもの、区民が広く、もう少し裾野を広げるような事業をするという切り分けになってあります。","id":"exchange-108"},{"speaker":"須藤委員","kind":"質問","question":"例えば公開講座をやっています。もっといい形のこの部分が、いわゆる生涯学習として生きてくるのではないかなというふうに感じるんですけれども、その辺いかがか尋ねました。","respondent":"上川内生涯学習課長、中尾根企画部長","answer":"今まで社会教育というところから、生涯学習という概念に変わってきているわけで、生涯学習というのはすべてを網羅するということになってきています。区民生活にもっと密着したものという考えがありますので… 歴史的には、先ほど言いましたように、文化の面の強さと、学習の面の強さで歴史的な経過をそのまま現在まで引きずってきているです。","id":"exchange-109"},{"speaker":"須藤委員","kind":"質問","question":"その辺を見極めながら、こういった事業計画というのもつくっていってほしいと求めましたので、よろしくお願いいたします。体育館のほうで、予約システムをインターネットでやるようになったんですけれども、これを取り入れてから問題点は何か生じませんか尋ねました。","respondent":"上川内生涯学習課長","answer":"予約システム、体育館のほう、約６割の方がネットに参加されております。問題点は今のところは伺っておりません。","id":"exchange-110"},{"speaker":"須藤委員","kind":"質問","question":"顔が見えないものですから、顔が見えなくなってきちゃって、条件がそろっていれば全部ＯＫになってくる。今いい形をとっているんだけれども、次の問題点というのがその辺が出てきているので、そういうことに対してはいかがか尋ねました。","respondent":"上川内生涯学習課長","answer":"氏名、代表者を出していただきますので、従来どおり特定はできます。即刻やめていただくとか、何もなくできるというわけではございませんので、そこのところは実態を踏まえて注意をしていくということになると思います。","id":"exchange-111"},{"speaker":"須藤委員","kind":"質問","question":"その辺は課長のほうでスポーツ協会のほうへよく尋ねていただいて、今度その辺のシステムを変えていきましょうという話をさせていただきました。そういうところで、使用料を取っているんですから、それに見合った場所を提供するという考えはいかがか尋ねました。","respondent":"梶教育委員会事務局副参事","answer":"戸越体育館のほうの競技場、アリーナのほうに畳を敷いて、実際に区民体育をやっているような状況です。現在検討中ですので、その中で利用団体等のお声を聞きながら、より使いやすい方法で検討をしていきたいと考えています。","id":"exchange-112"},{"speaker":"中塚委員","kind":"質問","question":"子どもたちのことをどう考えているのでしょうか。この意見をどう受け止めますか。","respondent":"鷹倉庶務課長","answer":"私どもにもいろいろメールがまいりますけれども、いい意見もありますし、今のお話のようにため息の出るメールもあります。私ども頑張れというような励ましのメールを受けながら、今後進めていきたい、このように思ってあります。","id":"exchange-113"},{"speaker":"中塚委員","kind":"質問","question":"たった２年間で第１校、そして第２校と、区民の怒りは当然ではないでしょうか。このようなやり方が区と区民が信頼に基づいたパートナーシップができていると思うのか尋ねました。","respondent":"鷹倉庶務課長","answer":"大井地区における小・中一貫校につきましては、まさに区民の方々の意見を十分聞きながら学校を決めていくという形で進めさせていただきました。地元の説明、あるいはさまざまな関連機関の意見を十分聞きながら進めてきたですので、このように私どもは考えてあります。","id":"exchange-114"},{"speaker":"中塚委員","kind":"質問・要望","question":"保護者と区民の間にどういった区民参加、協働があったのでしょうか。９月９日前に、なぜ７月に夏休み前に挙げられた保護者の意見に回答をする必要がなかったのか尋ねました。","respondent":"鷹倉庶務課長","answer":"決められたルール、手続的に進めなくてはいけないところをまず聞く。あるいは文教委員会に報告する、これがまさに民主主義社会のルールと、このように考えてあります。","id":"exchange-115"},{"speaker":"中塚委員","kind":"質問・要望","question":"地域説明会の早急な開催を求めていきたいと思いますけれども、そもそも品川区は公聴会、地域説明会をどのように位置づけているのでしょうか。これらはどういった場だと思っているのか尋ねました。","respondent":"鷹倉庶務課長","answer":"私ども公聴会、地域説明会、いろいろな区民の方々と接する場があります。そのご質問に答えていくには、ある程度の方向性を確認しながら、住民の方々に説明していく責任があると思ってあります。","id":"exchange-116"},{"speaker":"中塚委員","kind":"意見","question":"説明会の開催について、区の説明をするだけではなくて、その場で区民の意見を直接聞く」と書いてあります。公聴会とはどういう場なのか、もう一度説明を求めました。","respondent":"山田広報広聴課長","answer":"ただいま中塚委員からご説明がありましたとおり、区の施策の新しい施設建設でありますとか、いわゆるフェース・トゥ・フェースで説明をしていく。きめ細かに説明をして、区民の皆様のご理解を得るということで開催をする公聴会、また説明会ということになってあります。","id":"exchange-117"},{"speaker":"中塚委員","kind":"質問・要望","question":"その場で区民の意見や要望を聞き、施策や建設計画への反映を図る、こうはっきり述べているわけです。どうして９月９日の計画決定前にこうした公聴会、地域説明会を開催しなかったのか尋ねました。","respondent":"鷹倉庶務課長","answer":"９月９日の教育委員会の決定の前に区民の方々の代表である、例えばＰＴＡの方々、あるいは地域の方々の声を聞いてあります。聞いていないということではございません。","id":"exchange-118"},{"speaker":"中塚委員","kind":"質問","question":"聞いているなら、なぜ回答しないんですか。もう一度説明を求めました。","respondent":"古川教育次長","answer":"１点、原小学校における説明会、さまざまなご意見に対して、なぜ回答しないのかと。あえてこのことに一つ一つ回答を決定の前にするという考え方は私どもは持ってございません。","id":"exchange-119"},{"speaker":"中塚委員","kind":"質問","question":"教育委員会にも保護者に対しても問答無用の姿勢で、しかも、教育委員会の計画決定の場は非公開、これはどういう姿勢なんですか。そして、公聴会、住民説明会をきちんと保障すべきだと思いますけれども、いかがか尋ねました。","respondent":"鷹倉庶務課長","answer":"政策決定段階での教育委員の意見、あるいは区民の意見をどのように反映すべきか。それを十分承知していただいた上で決定していただく、これが教育委員会の正しいあり方だと、このように考えているところであります。","id":"exchange-120"},{"speaker":"中塚委員","kind":"質問","question":"教育委員会とは一体何なんですか。説明を求めました。","respondent":"鷹倉庶務課長","answer":"そして全体像をつかんでいただきながら判断をしていただく、教育委員会としての最終的な最高の意思決定機関です。したがって、事務局はいろいろ案を練るということは、私どもの事務局としての責任、このように考えてあります。","id":"exchange-121"},{"speaker":"中塚委員","kind":"質問","question":"その後、なぜ回答をしないのかという申し入れをしても、今日に至ってもいまだに回答がないわけです。どうして一人ひとりの区民に対して、行政として姿勢を改めるべきだと思いますけれども、いかがか尋ねました。","respondent":"鷹倉庶務課長","answer":"今の２回の申し入れはきちんと申し入れがされたですけれども、提出の仕方がちょっといかがなものかなという部分が確かにあります。ただし、中身的には、ただいま検討をしています。","id":"exchange-122"},{"speaker":"中塚委員","kind":"質問","question":"でも、今回の９月９日に出したもの対しては、回答できないという理由は全くないんですよ。提出したものに対して、全く連絡がない、こういう姿勢は大変問題だと思いますけれども、いかがか尋ねました。","respondent":"鷹倉庶務課長","answer":"きちっと答えをしていくためには、やはり出し方もきちっとしていただくことが肝要かというふうに考えてあります。","id":"exchange-123"},{"speaker":"中塚委員","kind":"質問・要望","question":"改めてここで区長のお考えを伺いたいんですけれども、本会議の場でも、区民が主人公だとはっきりと申しております。区民の参加、協働の推進について、ぜひ区長のお考えをお伺いしたいと思います。","respondent":"古川教育次長","answer":"今回大井地区における小・中一貫校の設置場所、教育委員会が一定の判断をすべき内容であろうと、こういうふうに考えてあります。私どもは今回小・中一貫校を大井地区を決めるにあたりましては、一定のルールに従って今回決めてきた、そのように考えてあります。","id":"exchange-124"},{"speaker":"中塚委員","kind":"提案","question":"地域への説明、回答、合意のない小・中一貫校計画の決定は見直すべきだと思います。ぜひ早急な公聴会、住民説明会の開催を要望するとともに、計画の見直しを提案したいと思いますけれども、いかがか尋ねました。","respondent":"古川教育次長","answer":"無計画、独断専行ですが、私どもは決してそういうふうに考えてございません。こういうふうに考えてありますので、これは教育委員会の決定ですので、そのような考え方は持ってございません。","id":"exchange-125"},{"speaker":"中塚委員","kind":"質問・要望","question":"私は、平成１３年度に発表された、実際の審議は平成１０年ですか、ここから長い間にかけて審議をして、平成１３年に発表された。きちんと区民の意見に耳を傾けて、今後の運営に反映してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-126"},{"speaker":"須貝委員","kind":"質問","question":"通常の成績ですか、３学期制をとっている学校があるんですけれども、その成績票は教育委員会で把握しているんでしょうか。そして、点数なども、例えばその学校において社会何点取っている人が何人いるとか、その辺をお伺いしたいと思います。","respondent":"中島指導課長","answer":"そういった細かい部分等について逐一こちらのほうで状況を把握している部分はございません。成績の一覧表を作成していますので、その中でどういった比率で成績が付けられていっているか、そういう状況は把握しています。","id":"exchange-127"},{"speaker":"須貝委員","kind":"質問","question":"今のは、例えば中学校でもいいんですけれども、２学期に学期末テストをやりますね。そのときに点数何点の子が何人いるとか、そういう細かいことはこないんか尋ねました。","respondent":"中島指導課長","answer":"そういった細かい部分までの情報ではございません。","id":"exchange-128"},{"speaker":"須貝委員","kind":"質問","question":"９科目なら９科目、それがどういう割合にあるか、それじゃ成績が伸びようがないんじゃないですか。その辺ちょっとお伺いします。","respondent":"中島指導課長","answer":"それに従いまして子どもたちの基礎学力の定着を図るということは、これはそれぞれの学校長が自分の学校の経営方針のもとに進めていく内容です。","id":"exchange-129"},{"speaker":"須貝委員","kind":"質問・要望","question":"それをある学校でもいいですから、そういう世界なんですから、そこら辺をよく把握してほしいと求めました。それがウイークデーの午後２時からやるとか、午後３時からやって、それがどうして周知させようという方針になるのか、そこをお伺いしたいと思います。","respondent":"中島指導課長","answer":"それぞれ各学校の年間のスケジュールにおいて決定されておりますけれども、例えば道徳の授業公開講座を土曜日に実施している学校もあります。月曜日から土曜日に授業を実施して、ウイークデーに見に来れない方々に土曜日に見ていただくという体制をとっている学校も多くあります。","id":"exchange-130"},{"speaker":"須貝委員","kind":"質問","question":"引き続きまして、地域スポーツの推進についてお伺いしたいと思います。スポレク推進委員会の人たちは、それぞれのクラブを普及させているわけですから、地域の人のために。","respondent":"上川内生涯学習課長","answer":"地域の人にもスポーツの楽しみをということで、教室を開いていただいていることに対しては、感謝しております。１７地区ありますから、楽しくスポーツを広めていただくのが趣旨ですから、調整してまいりたいと思います。","id":"exchange-131"},{"speaker":"須貝委員","kind":"質問・要望","question":"要望としてですけれども、バレーボールをやる人、ソフトバレーもあります。どうぞ皆さんだれでも入ってくださいという形をとっているわけですから、もうその人たちは十分やっていると思うんです。","respondent":"上川内生涯学習課長","answer":"スポレク推進委員の方たちには、自主的にさまざまな活動をお願いしているところでございまして、その地区のスポレク推進委員会の中で、こういうことをやっていきたいというふうに決めていると思いますが、詳細につきましては、もう一度お話を伺わせていただきたいと思っています。","id":"exchange-132"},{"speaker":"中島委員","kind":"質問・要望","question":"小学校１年生と中学３年生が、学校という集団において一つの形で成り立つのでしょうか。そのまま９年間同じ小さな集団の中で守られていては、井の中の蛙にならないか尋ねました。","respondent":"中島指導課長","answer":"９年間を見通して子どものなめらかな教育活動の継続、また継続的に延ばしていきたい、大きな願いがここにはあります。この９年間の中でさまざまな子どもたちの係わり、そして成果がこれまでにはない新しい形で考えられるものと考えています。","id":"exchange-133"},{"speaker":"中島委員","kind":"質問・要望","question":"ただ、確かに小学校から中学校へという新しい世界、これも大事な視点ではないかなと思います。そういったこともこれからの教育の中に取り入れていっていただきたいなと思うんですが、その辺のところはいかがか尋ねました。","respondent":"中島指導課長","answer":"４・３・２という大きな学習のまとまりで節目節目を持ってまいりますけれども、６年生が終了した段階で小学校の教育課程の終了という節目がありますので、ご指摘のような形の新たな部分も誕生してくるのではないかと考えます。","id":"exchange-134"},{"speaker":"中島委員","kind":"質問","question":"部活動はどうなるのか、こういったことを質問したけれども、答えが出なかったということの苦情がきております。そうしたきめ細かな、言葉一つで相手の心というのは変わってくると思うんですが、いかがか尋ねました。","respondent":"鷹倉庶務課長","answer":"確かにきめ細かな配慮、あるいは言葉のニュアンスの受け止め方ということがありますので、今後十分注意しながらやっていきたいと思ってあります。","id":"exchange-135"},{"speaker":"中島委員","kind":"質問・要望","question":"これは大変難しい問題かもしれませんが、何らかの形でフォローをしていただきたいなと、これは要望しておきます。バケツ一杯ぐらいの水を出してから使ってくださいよと言われているんですが、学校のほうはどうか尋ねました。","respondent":"鷹倉庶務課長","answer":"今私どもの捉えている部分では、学校の水道管について鉛を使っているものはないというふうに現状を把握しています。直ちに新しいものに代えたいと思ってありますけれども、今把握しているところではない、こういうふうに捉えてあります。","id":"exchange-136"},{"speaker":"中島委員","kind":"質問","question":"昭和６０年以前に建っている建物の中というのは、水道局では、コーキングを全面的にやらない限りは入っている可能性というのはあると思うんです。ですから、これは調査をする必要があるんじゃないかなと思うんですが、いかがか尋ねました。","respondent":"谷田部学務課長","answer":"水道水等の水質の検査も実施していますけれども、今のところ学校については安全、基準値の中におさまっているという状況です。","id":"exchange-137"},{"speaker":"中島委員","kind":"質問・要望","question":"水をある程度出してしまえば、ほとんど何かが発見されるということはないと思うんです。ですから、生徒のほうに注意は必要じゃないかなと思いますので、これはぜひ要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-138"},{"speaker":"川西委員","kind":"質問","question":"これはどういう方法で購入をして、単価が低いですから、こういう器具等は一時にくらべて安くなっているというふうに直感しています。同じ２割引きでも１社にこだわって見積もりをとるのかどうか、その辺についてお伺いいたします。","respondent":"谷田部学務課長","answer":"夏季施設の中で検討をするのか、全体の宿泊行事の中で検討をするのか、今後考えていきたいというふうに思ってあります。学校によってもクラブ活動等の取り組みも状況も違いますし、多ければいいのか、部活動を活性化していくのは今後も必要だというふうに思ってあります。","id":"exchange-139"},{"speaker":"川西委員","kind":"質問","question":"今の最後の問題は、総務費とかということになりますから、答弁いただくのはまずいか尋ねました。","respondent":"西島経理課長","answer":"給食調理の物品の購入ですけれども、まず一つは、金額で分けてあります。４０万円以下の物については随意契約ということが可能ですけれども、あるいは一般競争入札ということで購入するのが原則です。","id":"exchange-140"},{"speaker":"川西委員","kind":"質問・要望","question":"１校実施で９８人というのは、これは自費ですから、立派だと思います。それから、校医の報酬のあり方、これもＣ、この二つについて説明をしていただきたい。","respondent":"谷田部学務課長","answer":"給食のコストが高いというような話がありまして、文部科学省はそれを受けまして、そういうことでＣ評価ということで見直していくという考えです。報酬も一律ということで、その辺で校医報酬等の見直しはすべきではないだろうかということで、一応Ｃ評価をさせていただいたです。","id":"exchange-141"},{"speaker":"川西委員","kind":"質問","question":"教育センターの運営の今後について伺います。学務課長だけでなくて、指導課長も力を入れて、ぜひ。","respondent":"中島指導課長","answer":"教育センターの運営事業です。助言のための学校訪問、こどものフリーダイヤル相談、こういった形にこの事業が充てられてあります。","id":"exchange-142"},{"speaker":"石田委員","kind":"質問・要望","question":"１５４ページの夏季対策経費なのかどうかわからないんですけれども、１５９ページ、１点だけ聞きたいと思います。こういう段取り、議会のルールに則ってやってきたと思いますが、そこら辺の点を区長はどのように考えているか教えてほしいと求めました。","respondent":"高橋区長","answer":"説明会等々、それはあくまで補完をするもの、そういうふうなものの考え方で進めしています。このような方針で今後も進めていきたいと考えています。","id":"exchange-143"},{"speaker":"石田委員","kind":"提案","question":"これは提案でありますが、今そのパーセントを上げて、十何％まで持っていこうとかしているわけです。教育するほうなんですから、どういうふうに出すかは別としても、各学校の教員のそういう部分をとの意見を述べました。","respondent":"中島指導課長","answer":"こういったような学校としての率で表していくということは可能な部分ではないかなとも考えております。それぞれの学校の態度表明ですので、こういったお話につきましては、また校長会のほうとも十分連携を図りながら進めていく必要があろうかと考えます。","id":"exchange-144"},{"speaker":"石田委員","kind":"質問","question":"ちょっとお言葉を返すようですが、子どもたちにもちゃんと、今言った個人情報を補完してやっているわけですよ。そういうのも少し考えたらどうですかということなので、もう１点、もう一度突っ込んだ回答があればお聞かせ願いたいと思います。","respondent":"若月教育長","answer":"しかし、では、それをいつ、どんな段階でやるのかということは、これはまたいろいろな考え方があろうかと思います。これは一つのこれからのあり方かもしれませんので、考えさせていただきたい、かように思っております。","id":"exchange-145"},{"speaker":"石田委員","kind":"質問","question":"出勤でやっているわけだから、そういう捉え方でいくと、そういう意味のサマースクールを今後どういうふうにしていこうと思っていらっしゃるのか。子どもたちの夏休みというのをどういうふうに捉えていこうと思っていらっしゃるのか、その点をちょっとお聞きしたいと思います。","respondent":"中島指導課長","answer":"英検への対策、こういったようなそれぞれが課題を持って学習に取り組むというような実施の学校が増えてきているという状況があります。教育委員会といたしましても、各学校が自主的に取り組んでいくこういった内容につきましては、支援してまいりたいと考えております。","id":"exchange-146"},{"speaker":"石田委員","kind":"意見","question":"どうしても父兄たちから出てくる言葉は、出てきて大変ね」と、こうくるわけです。そういうことをある一定程度ホームページで出していく方向性も私は一つだと思うんですが、そこら辺の点のお考えをお願いいたしますとの意見を述べました。","respondent":"中島指導課長","answer":"品川区の教員の勤務という状況の中で、その紹介というような場面は考えられていけると思います。検討してまいりたいと思います。","id":"exchange-147"},{"speaker":"石田委員","kind":"質問・要望","question":"せっかく子どもたちに向けてこれだけ今教育改革をさまざま子どもたちがよくなる方法というのをやられているわけですから、これは要望にいたして、私の質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-148"},{"speaker":"山村委員","kind":"質問","question":"私からは１５２ページ、心の教室相談員活用調査研究費と、１５３ページ、まちの人々から学ぶ事業について、ご質問をします。それについての解決はどういう手法で今は挑まれているのかというのをまず教えてほしいと求めました。","respondent":"中島指導課長","answer":"もちろん対応する中には、学校への不満、こういったようなものもあるというふうに聞いております。不登校等の場合と違いまして、いじめという現象があることを学校が認識した段階ですぐにそれに係わる。","id":"exchange-149"},{"speaker":"山村委員","kind":"質問","question":"これは本当にすばらしいと思っておりまして、基本的にこの授業がなぜ勉強するのかというのの、なぜを答える部分だと私は思っております。学校のほうの受け持ちになっていらっしゃるのか、そういう面の費用に関しては考えていらっしゃるのか、そこら辺を説明してほしいと求めました。","respondent":"中島指導課長","answer":"こちらのほうは区のほうで予算化をして、学校の実施状況に応じて、現在は区内の共通商品券をお渡ししているという状況があります。平成１４年度の実施状況ですと、障害のある方々など、いろいろな方がいらっしゃいます。","id":"exchange-150"},{"speaker":"山村委員","kind":"質問・要望","question":"本当にいい人材に来ていただかないと、こういう事業は実りがないと思いますので。授業の時間割としては普通の授業に組み込まれてやられているんでしょうか、そこら辺を教えてほしいと求めました。","respondent":"中島指導課長","answer":"これは通常の授業で学ぶという形をとってありますので、放課後等ではございません。","id":"exchange-151"},{"speaker":"山村委員","kind":"意見","question":"なぜ勉強するのかということが小学校時代は一番わからなかったと私は思っておりますので、ただ親に勉強しろ、勉強しろと言われて勉強していた。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-152"},{"speaker":"南委員","kind":"質問","question":"１６０ページの幼保一元化の関係で質問をしたいと思います。先ほどもありましたけれども、二葉幼稚園で幼保一元化の事業も行うようになりましたが、クラス配置、先生の配置、クラス人数、そこを説明を求めました。","respondent":"谷田部学務課長","answer":"１歳児は定員１０名のところ１０名、２歳児が定員１２名で、在園児が１２名、３歳児が定員１５名のところ１４名という状況です。それから、幼稚園のほうの関係の在園児ですけれども、４月１日現在で４歳児が６０名、５歳児が５８名という状況です。","id":"exchange-153"},{"speaker":"南委員","kind":"提案","question":"構造改革特区の第三次提案についてということで、幼保一元化特区、こういうことで載っておりました。この内容についてお知らせくださいとの意見を述べました。","respondent":"榎本行財政改革担当課長","answer":"構造特区の話ですので、私のほうからご説明いたします。３点目が、保育所の入所要件の緩和を幼保一元化においては緩めてほしいということの３点を提案したものです。","id":"exchange-154"},{"speaker":"南委員","kind":"提案","question":"なぜこういう特区に提案をし、今もう既に幼保一元化ということで二葉幼稚園が始まっていますよね。ですから、その関係であえてなぜ改革特区のこれに名乗りを挙げてきたのかという、その辺の区のほうの変化する理由を教えてほしいと求めました。","respondent":"榎本行財政改革担当課長","answer":"受けない形で最初運営を考えていたわけですけれども、さらに柔軟な運営ができるということで、提案をさせていただいたものです。","id":"exchange-155"},{"speaker":"南委員","kind":"提案","question":"今ご答弁をいただいたように、品川区が特区に提案したというのは運営上の問題だというんですが、それをできるようにするというふうなことですよね。発達の促進、こういうものが大前提になっていないというふうに思うんですけれども、この点はどうか尋ねました。","respondent":"谷田部学務課長","answer":"市区町村長の事務というような制度上の問題もありまして、完全な一体化というのはなかなか難しい、一元化は難しいというのが現状です。ですから、ご心配の懸念はないものというふうに考えてあります。","id":"exchange-156"},{"speaker":"南委員","kind":"質問・要望","question":"改めていろいろ要望を聞いたんですけれども、廃止しないでほしいという要望を出したそうですが、大変憂慮すべき事態が発生した。ですから、ほかの会派からも指摘されておりますので、この問題について経過を簡単にお願いします。","respondent":"上川内生涯学習課長","answer":"ヘルストレーニング事業ですが、昭和４７年から実施されております。三十数年経ちまして、説明の経過につきましては、現場のところで館長をはじめ職員が対面をしながら説明をしております。","id":"exchange-157"},{"speaker":"南委員","kind":"質問・要望","question":"文教委員会でもそのことが指摘されているんですが、その後どういうふうに現場のほうでは対応をされているんでしょうか。これからの進め方としてきちんとやるべきだということを強く要望して、残念ですけれども、終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-158"},{"speaker":"三上委員","kind":"質問・要望","question":"私も当初からこの問題についてお伺いしようと思っておりましたので、同じような質問にならないように、ちょっとお伺いしたいと思います。教育財産としてだけ購入された土地であったのかどうかということで、そこらあたりの性格的な部分についてご説明ほしいと求めました。","respondent":"浜脇住環境整備課長","answer":"今の荏原第一中学校のグラウンドに隣接する、住環境整備課として管理をするといいますか、所有のほうは住環境整備課のほうが所管して持ってあります。それ以外の大部分のグラウンドにつきましては教育委員会の所管というふうになってあります。","id":"exchange-159"},{"speaker":"三上委員","kind":"質問","question":"こういうように伺ってみると、両方がどのように維持管理について話し合いをしていくかということについて、どのように具体的に話し合われてきたんか尋ねました。","respondent":"浜脇住環境整備課長","answer":"たしか荏原第一中学校のほうが５,５００m2ぐらいで、私どもが持っている広場の面積は１,０００m2ですので、グラウンドに印をつけてあります。教育委員会と住環境整備課が話し合いを持って解決していこうと、こんなような確認書を取り交わしています。","id":"exchange-160"},{"speaker":"三上委員","kind":"質問・要望","question":"ですから、このことについてしっかりとご返事をほしいと求めました。子どもちを含めて、水の問題として、長期間使われなかった場合にはどういうふうにしなさいというふうに児童・生徒に話をしているんか尋ねました。","respondent":"鷹倉庶務課長、谷田部学務課長","answer":"確かに近隣の方に非常に迷惑をかけているということがあります。委員ご提案のございました、砂塵を防止するという働きは当然ありますので、この点も踏まえながら検討をしてまいりたいと思ってあります。 水道の関係ですけれども、新学期に入る前に各学校では、擁護教諭を中心といたしまして、蛇口を開けまして、管の中にとどまっている水を出すというような作業を必ずしております。","id":"exchange-161"},{"speaker":"三上委員","kind":"質問・要望","question":"荏原第一中学校のほうはぜひ早急に対応していただきたい。それから、水の問題については、水を出しなさいと、これはなぜ出さなければならないんか尋ねました。","respondent":"谷田部学務課長","answer":"蛇口を締めた状態ですと、管の中に当然水が残っていますので、その水が傷むということで、細菌等の繁殖も当然あるでしょうから、そういった汚れた水は出して、新しい水を使うということで、そのような指導をしているです。","id":"exchange-162"},{"speaker":"三上委員","kind":"質問","question":"こういうことであると、こういうことでその対応をされてきたということは私も十分分かった上でお尋ねしているんです。現在は品川区の、学校として特定した場合に、給水管がどれぐらいの年数経っているのが多いんか尋ねました。","respondent":"鷹倉庶務課長","answer":"その時期に合わせて給水管を当然手当てしているということが考えられます。そういうことですので、それぞれの学校の建設時が給水管を配置した時期ではないかと、このように推測されます。","id":"exchange-163"},{"speaker":"三上委員","kind":"質問","question":"少なくとも２０年以上は経っている学校が多いのかな。錆びを呼んでいるという形になってくるわけですから、赤水対策ということについて、どういう取り組みを今教育委員会としてはされているんか尋ねました。","respondent":"鷹倉庶務課長","answer":"手元にちょっとデータがないわけですけれども、基本的に２０年程度で老朽化の取り替え、先ほど申し上げた、全体的な校舎をいじっていくときに、折に触れながら、老朽管の取り替えをしています。","id":"exchange-164"},{"speaker":"三上委員","kind":"質問・要望","question":"お金もかかりますから、そういう意味にあっては、しっかりと赤水が出ない対策というものをそれなりにこれからとっていってほしいと求めました。それから、まだ時間がありますので、夜間校庭開放について、今年で何校になったんか尋ねました。","respondent":"上川内生涯学習課長","answer":"１５校です。","id":"exchange-165"},{"speaker":"三上委員","kind":"質問・要望","question":"自分の体力に合わせて運動をやりたいという人が、この日は思いっきり土の上で体を動かして汗を流したいと、こういうふうに要望する。何らかの形で個人の資格で借りられるように、校庭を開放をしてもらいたいとお願いしていたんですけれども、その考え方についてはどうなんか尋ねました。","respondent":"上川内生涯学習課長","answer":"夜間校庭開放、校庭は広いということがありますので、できるだけ多くの方に利用していただきたいということで、団体を優先に貸し出ししているものです。","id":"exchange-166"},{"speaker":"三上委員","kind":"質問・要望","question":"だけども、その人たちが、この日は思いっきり使えるということがあるまでは、どれくらい来るかわからないという、そういうことだってあるはずです。そこのところをしっかりと考えて取り組んでいただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-167"},{"speaker":"塚本委員","kind":"質問・要望","question":"学校図書の関係と、地域のスポーツ施設をどう考えるかということ、最後にプラン２１に関連してお伺いいたします。言葉ですから、どうしたらいいのかなというようなことを今思っておられることがありましたら、お知らせいただきたいです。","respondent":"中島指導課長","answer":"小学校、中学校ともに学校における読書活動というものの重要性は教育委員会のほうでも十分認識しています。さまざまな取り組みをやりながら、今後一層こういった子どもたちが図書に触れる、読書活動を推進していくことが重要であると強く認識しております。","id":"exchange-168"},{"speaker":"塚本委員","kind":"質問","question":"そして一般の図書館は地域館といいますか、地域の中央館みたいな役割が分けられるのではないかというイメージを持っております。そういう方向性、すまいるスクールが一挙に全校に行き渡るわけですから、いかがか尋ねました。","respondent":"古里品川図書館長、中島指導課長","answer":"区立図書館のほうが指導課と今協議をいたしておりまして、将来学校の図書室を地域に開放できないかということも今模索をしています。区立図書館としてもぜひ子どもたちの読書環境の整備という点で積極的に取り組んでまいりたいというふ… 中学校におきましても、これは１校のみですけれども、放課後の時間を開放しているというような状況があります。今図書館長のほうでも申し上げましたように、今後これの拡充を図っていくということは重要な課題であると考えております。","id":"exchange-169"},{"speaker":"塚本委員","kind":"質問・要望","question":"方向性を確認できて安心しておりますけれども、地域の図書館との連携と役割分担を１点注意していただきたいのと、それから。どういう社会教育的な、企業の中でのということですが、取り組みをしているかということを承知しているかということをまず伺いたいと思います。","respondent":"上川内生涯学習課長","answer":"申し訳ございません、詳細は承知してはおりません。","id":"exchange-170"},{"speaker":"塚本委員","kind":"質問","question":"これは大事な視点ですから、ぜひそういうものを視野に入れてほしい。品川区内の公共施設で管理しているところの中で、例えばバスケットボールの公式のコートが取れるぞというところがどれだけあるか承知していますか。","respondent":"上川内生涯学習課長、中島指導課長","answer":"二つの体育館は正式ということは把握しています。 区立小中学校では戸越台中学校の体育館だけです。","id":"exchange-171"},{"speaker":"塚本委員","kind":"意見","question":"と同時に、先ほどの話とつなげると、企業が既にそういうものを持っておるわけです。ある部分で社会還元をしたい、子どもたちにコーチをしたいという人も必ずいるはずですから、いかがでございましょうかとの意見を述べました。","respondent":"上川内生涯学習課長","answer":"委員おっしゃるとおり、区内のそういういい体育館等がございましたら、区民のスポーツ振興のためにはいろいろ連携をして、利用する等連携をお願いしていきたいと考えています。","id":"exchange-172"},{"speaker":"塚本委員","kind":"質問・要望","question":"これからの話だということですから、指摘しておきます。何か文化的な興行的なことをやればいいんだろうというような時代でございましたけれども、何かコメントがあればほしいと求めました。","respondent":"中尾根企画部長","answer":"これが基本方針として三つ載せてあります。そのような方針を持っておりますので、そういう協議はしていきたい、このように考えてあります。","id":"exchange-173"},{"speaker":"塚本委員","kind":"質問・要望","question":"プラン２１ですが、今年の４月に冊子第３版が出ておりまして、拝見いたしました。組織を動かして何事かの成果物を得る、経営ということの資源というものはどういうものがあるというふうに、お答えほしいと求めました。","respondent":"中島指導課長","answer":"現在進めております成果基盤型の学校づくりの中での資源というご質問かと思います。ただ、その中で、学校で一番大きなものは、子どもたちに指導をする教員、この人の部分ではないかと考えます。","id":"exchange-174"},{"speaker":"塚本委員","kind":"質問","question":"権限、現状で校長、実際現状で持っている教育委員会の力をどこまで現場に渡しているかということには少なからず疑問を持っています。一旦ある種の風土ができたんですから、いろいろなことを次のステップで出していかなければいけないと思うんですけれども、どう考えておりますか。","respondent":"若月教育長","answer":"ただ、今の制度から言って、できることと、できないこと、限界もあることもまた事実であります。これがある意味では非常に大事なところであります。","id":"exchange-175"},{"speaker":"塚本委員","kind":"質問・要望","question":"語っていただきたいところですけれども、現状のままでいいという、これでいっぱいやっているというのはおかしいので、上に権限を渡せということと同時に、目いっぱい品川方式で工夫をしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-176"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/623169?Template=document&Id=1222#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2003-01-01&TermEnd=2003-12-31"}],"sourceMeta":{"pages":0,"characters":118403,"voices":385}},{"id":"h15-20031020-4","meetingId":"h15-c-settlement","date":"2003年10月20日","dateIso":"2003-10-20","committee":"決算特別委員会","time":"午前１０時０６分～午後６時２１分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を136件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"田中委員","kind":"質問・要望","question":"これらは大変区民サービスの向上につながったものと思われておりますが、まずこれまでの評価としてどのように評価されているのかお伺いをいたします。これらの事業は移管がなされなければ行えなかった施策ではないかと考えていますが、そういった観点からのご見解をお聞かせほしいと求めました。","respondent":"松本環境清掃事業部長","answer":"平成１２年に清掃移管が実施されました。以上のことかから、清掃事業の移管につきましては、大変意義深いものであったというふうに考えてあります。","id":"exchange-001"},{"speaker":"田中委員","kind":"質問・要望","question":"それ以前と比較しますと達成されているのではないかと考えていますが、区民サービスとは別の観点のごみ減量という観点からの成果は、どのようにとらえているのかお聞かせほしいと求めました。","respondent":"松本環境清掃事業部長","answer":"これらの施策を区で一体的に行うことによって、区民のごみ減量に対する意識の向上と、具体的行動を引き出したものというふうに考えてあります。今後とも、ごみ減量に向けて、区民の身近なところから施策の展開に努めてまいりたいというふうに考えてあります。","id":"exchange-002"},{"speaker":"田中委員","kind":"質問・要望","question":"財調制度のもとで運営がなされていますので、ごみが減量されることが財調上、どういう影響を与えるのかということをお聞かせほしいと求めました。単純に考えるとそういうふうに思われてしまうんですが、その辺の仕組みもお聞かせほしいと求めました。","respondent":"市岡企画財政課長","answer":"ごみの減量の努力と財調の関係について、ご説明申し上げます。かえって財調上、例えばリサイクル事業等に新たな需要を折り込んでいくという改革を進めるべく、都区間で議論を交わしているという状況です。","id":"exchange-003"},{"speaker":"田中委員","kind":"質問・要望","question":"これまでの成果ということでお伺いをしてまいりましたが、今後の課題ということにつきましてお伺いしたいと思います。こんな中、先般区長会が行われたということを伺っておりますが、どういうふうに考えているのかお聞かせほしいと求めました。","respondent":"高橋区長","answer":"清掃工場の問題ですが、ずっと自区内処理か地域処理かという問題で２年間それぞれ区長会で検討してまいりましたが、結論が出ない状況でございました。同時並行的にこの問題についても区長会で検討をし、検討した結果を助役会におろして、このような段階に来ているものです。","id":"exchange-004"},{"speaker":"田中委員","kind":"質問・要望","question":"平成１７年度以降の対応ということで、地域処理の考え方のもとで月２回のペースで、役割ということでお聞かせをほしいと求めました。この問題に取り組んでいただきたいと思うんですが、品川区の立場も踏まえながら、今後の方向性についてお聞かせほしいと求めました。","respondent":"高橋区長","answer":"今、でき上がりますと最新の工場ができるわけでございまして、すべてあるからといって２３区の問題とかけ離れての考え方を持つわけではございません。","id":"exchange-005"},{"speaker":"田中委員","kind":"質問・要望","question":"持たざる区の配慮も含めながら、配慮しながら、先送りということのないようにリーダーシップを発揮していただきたいと考えています。今後の移管の改革に取り組む上で、どういった区民サービスの向上につながるのか、その辺のことをお聞かせほしいと求めました。","respondent":"高橋区長","answer":"増員をせずに、そういう方法ができることをこれからも検討をし、実施をしていく必要があるんじゃないだろうかと。いろいろその他方法はあると思いますが、全区に戸別収集が実施できれば、素晴らしいごみの収集事業が行えるだろうというふうに思っております。","id":"exchange-006"},{"speaker":"田中委員","kind":"意見","question":"残された事業の移管で、今現在収集・運搬までですが、処理・処分まで含めて、品川区が直接タッチすることによって、区民意識が高揚することで、今区長がおっしゃられたような各戸収集などがより進んで区民サービスの向上、ごみ減量につながればということを期待しておりますとの意見を述べました。","respondent":"高橋区長","answer":"そういうものもやはり２３区で十分検討する必要があるんじゃないだろうか、私はそのように思っています。清掃工場その他は各区が所有して、協議会に運営を委託するという方法が取れないだろうかという考えを持っております。","id":"exchange-007"},{"speaker":"田中委員","kind":"質問・要望","question":"引き続きまして、教育行政の移管に伴う成果なり今後の課題についてお聞かせほしいと求めました。どのような意識の変化があったのか、またそのことが教育上どのような変化、成果があったのかをお聞かせほしいと求めました。","respondent":"古川教育次長","answer":"これも人事権が、区へ移管されたことによる一つの効果ではないかというふうに考えてあります。今後とも各園は多様な幼児教育のあり方について、検討を続けていくものと考えています。","id":"exchange-008"},{"speaker":"田中委員","kind":"質問","question":"幼稚園の先生方の変化の中に、まさにそのことが保護者の方々の多様な保育ニーズにこたえていくメニューをつくり出す上でも必要な要素だと思うんです。昨年でしょうか、開園してほぼ１年の評価、また保護者の方々のニーズにこたえているという部分の印象等をお聞かせいただけたらと思います。","respondent":"古川教育次長","answer":"一体となって就学前の乳幼児の育成にあたることこそが、人事権の移管による大きな成果というふうに認識しています。子どもの心身の発達に合わせた一貫した乳幼児の育成方針に基づき、一つの施設で継続的に乳幼児の育成が行えることが二葉すこやか園の特徴です。","id":"exchange-009"},{"speaker":"田中委員","kind":"質問・要望","question":"就学前の教育という観点で言えば、幼稚園の役割がありますし、また保育に欠ける子どもの対応ということで保育園の役割があります。考え方、方向性というんでしょうか、その点についてお聞かせほしいと求めました。","respondent":"古川教育次長","answer":"小学校入学までの６年間、社会性ですとか創造性を高め、乳幼児のすこやかな成長を育むことが大変重要であるというふうに考えてあります。既存の幼稚園、保育園にこだわることなく、こういった視点で教育、保育が行われることが基本的には望ましいと、このように考えてあります。","id":"exchange-010"},{"speaker":"田中委員","kind":"質問・要望","question":"まさに今後の学校改革を実現していく上では、これまで品川区としては「教育改革プラン２１」で、さまざまな改革を実施されてきております。改革をするにあたっての影響というんでしょうか、その点についてどのようなものを認識されているのかお聞かせほしいと求めました。","respondent":"古川教育次長","answer":"中学校におきます教育活動の中で、そして小・中学校の教員のそれに対する対応によっては可能であろうと、このように考えてあります。","id":"exchange-011"},{"speaker":"田中委員","kind":"質問・要望","question":"今現在行われている「教育改革プラン２１」というものが、教育改革がこれだけ進むんだというものがもしありましたら、その辺をお聞かせほしいと求めました。","respondent":"古川教育次長","answer":"私もさまざま人事権について考えてまいりましたけれども、なかなかそこまで及んでいないという現実を自ら痛感しています。そして品川区の「教育改革プラン２１」が推進するような体制づくりを整えるということが、このように考えてあります。","id":"exchange-012"},{"speaker":"田中委員","kind":"質問・要望","question":"さらに教育の水準を高めていく上には人事権がなくてはならないんだという意識がないと、そういう意味の改革も進まないのではないかと思われますが、改めてその辺の意識の部分をお聞かせほしいと求めました。","respondent":"若月教育長","answer":"そういった意味で、プラン２１を進めていくというのは大変大きな力になろうかと思いますが、この件についても２３区の教育長会でも話題になります。","id":"exchange-013"},{"speaker":"田中委員","kind":"質問・要望","question":"先ほど清掃事業の中で２３区の中でリーダーシップをというお願いをさせていただきましたが、今後の活躍をお願いしたいと思います。今後の姿勢といいますか、対応といいますか、大都市事務の東京都と区の役割分担の考え方についてお聞かせほしいと求めました。","respondent":"市岡企画財政課長","answer":"しかし、私どもの基本的な認識は、これで都区間の分権改革が終わったものだというふうには考えてございません。この問題については積極的にこれからも取り組んでいきたいと、このように考えてあります。","id":"exchange-014"},{"speaker":"田中委員","kind":"質問・要望","question":"例えば建築確認もなぜ１万m2で切ってしまうのか、そういった分野の移管も、ぜひ財源とともに移管の改革の推進にご尽力をほしいと求めました。現在国が想定している三位一体の改革が仮になされたときの品川区の影響というのは、どのようなものがあるのかお聞かせほしいと求めました。","respondent":"市岡企画財政課長","answer":"政府のいわゆる骨太方針２００３を見ましても、むしろ国庫補助負担金の廃止・縮小だけが先行しているという懸念を払拭できないところです。引き続き税財源の移譲ということを軸に、さらにこの問題を注視してまいりたいと、こういうふうに考えてあります。","id":"exchange-015"},{"speaker":"田中委員","kind":"質問・要望","question":"国の動きの中で影響ということがありますが、また一方で品川区においては都区制度改革の中においての財政自主権の確立ということが、今後の引き続きの大きな課題だと考えていますが、そのことについての今後の見通し、またご決意などをお聞かせほしいと求めました。","respondent":"市岡企画財政課長","answer":"消防、どうしても東京都が一体としてやらなければいけない事務だけを東京都が行い、抜本的な改革の問題が横たわっているというふうに考えてあります。いろいろな議論のポイントだというふうに考えておりまして、区としての主張を尽くしてまいりたいと、このように考えてあります。","id":"exchange-016"},{"speaker":"田中委員","kind":"質問・要望","question":"それを実現する中で受け皿として、今の２３区の体制のままで果たしていいのかという問題も、今後大きな議論となってくると思います。今後は大きな問題になってこようかと思いますが、この点について、どのような認識をされているのかお聞かせほしいと求めました。","respondent":"中尾根企画部長","answer":"２３区の独自性を発揮しまして、ないしは政策の戸別の問題での連携について真剣に今後は考えていくということだと思います。特に、清掃問題そのものがきちんと一つのけりをつけた、その次に新しいステップがあるのではないかと、このように考えている次第です。","id":"exchange-017"},{"speaker":"田中委員","kind":"質問","question":"区民に一番身近な自治体が行政サービスを行うことが、区民サービス、住民サービスの向上につながるものだと確信しております。そういう中で、改めて都区制度改革に対する姿勢、ご決意を最後にお聞かせをいただいて、私の質問を終わります。","respondent":"高橋区長","answer":"それぞれの権威の先生方をお呼びし、今後の２３区の問題、特別区のあり方の問題等々についてご検討をお願いすることになっております。２３区の特別区という問題に対しましてどのように進めていくか、改めて検討し直そうじゃないだろうかという機運があることは事実です。","id":"exchange-018"},{"speaker":"原委員","kind":"質問","question":"そしてまた、同じ地区内における小・中一貫校と普通校とのバランスはどう考えているのかというような質問が出されておりました。その部分も踏まえ、意識を持っていらっしゃる方だけではなく、その部分につきまして確固たるご意見を伺いたいと思いますので。","respondent":"若月教育長","answer":"各地区に原則１校としまして、地域のバランス等々も考えながら計画的に実施をしていきたいと、現在そのように考えているところです。近々のうちには福祉事業部との合同の説明会等々を予定してございまして、こんなふうに考えているところです。","id":"exchange-019"},{"speaker":"原委員","kind":"質問・要望","question":"今、お話をいただきましたようなしっかりした考え方を、今後の教育現場の中で反映をされていくように要望をいたしておきます。あるいは教育委員会もこういった理想像を持って教師にあたってほしいということをどう考えているのかということについてお伺いします。","respondent":"若月教育長","answer":"大変、難しいご質問ですけれども、教師の理想像といいましょうか、教育委員会として、まず基本的に考えていることを大きく分けますと三つあります。こうしたものを常に働きかけ、研修に生かしながら教員の資質向上に努力をしています。","id":"exchange-020"},{"speaker":"原委員","kind":"意見","question":"今、果たしてそれが今の教育現場の中で、教育長の考え方がどこまで浸透しているかというのが一番大事なところではないかなというふうに思っています。例えばの話ですけれども、その辺のところも、質というのはどういうところなのかというお考えを示してほしいと求めました。","respondent":"若月教育長","answer":"若干、今度は中身に係わってくるわけでありますけれども、これは大きく分けまして三つ考えております。これは先ほど申し上げましたようなところで、いろいろな材料を使いながら研修に励んでいただいていると、こんな状況です。","id":"exchange-021"},{"speaker":"原委員","kind":"質問・要望","question":"今後の「教育改革プラン２１」の推進の中で、その辺のところの理想的な部分も含めて、生かしていただきたいというふうに思っております。特に、その場に校長先生が立ち会えるのかどうかということも含めて、その辺はどういうふうに考えていらっしゃるのかお聞かせほしいと求めました。","respondent":"若月教育長","answer":"単に教育者の延長線上に位置づく優れた教育実践者としてだけでは、もう十分その機能は果たせないというのが教育委員会の考えです。目標を常に意識する学校経営、そうした学校経営が必要なのであって、与えられたことをこなしていくという学校経営の考え方は既に持っておりません。","id":"exchange-022"},{"speaker":"原委員","kind":"意見","question":"裁量権の中で学校が特色を出すには、「教育改革プラン２１」の推進の中に９項目挙げられておりますけれども、だんだん特色が薄れてくるわけです。そうすると学校の管理職はどういう裁量権を持って、いかがでございましょうかとの意見を述べました。","respondent":"若月教育長","answer":"それを考えるときには、五つの窓口があるだろう。それぞれの中身での子どもの成長や工夫といったようなものは、かなりその学校ならではの特色が出てきていると、このように認識をしています。","id":"exchange-023"},{"speaker":"原委員","kind":"質問","question":"そうすると、なおさら特色を出すところをどこに持っていくか、結局そういった情報の中では同じような形のものが出てきているわけですから。そうすると、そこの考え方としてはどういうふうに持っていったらよろしいんか尋ねました。","respondent":"若月教育長","answer":"それを使って、何と小学校と中学校が連携をして、それぞれの小学校の教育課程の特色を出そう。ご指摘のそうした連携に基づく特色といったようなものを、これからも本区では大事に育てていきたいなと考えております。","id":"exchange-024"},{"speaker":"原委員","kind":"質問・要望","question":"特色という中で、その時点のところでは「教育改革プラン２１」をさらに推進をしていただきたいと思うんですが、今後の中で学校と塾との係わり合い。学力とかあるいはいろんな教育産業が学校経営の中に携わってきたときに、どういう対応をされるのかお聞かせほしいと求めました。","respondent":"若月教育長","answer":"まだ私たちが努力すべきことが残っていると考えているところです。そうした意味で、もう少し私たちの努力を続けさせていただきたいなと、かように思っております。","id":"exchange-025"},{"speaker":"原委員","kind":"意見","question":"したがいまして、教育改革プラン２１を進める中では、その中でお進めいただけるということがよろしいのではないかなというふうに思います。あるいは家庭とか地域とかいろいろあると思うんですが、特に学校で気をつけなければならない指導方法というのは考えられていらっしゃるかとの意見を述べました。","respondent":"若月教育長","answer":"少子化に伴いまして、子どもをめぐる人間関係の希薄化ということが当然問題になってまいります。そういうことをやっていかなきゃならないという現状にあるですので、今、そういう点に力を入れて学校には指導をお願いしています。","id":"exchange-026"},{"speaker":"原委員","kind":"質問","question":"もちろん家庭とか地域の係わり合いが強くなってくるとは思うんですけれども、その辺のところの要するに学校での役割というのは、どういうふうに考えていらっしゃるのか尋ねました。","respondent":"若月教育長","answer":"私は割と単純な考え方を持っているんですが、社会のルール、そうしたようなものをきちんと繰り返し子どもたちに伝えていく。これがやはり一番大事な基本的な姿勢ではないだろうか、こんなふうに思っております。","id":"exchange-027"},{"speaker":"原委員","kind":"質問・要望","question":"今までの教育の中で、やっぱりその部分が欠けてきているのが現状だったのではないだろうかと思うんです。やはりより以上に学校のところでしっかりそれを教えていくことが、これからの日本をつくると言っていいんですか、いかがでございましょうか。","respondent":"若月教育長","answer":"今回小・中一貫校で新たな取り組みとして考えられる教科の一つに、この二つのいいところを融合した市民科という新しい分野を研究しています。委員が期待されているような、子どもたちにいい影響を与えられるような内容にするよう、これからは頑張ってまいりたいと考えております。","id":"exchange-028"},{"speaker":"原委員","kind":"意見","question":"これは平成１７年から１０年間かけて次世代育成をやっていくということなので、１０年間のプランニングを考えていかれるんじゃないかなと思うんです。学校教育の中で就学前から、あるいは勉学について、その辺のプランを何かお考えがあるようでしたら説明を求めました。","respondent":"若月教育長","answer":"この教育改革プラン２１をさらに充実、学校教育の立場からは非常に大事なことであると、こんな認識を持っております。したがいまして、義務教育を超える部分につきましては、全庁的な観点から行動計画等々を策定していく必要があろうかと、こう考えているところです。","id":"exchange-029"},{"speaker":"原委員","kind":"意見","question":"この次世代のところは、教育委員会だけではないですよね。教育委員会だけではなく、その辺についてお考えがあるようでございましたら説明を求めました。","respondent":"中尾根企画部長","answer":"従来は働く母親をいかに支援していこうかというようなことで、全体的には保育行政の支援が非常に強い考え方で取り組まれてまいりました。全庁的な視点の中から国のモデルプラン等も参考にしながら再検討をして、よりよい施策づくりのために努力していきたいと考えています。","id":"exchange-030"},{"speaker":"原委員","kind":"質問・要望","question":"今のお考えですと、各部署の調整役あるいは調整委員会のような形のものをつくり上げて、その中で子育てについての全体的な考え方については考えていこうというふうに思われているのでしょうか、その辺のところのプランがあるようでしたら教えてほしいと求めました。","respondent":"中尾根企画部長","answer":"これからの取り組みのプロセスで、今のところ考えておりますのは、整合性を持たせた一つの素案みたいなものをつくっていきたい。大まかに言えば、このようなスケジュールで考えてあります。","id":"exchange-031"},{"speaker":"原委員","kind":"質問・要望","question":"そういう成果をどういう形で表に出していこうとされているのか、一般の方々からは「これはどうなっているんだ」と聞かれる部分があります。そういうところも含めて、出てきた成果についての報告あるいは考え方について教えてほしいと求めました。","respondent":"若月教育長","answer":"それについて、まずは来年１月２８日に、教育改革プラン２１の検証のフォーラムをきゅりあんでやることになっております。したがいまして、学校独自の新しい方策といったようなものを開発していく必要があるということは、痛切に感じているところです。","id":"exchange-032"},{"speaker":"原委員","kind":"意見","question":"それをできるだけ報告をしなければならないという部分も含めて、教育改革プラン２１というのは既に４年経っている、あるいは４年しか経っていない。","respondent":"若月教育長","answer":"教育改革プラン２１で進めてきた部分でのハードの部分というのは、そして区長部局の理解をいただいて、かなり順調に進んできてあります。当然一つの方針は出しますが、なるべく後ろに下がりたい、これは現在私が考えていることです。","id":"exchange-033"},{"speaker":"原委員","kind":"質問・要望","question":"先ほどお話を伺おうかなと思っていたんですが、これからはもっと加速しますから、お答えがあればありがたいなというふうに思います。地域にどのぐらい密着したものを建て替えの中に取り入れていこうとしていらっしゃるのか、その部分についてお伺いさせてほしいと求めました。","respondent":"若月教育長","answer":"そういう制度でこういう方針でやってくださいと言われて、制度上、形の上は似ていても実質的にはかなりその内容に差が出てくるだろうと考えています。","id":"exchange-034"},{"speaker":"原委員","kind":"質問・要望","question":"今までいろいろ教育の部分についてお伺いをさせていただきました。その辺が欠ける点はないんだろうかというところで、お考えのあるところで結構ですから、お聞かせいただけれはありがたいと思います。","respondent":"若月教育長","answer":"ご家庭の要求といったようなものに、今の選択制が十分に対応しこたえていると、かように認識をしております。やはり、その研修の場も基本的にはこれから少しずつ学校のほうに戻し、学校がその力を持つ、そういう方向性に持っていきたいと考えております。","id":"exchange-035"},{"speaker":"原委員","kind":"質問・要望","question":"そういう意味から、いろんなお話を聞かせていただきましたけれども、教育改革プラン２１をしっかり進めていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"堺委員","kind":"質問・要望","question":"併せて、関係者への説明会の開催と関係者の皆さんからどのような要望が出ているのか。１７年にかけて工事を行い、平成１８年４月に開校する予定になっておりますけれども、それぞれお聞かせほしいと求めました。","respondent":"若月教育長、古川教育次長","answer":"こうしたことを踏まえまして、小・中学校の垣根を取り払って、９年間という長いスパンの中で子どもたちの個性、能力を十分に発揮する。そうした柔軟なカリキュラムというものをつくっていって… １０月末に仮設校舎の工事に着手するという予定でございまして、１２月の冬休み期間を利用して引っ越しをするという考え方です。","id":"exchange-037"},{"speaker":"堺委員","kind":"質問・要望","question":"１０月１日に伊藤中学校と原小学校、その際に出された保護者の方からの意見について、改めてこの席を借りて確認をしておきたいと考えています。業者のほうからのプランが提示されるのが１１月頃になると、学校選択が１０月末ですから、この辺についてもお聞かせほしいと求めました。","respondent":"古川教育次長","answer":"１点目ですが、１０月１日にそれぞれ伊藤中学校をエリアとします三つの小学校の保護者の方にお集まりいただきまして説明会を行いました。今回のケースにつきましても、個別に相談をお受けするなど柔軟に対応してまいりたいと考えております。","id":"exchange-038"},{"speaker":"堺委員","kind":"質問・要望","question":"日野中学校や区立総合体育館および原小学校など、区有財産の有効活用についてお伺いしておきたいと思います。それから、区立総合体育館について、その辺の事実関係も教えておいていただきましょうか。","respondent":"中尾根企画部長","answer":"今現在６ｍを１６ｍに広げる予定ですが、体育館の反対側が１０ｍ広がるということで、体育館そのものについてはセットバックは要らない。区の施策に対する方針のみならず、今後どのように使っていくのかという検討をすべきところですので、よろしくお願いいたします。","id":"exchange-039"},{"speaker":"堺委員","kind":"質問・要望","question":"次に、品川区庁舎内に品川区公有財産管理運用委員会というのがあるやに聞いておりますが、この委員会の設置目的、所管事項および構成メンバーについてお知らせほしいと求めました。","respondent":"本間総務部長","answer":"これは区内部の検討組織でございまして、設置目的は区有財産の効率的な活用方法などを調査・検討するために設けた組織です。所管事項といたしましては、区が所有いたします行政財産、普通財産で未活用なものを検討し、活用のための案をつくることです。","id":"exchange-040"},{"speaker":"堺委員","kind":"質問・要望","question":"地元関係者の意見も聞いて有効活用をぜひ図っていただきたいと、この件についてお尋ねしておきたいと思うんです。そういう面で、今申し上げた件についてのご見解をお尋ねしておきたいと思います。","respondent":"本間総務部長","answer":"公有財産管理運用委員会といたしましては、関係部署と十分調整を図った上で原案を作成して、事業部経営会議に付議したいと考えているところです。","id":"exchange-041"},{"speaker":"堺委員","kind":"質問","question":"次に、区有財産の有効活用についての２点目の質問ですが、密集住宅市街地整備促進事業用地についてお伺いしておきたいと思います。最初に、密集住宅市街地整備促進事業の内容と実績について、簡単にご説明ほしいと求めました。","respondent":"中谷まちづくり事業部長","answer":"国の制度あるいは東京都の制度を活用しながら効率的に事業運営を行い、安全で快適なまちづくりをつくるということに努めているところです。","id":"exchange-042"},{"speaker":"堺委員","kind":"意見","question":"具体的にお尋ねしておきたいんですが、平成１２年３月に約６６４m2の土地を購入したわけです。購入してからはや３年経過して、このままでいいのかどうかということでございまして、この辺についてのご見解を説明を求めました。","respondent":"中谷まちづくり事業部長","answer":"ご指摘の用地につきましては、平成１２年にまちづくり用地として購入し、目的としては広場用地として購入してございました。ご案内のとおり３年が経過しているということで、区といたしましてはなるべく早期に広場として整備できる方向で、現在調整を進めているところです。","id":"exchange-043"},{"speaker":"堺委員","kind":"確認","question":"この十勝沖地震の震源は、約１０年前に相次いだ二つの大地震と同じ海域だった。去る１０月１３日、浸水の原因等を含めまして、改めて確認をしておきたいと思います。","respondent":"中谷まちづくり事業部長","answer":"浸水被害の状況ですが、床上・床下を合わせまして３２件です。それが時間換算で１００mmを超すですので、下水道施設に収容しきれずに、浸水によるご迷惑をかけたことが原因というふうに考えております。","id":"exchange-044"},{"speaker":"堺委員","kind":"質問・要望","question":"園庭の砂がどうしても道路上に出てきてしまって、それが浸水の要因になるといけませんので、園庭のどろについてもぜひ対策を講じていただきたい。ご見解をお伺いします。","respondent":"中谷まちづくり事業部長","answer":"区といたしましては、下水道局とも協力しながら浸水対策、今後の対応策について早急な検討を行っていきたいと、かように考えているところです。","id":"exchange-045"},{"speaker":"堺委員","kind":"意見","question":"次に、地区総合防災訓練に関連をして、お尋ねをしておきたいと思います。７月２６日に板橋区で行われました密集市街地における避難訓練について、改めてこの場で情報を提供ほしいと求めました。","respondent":"太川区民生活事業部長","answer":"町会、そのデータをもとに住民の避難行動や避難時間等を科学的に分析して、密集市街地における防災計画に反映させるというものです。倒壊家屋を想定した通行止めを設置いたしまして、その場で安全な道を探していくという実践的な訓練をしたです。","id":"exchange-046"},{"speaker":"堺委員","kind":"質問・要望","question":"住民には事前に知らせないで行ったという、まさに実践に則した訓練という、ぜひこういう訓練も実施していただきたいと思っているわけです。区としても対策を講ずるようにお願いをしたいと思っているわけですが、ご見解をそれぞれ説明を求めました。","respondent":"太川区民生活事業部長","answer":"本区の地区防災訓練につきましては発災型対応で訓練会場に行くという、その間に経路を点検して初期消火とか安全を確認する訓練を取り入れてあります。","id":"exchange-047"},{"speaker":"堺委員","kind":"質問・要望","question":"部長の答弁の中で、災害要援護者の避難誘導ワークショップに基づいて、訓練の拡大という視点からお尋ねをしておきたいと思います。大井第三地区、荏原第四地区に参加された方々、実際に携わった方の感想等があればお知らせほしいと求めました。","respondent":"太川区民生活事業部長","answer":"昨年、小山二丁目で第１回目避難誘導のワークショップを行いまして、今年は４カ所で既に実施しています。今後も引き続きまして意向調査等を行いまして、万全を期してまいりたいと考えています。","id":"exchange-048"},{"speaker":"堺委員","kind":"質問・要望","question":"こんなに役に立つものか」という感想も寄せられているですから、町会や自治会が中心になって備えをしておく必要があると思うわけであります。ぜひ各地域におきましても、こういう取り組みを全区的に推進していっていただければと考えていますが、この辺についてのご見解を説明を求めました。","respondent":"太川区民生活事業部長","answer":"先ほどお答えいたしましたように、既に合計で５地区でワークショップを行ってありますので、基本的な誘導のマニュアルはほぼでき上がってあります。","id":"exchange-049"},{"speaker":"堺委員","kind":"質問・要望","question":"それから、地区総合防災訓練と学校関係者の参加状況についてお尋ねをしておきたいと思います。そのときの学校関係者の参加状況等について把握しておられればお知らせほしいと求めました。","respondent":"太川区民生活事業部長","answer":"当日、荏原第四中学校の校長、教頭先生をはじめといたしまして、２２名の教員と７８名の生徒の参加がございました。この様子を見ておりました地域の方々からは、非常に若い力に対する頼もしさということで、大きな拍手がわいたという報告を受けてあります。","id":"exchange-050"},{"speaker":"堺委員","kind":"提案","question":"区議会公明党としても予算要望や、機会あるごとに夜間の防災訓練の必要性について提案してまいりました。荏原第三中学校で実施されたと伺っておりますけれども、今後どのように取り組まれようとしているのか、ご見解を説明を求めました。","respondent":"太川区民生活事業部長","answer":"夜間の防災訓練ですけれども、今ご指摘のとおりかつて十数年前に荏原第三中学校で初めて実施した経験があります。そういうことで、現在のところは昼間の避難訓練を中心に取り組んでまいりたいと思ってありますので、ご理解のほどをよろしくお願いいたします。","id":"exchange-051"},{"speaker":"堺委員","kind":"質問","question":"昨日は、八潮地区で総合防災訓練が地区内の五つの小・中学校で実施されたと伺っております。その辺の訓練状況等を把握されておられましたら、教えてほしいと求めました。","respondent":"太川区民生活事業部長","answer":"それから、９月２８日に宮前小学校で行われました避難所訓練ですが、ここにつきましては今年度初めて合同防災訓練を実施したです。焚き出し、応急救護等、内容も豊富に充実したものが実施されたと考えています。","id":"exchange-052"},{"speaker":"堺委員","kind":"確認","question":"誘導班というのでしょうか、あるいはトイレの当番体制とか、そういう役割分担も決めておく必要性もあるかなと思っているわけです。この辺について、強化ガラスに改修されているのかどうか、その辺を確認しておきたいと思います。","respondent":"太川区民生活事業部長","answer":"学校が避難所として指定されましたのは平成９年ですが、年に最低１回は実施して、今後の避難所のあり方を確立しようということで進めてまいりました。","id":"exchange-053"},{"speaker":"堺委員","kind":"質問","question":"学校の窓ガラスですが、校庭側については改修されているように聞こえたんですが、教室の中、廊下側というんですか、そちらはどうなっているんか尋ねました。","respondent":"古川教育次長","answer":"主として球技等の対策ということで、外に対してはかなり実施していますけれども、内部の廊下側につきましてはまだ未整備な部分があります。こういった部分につきましても、計画的な整備につきましては内部の改修の時期等に合わせながら、検討してまいりたいと考えています。","id":"exchange-054"},{"speaker":"堺委員","kind":"質問・要望","question":"それから、防災に関しての子どもボランティア育成の件についてお尋ねをしておきたいと思います。静岡県の教育委員会で取り組みが始まったようですが、子ども防災ボランティア育成事業について、情報を得ていればお知らせほしいと求めました。","respondent":"太川区民生活事業部長","answer":"静岡県の教育委員会では、昨年２月に小・中学生に地域の防災活動に貢献してもらうための防災教育の基本方針を策定したそうです。報道によりますと、和歌山県の教育委員会、高知県の教育委員会等でも同様な取り組みをしたそうです。","id":"exchange-055"},{"speaker":"堺委員","kind":"質問","question":"子どもでも救護や物資の搬送、そういう軽い作業といいましょうか、そういうことについてはお手伝いができるのではないかと思っているわけです。ぜひ品川区におきましても、その上で余力があれば子どもにもそういうボランティア精神というのでしょうか、ご見解を説明を求めました。","respondent":"太川区民生活事業部長","answer":"防災ボランティアの知識とか技能を育てるための活動はまだ実施しておりませんけれども、また協力するように呼びかけているところです。自ら進んで地域に係わることのできる児童・生徒の育成を目指しまして、ボランティアの活動等に参加していただきたいと思ってあります。","id":"exchange-056"},{"speaker":"堺委員","kind":"質問・要望","question":"最後に、児童や青少年の健全育成事業等の拡充についてお伺いをしておきます。最初に、学童保育クラブの事業目的と、ここ３年ぐらいの入会理由別の状況および今後の方向性についてお聞かせほしいと求めました。","respondent":"小沼福祉事業部長","answer":"この間学校の週５日制、あるいは本格実施あるいはすまいるスクールの開始ということで、児童の育成環境が相当変わってきてあります。ただ、そういう中においても次世代育成支援に代表されますように、健全育成ということを目指して進めていきたいと考えています。","id":"exchange-057"},{"speaker":"堺委員","kind":"意見","question":"次に、厚生委員会でも話があったかと思うんですが、平成１５年度末をもちまして、学童保育クラブが９館閉館されるわけです。そこの職員等の処遇について、お知らせほしいと求めました。","respondent":"小沼福祉事業部長","answer":"平成１５年度末で閉鎖を予定されている学童保育クラブに勤務している職員の処遇の問題ですが、そういうものに従いまして。区の非常勤職員の要綱というのがありますので、そちらに定めた手続なり基準に従いまして、任用等で対応してまいりたいと考えています。","id":"exchange-058"},{"speaker":"堺委員","kind":"質問・要望","question":"今の職員の件でお尋ねをしたとき、すまいるスクールというお話が出ておりましたが、改めてすまいるスクールの事業目的と今後の方向性についても、併せてお聞かせほしいと求めました。","respondent":"古川教育次長","answer":"本年９月に１５校を開設いたしまして、現在１９校で実施しています。全校実施に向けながら、なお未設置校の開設につきましても、今後計画的に進めていきたいと考えています。","id":"exchange-059"},{"speaker":"堺委員","kind":"意見","question":"これはぜひお願いをしたいという意味でお尋ねをしておきたいと思います。学童保育クラブのよさを継承しつつ、細心の心配りを重ねてお願いをしておきたいと思っているわけですが、ご見解を説明を求めました。","respondent":"古川教育次長","answer":"すまいるスクールを安心してご利用していただけるような移行につきまして、これまで以上にさまざま配慮してまいりたいと考えています。私ども、少なくとも学童保育クラブで実施している内容につきましては、必要なものにつきましては継承していきたいと考えています。","id":"exchange-060"},{"speaker":"堺委員","kind":"質問・要望","question":"保護者を対象にしたすまいるスクールの体験学習を開催することについてということで、お尋ねしておきたいと考えています。その際に、ある面では必要ではないかと思いますが、その辺についてのご見解をお聞かせほしいと求めました。","respondent":"古川教育次長","answer":"百聞は一見にしかずですので、ぜひ実際にすまいるスクールを見学し、そして体験をしていただきたい。には、個人単位でも結構ですが、すまいるスクールを訪れあるいは体験するような機会をこれからもつくってまいりたいと考えています。","id":"exchange-061"},{"speaker":"堺委員","kind":"提案","question":"今後閉鎖される予定の学童保育クラブの跡地利用については、児童センターの重点事業に対応した機能拡充に向けて活用されるよう提案するわけです。併せまして、西中延児童センターは３階と４階のトイレが男女一緒で使いにくいという声がありますので、ご見解を説明を求めました。","respondent":"小沼福祉事業部長","answer":"これにつきましても今後地域での状況等において、よりふさわしいものを検討していきたいというふうに、現在作業に着手している段階です。なお、西中延児童センターですが、これにつきましては今後育成室等の転用計画に合わせまして、適宜検討を進めてまいりたいと考えています。","id":"exchange-062"},{"speaker":"堺委員","kind":"質問","question":"明確に来年の３月をもって、４月以降閉鎖されるわけですから、九つ空くということが明確になっているわけですから。その辺についてのお考えは、どうか尋ねました。","respondent":"小沼福祉事業部長","answer":"当然ですが、それはそれなりに来年度に間に合うような形で使っていくという基本的な考え方はあります。ただ、今この場で即４月云々ということはちょっと言えないという状況ですが、鋭意検討を進めているというふうにご理解をいただければと思います。","id":"exchange-063"},{"speaker":"堺委員","kind":"質問・要望","question":"やっぱり改修したりいろいろその期間かかるわけですから、さっき申し上げましたように、ぜひひとつ前向きに取り組んでほしいと求めました。次に、児童センターの役割と機能について、まず児童センターの事業内容について確認をしておきたいと思います。","respondent":"小沼福祉事業部長","answer":"一般的には児童の健全育成ということに努めまして、それに向けてのさまざまな事業展開をするということになってあります。青少年の居場所の問題であるとか、あるいは広く悩みの問題への対応であるとか、こういうようなことが主な活動内容になってあります。","id":"exchange-064"},{"speaker":"堺委員","kind":"意見","question":"併せまして、ティーンズプラザが今年の４月からスタートしまして、その中でビデオカメラを放送局用に２台購入しました。私も見てまいりましたけれども、大規模改修してつくった放送室が有効に活用できればと思っているんですが、その辺のご見解を説明を求めました。","respondent":"小沼福祉事業部長","answer":"充実であるとか、地域との連携であるとか、中高生の支援といった点に今後私どものほうでシフトしていくというようなことが１点あります。それから、ボランティアの方々の連携なり活用なりを図って進めてまいりたいと、こんなようなことを考えてあります。","id":"exchange-065"},{"speaker":"堺委員","kind":"意見","question":"あるいは８月には卓球台を新しく購入して、トワイライト卓球大会で６０名、大勢の方々がこの児童センターに来るようになった。物理的に来館可能な日曜日の開館、あるいは開館時間の延長も必要と思いますが、検討状況についてお考えを説明を求めました。","respondent":"小沼福祉事業部長","answer":"先ほど申し上げましたけれども、児童センターのあり方検討委員会の中でも、その点については触れてあります。一つの提言を出したものですので、開館時間の延長あるいは日曜開館というようなことも、可能な限りは臨んでいきたいというふうに考えてあります。","id":"exchange-066"},{"speaker":"堺委員","kind":"質問","question":"可能な限り前向きにですので、ぜひこれも児童センターの機能アップに向けて、努力をお願いしたいと思います。以上で、私の総括質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-067"},{"speaker":"菊地委員","kind":"質問・要望","question":"決算委員会の最中に震度３から４の地震がありまして、これが震度５、６という地震だったらどうなるのかという不安を皆さん抱いたことと思います。そこでお伺いしたいんですが、東京２３区全体で耐震診断に助成をしている区がどの程度あるのかお知らせ願いたいと思います。","respondent":"中谷まちづくり事業部長","answer":"最初に、耐震診断の助成を２３区で実施している区の状況ですが、私どもが調べたところでは１５区というふうに認識しております。区営住宅では平成１３年度が６１.３倍、平成１４年度が３４.１倍、大体そういう状況です。","id":"exchange-068"},{"speaker":"菊地委員","kind":"質問","question":"戸建てのものというよりＲＣ、区でこれからこういうものを持っていくつもりなのかどうか、この辺の考え方についてお聞かせ願いたいと思います。何度応募しても入ることができないわけですから、こうした方はどうしていけばいいのか、この点についても考えをお聞かせ願いたいと思います。","respondent":"中谷まちづくり事業部長","answer":"慎重に検討してきたところですが、そういう意味で品川区で耐震診断を考えておりますのは、効果的な対策をやっていかなけばいけないです。やはり老朽の木造建築物ですから、効果・効率的な事業展開になるだろうということで、それについての助成を検討しているです。","id":"exchange-069"},{"speaker":"菊地委員","kind":"質問・要望","question":"実際に住宅に困窮している区民の皆さんですとか、不況の時代ですから、自治体の果たす役割の最も重要な部分ではないかというふうに思います。１０２億円の補助金が投入されるということですけれども、改めてここでの計画概要についてお知らせを願いたいと思います。","respondent":"中谷まちづくり事業部長、岩野まちづくり事業部次長","answer":"先ほども申し上げましたとおり、区としては優先して取り組むべきというふうに考えておりますので、よろしくお願いしたいと思います。特定行政庁による勧告が必要だとか、いろいろ特定の制限がございまして… その際に、本年６月段階で準備組合が事業協力ではなくて、参加組合員を直接探すといった形で現在に至っているという状況です。約２５０戸、賃貸棟が２８階建てで３万２,６００m2、約３３０戸です。","id":"exchange-070"},{"speaker":"菊地委員","kind":"質問","question":"この考え方というのは、実際に特色がどうとかという問題ではないような気がしますけれども、この点についてお聞かせ願いたいと思います。品川区はこのことについて、開発道路の指導を行っているということですけれども、この辺の子細についてお知らせ願えればと思います。","respondent":"岩野まちづくり事業部次長、中谷まちづくり事業部長","answer":"全体の計画についてですが、款別審査のときにお答えいたしましたように、主に住宅をメインにした計画を地元と話をしています。やはり６０ha全体の中で西地区がどういう役割を占めるかというようなことの検討と… 私のほうからは北品川のミャンマー大使館脇の開発問題の道路の関係につきまして、ご説明申し上げます。事業主に対しましても各建築基準法、都市計画法等の諸法に基づきまして、手続をきちんとしていただくように現在指導しています。","id":"exchange-071"},{"speaker":"菊地委員","kind":"質問","question":"ですから、先ほどお聞きした区営住宅の建設をしていくということが重要ではないかというふうに思います。時間がありませんので、それから旗の台の一部でしょうか、わずかに残った第１種住居専用地域を守っていくべきだというふうに思います。","respondent":"中谷まちづくり事業部長","answer":"第１種住居専用地域の変更についてのお尋ねですが、区ではこれまで御殿山地域を第１種住居専用地域ということで行ってまいりました。事業者が予定おりますのは、これは東京都の制度に基づくものでございまして、適法のものであるというふうに認識しております。","id":"exchange-072"},{"speaker":"菊地委員","kind":"質問・要望","question":"先の第１種住居専用地域を守っていくという立場を、ぜひ貫いてほしいと求めました。以上で、質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-073"},{"speaker":"沢田委員","kind":"質問","question":"私は学童保育クラブのすまいるスクールへの移行、廃止問題について質問をします。関係者から出されている不安や疑問の内容はどんなものなのか、以上３点について説明をしてほしいと求めました。","respondent":"小沼福祉事業部長","answer":"これについては２年前に開始した時点ですと、今日行われている状況の中では、特に私どもとしますと大きな違いはないというふうに考えてあります。ただ、この関係ですが、それは今まででございまして、請願の結果が出ましてからは、今日私どものところには一切来てございません。","id":"exchange-074"},{"speaker":"沢田委員","kind":"質問","question":"メールが大分寄せられたと、今はなくなったということなんですが、賛成と反対はどんな割合ですか、それをお聞かせ願いたいと思います。児童福祉法で放課後児童健全育成事業の中で、ここで「生活の場の提供」というのは、部長はどうお考えか尋ねました。","respondent":"小沼福祉事業部長","answer":"最近では、ほぼヒフティヒフティから逆になって、すまいるスクールをもっと積極的な形での活用を考えたらいいというふうになってきてあります。遊びを通しての生活の場、あるいは生活についてのルールなり指導を築いていくんだとのが、今日定説になってあります。","id":"exchange-075"},{"speaker":"沢田委員","kind":"意見","question":"だから、遊びの場の提供に加えて、生活の場というのは親がいない間、家庭にかわる施設、役割を学童保育クラブが担ってきたんだと思います。部長は全く大きな違いはないと言いますけれども、学童保育クラブにあってすまいるスクールにないサービス内容はどんなものがありますかとの意見を述べました。","respondent":"小沼福祉事業部長","answer":"それから、１年生から３年生まですべて連絡帳云々というのは、既存の学童保育クラブの中でも提供しているものではございません。それから、すまいるスクールではそれと違いますけれども似たような形のものをしていますので、ほとんど違いはないというふうに申し上げたわけです。","id":"exchange-076"},{"speaker":"沢田委員","kind":"意見","question":"子どもを育てる中で、子どもが落ち込んだときにどう対応するかというところで、みんな悩むんです。このような場合にどういう対応が保証されるか，すまいるスクールだったらどうなったのかと聞いているので答えてくださいとの意見を述べました。","respondent":"小沼福祉事業部長","answer":"今までやっている学童保育クラブ事業の対応の仕方と。利用状況も違いますので、そういう個々具体的な問題につきましては、各すまいるスクールのほうできめ細かな対応を取り組めばよろしいわけです。","id":"exchange-077"},{"speaker":"沢田委員","kind":"質問","question":"どうしたらいいでしょうか」と書いて、先生はそれに返してくれる。ですから、専任の指導員が２人いるということは、子どもを激励し自発的に自立できるように支援していく。","respondent":"古川教育次長、小沼福祉事業部長","answer":"私のほうからすまいるスクールの状況について、先にお答えしたいと思います。常勤の専任指導員１名、非常勤が８名、合わせて９名体制です。 西品川ですが、６８名です。〔「職員体制」と呼ぶ者あり〕 確か３名だったと思いますが、非常勤は１名です。","id":"exchange-078"},{"speaker":"沢田委員","kind":"質問","question":"１０２名にものぼる子どもを１名の専任職員と４名の非常勤職員でどう見るんでしょうか。改めて、こんなに１０２名、２.５倍も増えながら職員は圧倒的に少なくなるということで、サービス向上と言えるでしょうか、いかがか尋ねました。","respondent":"古川教育次長","answer":"それまでに当然解決していきたいと、このように思ってありますし、加えて専任指導員１人と非常勤職員４人です。そしてバックアップする４名、全体で９名おりますので、このように考えてあります。","id":"exchange-079"},{"speaker":"沢田委員","kind":"意見","question":"今の学童保育クラブと歴然と内容が違うと思います。その中に学童保育クラブを取り込むときに、国は補助金を出すのに一定の条件を課していますけれども、説明願いたいと思いますとの意見を述べました。","respondent":"小沼福祉事業部長","answer":"国の補助金と言いますけれども、私どもは国の補助金は受けてございません。","id":"exchange-080"},{"speaker":"沢田委員","kind":"意見","question":"学童保育クラブとすまいるスクールの全児童対策の問題で、これは一つの大事な指針となるから聞いているんです。もう一度、お答えくださいとの意見を述べました。","respondent":"小沼福祉事業部長","answer":"何度も申し上げますけれども、私どもは国庫補助事業として、それを受けて事業展開をしているわけではございませんので、それについて説明しろと言われても、この場では説明のしようがございません。","id":"exchange-081"},{"speaker":"沢田委員","kind":"確認","question":"そのほか、子どもの所在確認ができる体制を取りなさいという、８項目クリアしなければ国庫補助を出さない。このうちどれだけクリアしていますか。","respondent":"小沼福祉事業部長","answer":"冒頭からお話申し上げていますように、国基準の適用を受けるあるいは国の補助をもらっての事業展開ではございません。平成１５年４月１日になりまして、私どもは今は学童保育クラブにつきましては、直営で実施しているということも付言はします。","id":"exchange-082"},{"speaker":"沢田委員","kind":"意見","question":"次に、私はこれまで保護者に対してどのような説明会がされてきたのか、それから立案から決定に至るまで、どういう手順を踏んで行われてきたのかお尋ねしたいと思いますとの意見を述べました。","respondent":"古川教育次長","answer":"すまいるスクールについての説明会ですけれども、本年度実施いたしましたのは９月に１５校開設を前提にした説明会だけを今現在やってあります。今後来年４月に向けまして、福祉事業部と連携しながら合同説明会を今後やっていきたいと、このように考えてあります。","id":"exchange-083"},{"speaker":"沢田委員","kind":"意見","question":"合同説明会を急いでやってほしいと思うんです。１１月４日から学童保育クラブの募集停止がされ、直近でいつぐらいにできるのかお答え願いたいと思いますとの意見を述べました。","respondent":"古川教育次長","answer":"私どものほうでは福祉事業部と調整した上で実施していきたいと思ってありますが、近々のうちにやっていきたいと考えています。","id":"exchange-084"},{"speaker":"沢田委員","kind":"質問","question":"ということは、１１月中には可能だということか尋ねました。","respondent":"古川教育次長","answer":"できれば、１１月には説明会をスタートさせたいと、このように考えてあります。","id":"exchange-085"},{"speaker":"沢田委員","kind":"提案","question":"私は、今回の提案は子どもがなおざりになっていると思います。私はこのことを厳しく求めたいと思いますし、この支援法あるいは基本法では言っておりますけれども、その充実を求めて終わりたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-086"},{"speaker":"高星委員","kind":"質問・要望","question":"私は大きく５点、１点目には、高橋区長の今後の課題ということでお考えをお聞きしたい。２０年、５期目という節目で考えたときに、そういったところでの考え方をちょっとお聞かせほしいと求めました。","respondent":"高橋区長","answer":"品川区は昭和５８年から行政改革を実施してきております。これからも、終りのない品川区の発展のために努力してまいります。","id":"exchange-087"},{"speaker":"高星委員","kind":"質問・要望","question":"その辺のところ、これからこれだけはやり遂げたい、これだけはやってみたいというふうに思っているものがありましたら聞かせていただきたいなと。これがまだまだそのままになってしまっていることも含めて、その辺の考えがありましたらお聞かせほしいと求めました。","respondent":"高橋区長","answer":"結果が高橋区政につながったんだというふうに、私は思っております。これが高橋区政の目玉だったのかなというふうに、過去に振り返ってみて、そういう印象を持っていただければ幸いだと思っています。","id":"exchange-088"},{"speaker":"高星委員","kind":"質問・要望","question":"始めにお聞きしたいんですけれども、これはどういうことなのか把握していらっしゃるかどうか。総括というにはちょっと細かいかもわかりませんけれども、とても大事なところがありますので、ひとつよろしくお願いしたいと思います。","respondent":"太川区民生活事業部長","answer":"当面、これから５年間を目途にいたしまして、交通渋滞解消のための違法駐車対策をさらに拡大して進めるというものです。意義づけ等につきまして十分私どものほうで調査いたしまして、計画上に載せるかどうかにつきまして、十分検討してまいりたいと考えております。","id":"exchange-089"},{"speaker":"高星委員","kind":"質問・要望","question":"当然学校の担任あるいは専門教員に対して厳しく対応が求められてくるんだろうというふうに思うんです。平塚中学校の問題でありますけれども、１学年の生徒数が２０人前後ということで、その辺のところを具体的にお聞きいたしたいというふうに思います。","respondent":"若月教育長","answer":"そう考えると、教員や一般の教員もこの問題に対する認識というものをかなり深めなければなりません。どういう手順でどんな検討委員会をつくるかということは、専門家をメンバーとしまして、その検討委員会をつくっていかなければならないだろうと。","id":"exchange-090"},{"speaker":"高星委員","kind":"質問・要望","question":"さらにはしかるべきところで明らかにしてもらって、安全に確実に確かなものにしていただきたいというふうに、これは要望したい。２７学級、２８学級というふうに、この先どうするんか尋ねました。","respondent":"若月教育長","answer":"そうした入学者数の予測は、データとして持ってあります。仮に学級が増えるような場合には、抽選といったような方法で子どもたちに入学していただく、そんな方法をどうしても考えざるを得ないです。","id":"exchange-091"},{"speaker":"高星委員","kind":"質問・要望","question":"現場の要求にはああだこうだ言わないで、やっぱり十分に保証してあげて、結果どうであったかというところで判断すべきだというふうに思います。その辺の考え方を、先ほどの分析と含めて、２点を説明を求めました。","respondent":"若月教育長","answer":"区長部局、大変なご理解をいただきまして、教育的な予算で相当な学校に対する財政的な支援というものはいただいております。以前に比べはるかに学校に対する財政的な支援というものは、私どもは一生懸命やっているつもりですので、ご理解をいただければと思います。","id":"exchange-092"},{"speaker":"高星委員","kind":"質問・要望","question":"かつて、私は本会議でも質問したことがあるんですけれども、荏原清掃事務所を再度お聞きします。それはわかった上で質問するわけでありますけれども、それですとあと１７年間あのままですよということになるんだろうというふうに思います。","respondent":"本間総務部長、松本環境清掃事業部長","answer":"私から１点目の清掃職員に関するご質問にお答え申し上げます。配置は難しいかなというふうには考えてありますが、なおかつ状況等がありますれば、検討してまいりたいと考えているところです。この課題を解決するために、あるいは各戸収集そのものについては手間暇かかりますので、収集車両を増やすなど対応策を図っているところです。","id":"exchange-093"},{"speaker":"高星委員","kind":"意見","question":"いずれにしても２０年の用途指定期間の問題は清掃事務所だけの問題ではございませんででして、清掃事務所だけの問題じゃなくてあろうと思うんです。その辺のところを一言だけ考え方を聞きたいと思いますとの意見を述べました。","respondent":"松本環境清掃事業部長","answer":"私ども事業を進める立場に立つ者にとって、確かに２０年間固定化するということは非常にきつい困難な状況です。そういう意味では、この内容について一律ではなくて、柔軟な対応を求めていきたいというふうに考えてあります。","id":"exchange-094"},{"speaker":"高星委員","kind":"質問・要望","question":"おおよそ区民の中には「衛生試験所ってどこにあるんですか」というくらいに、やっている仕事は大変驚きました。私は仕事の関係で尋ねる機会があったんですけれども、Ｏ１５７を含め感染症、水道水や河川。","respondent":"新美保健高齢事業部長","answer":"平成１３年の組織改正で、試験所の位置づけについては両所の調整機能に着目をしまして、健康課に位置づけたものです。その検討の中で、試験所の組織的位置づけをどうするかにつきましても、併せて検討をしています。","id":"exchange-095"},{"speaker":"高星委員","kind":"質問・要望","question":"品川３２万区民の安全、品川区民の安心をここで守り切る、こういう意気込みを与えていただきたいなというふうに思います。このことを聞いて、私の質問を終わらせてほしいと求めました。","respondent":"新美保健高齢事業部長","answer":"平成１４年度には今後の体制をいかにするかということで、根本的に見直しを検討を進め、可能な限り外部委託をしていく方向で見直しを進めております。特に今年度、現在レイアウト等も見直しまして、内部改修をする予定です。","id":"exchange-096"},{"speaker":"藤原委員","kind":"質問","question":"納税者が課税の意味や使い道をよく知り、納税者が理解できるように説明責任を果たすべきだと考えますが、この点についてどのようにお考えでしょうか。残り２年あまりとなった今日、この２点について、まずお伺いいたします。","respondent":"市岡企画財政課長","answer":"それから、２点目の東京都の説明責任あるいは清掃事業の財調の協議の問題なんですが、まず東京都はこれまでも４８％の説明責任を果たしているとは。今のような基本的な認識で平成１７年度までにきちんと財源配分の問題を議論してまいりたいと考えているところです。","id":"exchange-097"},{"speaker":"藤原委員","kind":"質問・要望","question":"それと２番目に質問をさせていただいたんですが、今後の都区協議の最も重要な課題になってくると思います。さらに、改めて要望しますが、これについてのご決意がありましたらお伺いします。","respondent":"市岡企画財政課長","answer":"財調の問題というのは、平成１２年度の都区制度改革のときに清掃事業の経費の問題、その他主要５課題という宿題がございました。この辺の基本的な視点に立って都区協議にあたっては、十分品川区の財政自主権を拡充する視点で主張を貫いてまいりたいと考えています。","id":"exchange-098"},{"speaker":"藤原委員","kind":"質問","question":"その辺は国会との関係だと思うんですけれども、国との協議とか、そういうことに関してはどのように考えているか尋ねました。","respondent":"市岡企画財政課長","answer":"財調の問題は、東京２３区というのがやはりちょっと特殊な事情がありますので、財政調整そのものは当面は必要だとというふうに考えております。","id":"exchange-099"},{"speaker":"藤原委員","kind":"質問","question":"続きまして、小・中一貫校についてお伺いします。９年間を見通した教育内容で、英語学習をしますというふうにお知らせに出ているんですけれども、このカリキュラムの検討状況を教えていただけますか。","respondent":"若月教育長","answer":"現在、英語学習については、慣れる、親しむ、そして使いこなすと、三つの大きなステップを考えてカリキュラムを考えているところです。具体的には、もう既に日野中学校と第二日野小学校でモデルケースとして授業を今現在進め、そのカリキュラムの検証に努めているところです。","id":"exchange-100"},{"speaker":"藤原委員","kind":"質問","question":"いわゆる小・中一貫校で９年間、英語教育をする。これは英会話が主体だと思うんですけれども、その辺についてはいかがか尋ねました。","respondent":"若月教育長","answer":"英会話だけが目的ではありませんが、英語に早めに親しんで、コミュニケーション能力を高めるというのは、一貫校における大きな目標であることには間違いございません。","id":"exchange-101"},{"speaker":"藤原委員","kind":"質問","question":"小・中一貫校において親の最大の心配事というのは、途中からの転校あるいは中学校入学時に一般の学校から小・中一貫校へ進む場合、教育内容の違いについていけるのかという点が１点あると思うんですけれども、その対応についてお伺いします。","respondent":"若月教育長","answer":"いずれにいたしましても、その子どもたちの状況に合った学習にはきちんとした指導をしていこうということは、既にプログラムとして考えてあります。生徒会活動等々を通して、学校生活への適応を図っていこうという、そんなカリキュラムを現在検討しています。","id":"exchange-102"},{"speaker":"藤原委員","kind":"質問","question":"一貫校と同じように英語学習や市民科の教科を学習したらいいんじゃないかと思います。そうすれば、区内のどこの学校へ進学しても基本は同じなので、親は安心できるはずだと思うんですけれども、いかがか尋ねました。","respondent":"若月教育長","answer":"形態はいろいろでありますけれども、カリキュラムの上での実質的な一貫校を目指すことに、本区においては変わりございません。英語、そして市民科、これはどの学校でもこれから展開をしていく予定です。","id":"exchange-103"},{"speaker":"西本委員","kind":"質問・要望","question":"学童保育クラブとすまいるスクールの再編成を行うに至った要因はどこにあるでしょうか。現在の学童保育クラブを利用されている子どもに対しての弾力的な経過措置をしていただきたいと考えますが、いかがか尋ねました。","respondent":"古川教育次長、小沼福祉事業部長","answer":"そして自立に向けて成長するとともに、これを全児童ということで総合的な支援が必要となっています。児童を別々に育成しないで、すまいるスクールを活用して放課後児童健全育成事業を実施するよう再編成を行うこととしたものです。 私のほうから、後段のお尋ねについてを中心にお答えしておきたいと思います。再三申し上げていますように、これについては柔軟な対応あるいは弾力的な対応を取って、遺漏ないような形での適切な手法を考えたいと思ってあります。","id":"exchange-104"},{"speaker":"西本委員","kind":"質問","question":"３年前より始まったすまいるスクールは保育というより、自立を促しながら安全な放課後の居場所を提供する目的で始まったと思われます。児童福祉法を今後どういうふうにとらえて、すまいるスクール等の再編成を考えていくのか尋ねました。","respondent":"古川教育次長","answer":"児童福祉法は、児童の健全育成をうたった基本の法律です。この基本理念を踏まえながら、児童福祉法施行令に定められた設備を整えることにより適切に実施してまいりたいと、このように考えてあります。","id":"exchange-105"},{"speaker":"西本委員","kind":"質問","question":"国と東京都では放課後児童健全育成事業の要綱が定められております。すまいるスクールが今後放課後児童健全育成事業として運営されるならば、基準となる要綱はどのようなものになるのか尋ねました。","respondent":"古川教育次長","answer":"特別区におきましては、これらの要綱を踏まえながら、それぞれの区の実情に合わせて独自性を発揮した事業を実施しているのが現状です。品川区におきましても、区の責任におきまして適切に実施をしてまいります。","id":"exchange-106"},{"speaker":"西本委員","kind":"確認","question":"国と東京都でそれぞれ要綱があるということですが、東京都の要綱と併せて確認をします。一人ひとりの子どもたちに精神的なケアも含めて大切な部分と思いますが、その必要性をどう考えられておりますか尋ねました。","respondent":"古川教育次長","answer":"運営にあたり必要な情報、例えば緊急時の連絡先でありますとか保護者の勤務先、こういった情報につきましては把握をしてまいりたいと考えています。","id":"exchange-107"},{"speaker":"西本委員","kind":"確認","question":"その中の一つに安全確保とありますが、出欠確認をどうされるのでしょうか。来る予定の子どもが来ない場合の対処は、どのようにしていくのでしょうか、それについてご説明をお願いいたします。","respondent":"古川教育次長","answer":"欠席の場合の連絡、特に低学年の場合ですけれども、保護者の方に対しましては電話等で連絡をするように、今後対応してまいりたいと考えています。","id":"exchange-108"},{"speaker":"西本委員","kind":"意見","question":"学童保育を必要とする子どもは、５時以降まで残っているケースが多いと思います。学童保育クラブでは集団下校するなど指導を行っておりますが、すまいるスクールではどのように対応するかご説明をお願いいたしますとの意見を述べました。","respondent":"古川教育次長","answer":"そういった場合につきましては、できるだけ一緒に帰るような帰宅の指導をしてまいりたい。いずれにいたしましても、寄り道をしないで、通学路を通って真っ直ぐ帰るような指導をしてまいりたいと考えています。","id":"exchange-109"},{"speaker":"西本委員","kind":"意見","question":"学校があるときと夏休みの長期の休みとでは、子どもたちの生活も異なります。この違いをどう考えているか、お考えをご説明お願いいたしますとの意見を述べました。","respondent":"古川教育次長","answer":"ＰＴＡとの共催事業等を取り入れながら、地域や家庭との協力で児童の健全育成を図っていく、このように考えております。そして夏休みですけれども、できればゆっくり過ごすようなことを基本にいたしながら、必要に応じて勉強タイムなど設けてまいりたいと考えています。","id":"exchange-110"},{"speaker":"西本委員","kind":"質問・要望","question":"必要か否か、その方法はどのようなことがあるかなど、今後の動向を見ながら検討していくことは可能でしょうか。利用する保護者と学校、検討する機会をつくっていただくことは可能かどうか、その辺の柔軟性についても説明をお願いしたいと思います。","respondent":"古川教育次長","answer":"この２年間すまいるスクール事業を実施してまいりました。保護者と指導員での話し合いというようなことが最後にございましたけれども、基本的な方針につきましては教育委員会のほうで出していく考えです。","id":"exchange-111"},{"speaker":"西本委員","kind":"質問・要望","question":"指導員の構成と非常勤のそれぞれの配置はどのようにしていくのでしょうか。その対処をどうしていくのか、いずれ専任指導員も非常勤化にするお考えがあるのか、考え方をお聞かせ願います。","respondent":"古川教育次長","answer":"これからさまざまな形で説明会等をやってありますけれども、いずれにいたしましても必要な人員を配置していくという考え方に立ってあります。","id":"exchange-112"},{"speaker":"西本委員","kind":"質問","question":"３年間すまいるスクールを実施して、地域の方々やボランティアの方々の協力を得ながら、すまいるスクールも日々発展していくとお聞きしています。今後、このすまいるスクールはどのように発展していこうとするのか、将来の目標、ビジョンを説明を求めました。","respondent":"古川教育次長","answer":"社会性、人間性の育成という点におきましても、大きな役割を果たすのではないかというふうに考えてあります。これからはこういった観点から、学校を活用しつつ地域や保護者の方々の参加をさらに進めながら、さらに拡大充実に努めていきたいと考えています。","id":"exchange-113"},{"speaker":"西本委員","kind":"質問","question":"今の子どもたちの環境の変化を考えますと、親が就労している子どもの保育に欠けるという定義は変わってきているのかなというふうに考えております。子どもたちの状況を考えたときに、それらの関係をどのように運営されていくのか、お考えをお聞きしたいと思います。","respondent":"古川教育次長","answer":"特に、地域との関係を大事にして、このすまいるスクールはスタートしたわけです。今後とも、そういう観点を大事にしながら、この事業の拡大に努めていきたいと考えています。","id":"exchange-114"},{"speaker":"井上委員","kind":"提案","question":"私は子どもの発達に詳しい作業療法士に伺いましたが、このような調査表は珍しいものではないそうです。人権宣言をしている品川区は、この調査をどのように考えるのか、見解をお伺いいたしますとの意見を述べました。","respondent":"古川教育次長","answer":"質問の調査につきましては、区内小・中学校で実施いたしまして、東京都教育委員会へ提出をしたものです。さらには高機能自閉症等、特別支援教育の推進についての資料を収集するという観点での調査であり、私どもはそれに対応したものです。","id":"exchange-115"},{"speaker":"井上委員","kind":"質問","question":"そういったことが必要であるとことで、なおかつ７月１１日付で来ましたので、教育委員会に来たのはさらに後だと思います。担任の一人の先生がご覧になったのではなく、複数の先生がそこに係わられたのかどうかお伺いいたします。","respondent":"古川教育次長","answer":"東京都への報告は９月１９日に提出しています。もう１点、この調査にあたりましては、複数の教員が係わってあります。","id":"exchange-116"},{"speaker":"井上委員","kind":"質問","question":"こういう現状を区はどのように考えているのか、お伺いをいたします。子どもたちの行事や学習への参加が人員の配置、施設設備の改善、その他の配慮等によって保障されるのかどうか伺います。","respondent":"古川教育次長","answer":"原則として各学校の責任において行うこととなっておりまして、保護者の方に介助員を探していただくといったことは、品川区ではしてございません。","id":"exchange-117"},{"speaker":"井上委員","kind":"質問・要望","question":"具体的に、どのように保障するのか伺います。通常学級で学びたいというニーズも尊重されるのかどうか、確認をさせてほしいと求めました。","respondent":"古川教育次長","answer":"現在、設置されております就学指導委員会が、保護者や本人のニーズ等の調整方法などを今後検討してまいりたいと考えています。東京都の中間のまとめでは、学齢期においても地域との関係を継続できるようにするというふうになってありますので、ご理解をいただきたいと思います。","id":"exchange-118"},{"speaker":"井上委員","kind":"質問","question":"副籍ということで、ニーズも尊重されると考えていますけれども、まだ始まっていない状況ではありますけれども、支援教室ができた場合には、担任はどのように配置されるのかということと、専門家のニーズの押しつけがあってはならないと考えますけれども、その点についてはいかがか尋ねました。","respondent":"古川教育次長","answer":"いずれにいたしましても特別支援教室の担任の配置につきましては、特別支援教室の教員の配置について検討をしています。区といたしましても、東京都の最終報告の結果を待ちながら、今後明らかになっていくものをきちっととらえていきたいと考えています。","id":"exchange-119"},{"speaker":"井上委員","kind":"質問・要望","question":"逆に後退することのないように、ぜひ子どもの最善の利益を基本に取り組んでいただきたいと要望いたしまして、次の質問に移らせていただきます。小・中一貫校を選択しない子どもたちの問題はどうするのか、お伺いをいただきます。","respondent":"若月教育長","answer":"このことについては、再三お答えをしております。決して、ほかの子どもたちに不利益を生じないようにしようです。","id":"exchange-120"},{"speaker":"井上委員","kind":"質問","question":"保護者や児童・生徒の多様なニーズにこたえるということですけれども、実際には小・中一貫校のニーズをどのように調査をしたのか教えてください。大崎、大井地区がそれぞれ選ばれた理由を伺います。","respondent":"若月教育長","answer":"そうしたものを解決するための方策の一つとして、教育委員会が小・中一貫校といった新たな展開の中で解決をしていこうというふうに考えたものです。","id":"exchange-121"},{"speaker":"井上委員","kind":"確認","question":"私が伺いたかったのは、保護者の方々のニーズについて、どういう調査をされたのかということをお願いいたします。地域の学校の設置状況、そういったところが中心であるというご答弁かと思いますが、その辺を確認させてください。","respondent":"若月教育長","answer":"必ずしも、どこにでもつくれるということではありません。そこに小・中一貫校の建設を考えた、それだけのことであります。","id":"exchange-122"},{"speaker":"井上委員","kind":"質問・要望","question":"教育改革はしてほしいという保護者の思いはありましたけれども、そういうことも１００％そうではないのではないかという意見を聞いております。平成２０年までに特例を活用して一体型と分離型の小・中一貫校を四、五ヶ所程度つくるとありますが、どこまで決まっているのか伺います。","respondent":"若月教育長","answer":"平成２０年までにというお話がございましたけれども、必ずしもそういったことは今現在コンクリートして決まっているということではございません。","id":"exchange-123"},{"speaker":"井上委員","kind":"質問・要望","question":"ここに書かれております「平成２０年までに特例を活用し」というところは、必ずしも平成２０年ではないということなのかどうかということ。ここについて改めて始まっていないところでの実践と検証ということは、どういった意味をするのか教えてほしいと求めました。","respondent":"若月教育長","answer":"それが一体どうだったか、新たな小・中一貫校像というものは当然でき上がってくるだろうと、こういうことを考えているところです。そうした中で、小・中一貫校の計画を進めていきたいと、こんなふうに思っております。","id":"exchange-124"},{"speaker":"井上委員","kind":"質問","question":"区は、このような進め方をどのように考えているのか伺います。教育への市民参加や十分な事前協議について、開かれた教育の立場から見解を伺います。","respondent":"若月教育長","answer":"２校目の小・中一貫校の準備についても、私たちは１校目の日野中学校での経験を生かして、説明会を何度も繰り返し進めてきているところです。","id":"exchange-125"},{"speaker":"井上委員","kind":"質問・要望","question":"今のご答弁ですと、決定をした段階で説明をしているということが、保護者の方々にももう少し説明責任を果たしていただきたいという要望だと思います。私どもは議事録を求めましたけれども、不存在という回答をいただきました。","respondent":"若月教育長","answer":"それから、２点目の施設計画検討部会とか、そういったところの中身ということですが、何度もこれば随分繰り返しやっているものです。ここでどんな話ということもなかなかお話できませんし、この点につきましては、どういうふうにお答えをしていいか見当がつかないわけです。","id":"exchange-126"},{"speaker":"井上委員","kind":"質問・要望","question":"特区申請によりますと、平成１６年度から新しい教育課程を実施することになっていますが、その対象校はどこになるのでしょうか。教材、副読本、テキストはどのようなものを使うのか、また教える教師にはどのような研修がされているのか尋ねました。","respondent":"若月教育長","answer":"それから、市民科の授業の時間数が多いという、これもご説明していると思いますが、現在学校では道徳と特別活動と呼ばれる領域があります。そのカリキュラムをつくる中から、教員の指導ガイダンスのようなものを同時に作成していくという考えです。","id":"exchange-127"},{"speaker":"井上委員","kind":"質問","question":"併せまして、先ほど一つ答弁がなかったのは、教材、副読本、テキストはどういったものを使うのかというところを併せてお伺いをいたします。こういったことも、そちらのほうに係わることだと思いますけれども、十分な説明が児童・生徒・保護者に伝わっているのかお伺いをいたします。","respondent":"若月教育長","answer":"教材については、今開発をしている最中です。それから、市民科だとか、新しい教科あるいは授業時数のことにつきましては、既に学校を通して保護者等には説明をしています。","id":"exchange-128"},{"speaker":"井上委員","kind":"質問・要望","question":"柔軟な対応をしてほしいということで、事前にそういった配慮もしていただきたいと、要望をします。有効利用の検討を要望しますけれども、この辺につきまして、お考えをお聞かせほしいと求めました。","respondent":"本間総務部長","answer":"公有財産管理運用委員会で調整をして原案をつくり、事業部経営会議の場で十二分に議論していきたいと、かよう考えている次第です。","id":"exchange-129"},{"speaker":"井上委員","kind":"質問・要望","question":"やはり情報をたくさん出していただくことと、そしてまたそこに市民が参加してともに考えていく。区長が再三おっしゃられております行政と市民との共同でいろいろな施策を進めていただければと要望いたしまして、質問を終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-130"},{"speaker":"伊藤委員","kind":"質問・要望","question":"会派所属議員の質問、そして会派として提出いたしました政策要望等を踏まえ、平成１６年度品川区予算に反映していただきますよう強く要望いたします。区議会第一党自由民主党品川区議団との連携をより深め対処していただくことを要望し、平成１４年度品川区各会計歳入歳出決算を認定いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-131"},{"speaker":"三上委員","kind":"提案","question":"なお、職員の６カ月定期代の早期実現、特別昇給問題について区民感情を十分受け止めていただき、改善されるよう強く求めておきます。健全な財政運営のためにも、さらなる行財政改革の推進を要望し、意見表明を終わりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-132"},{"speaker":"宮崎委員","kind":"質問・要望","question":"なぜ急いで拡大するのでしょうか。区は住民の反発に希望する子どもの出欠確認、正規職員４人を１人にするようではサービスは大幅低下し、事故の増加も心配されます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-133"},{"speaker":"土井委員","kind":"質問・要望","question":"ＰＴＡなどの要望を受けて補正を組んで実施され、今年の夏に間に合いました。今後の適切な対応が求められます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-134"},{"speaker":"藤原委員","kind":"質問・要望","question":"特に経常収支比率が８０％以下におさまっていることは、財政の健全性を示すものでありますが、引き続き相当な努力が求められています。財政力向上のために一層努力されますことを要望し、来年度に向けての予算要望なども十分に理解していただき、意見表明といたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-135"},{"speaker":"井上委員","kind":"提案","question":"生活者ネットワークは意見と要望を以下に述べまして、平成１４年度品川区一般会計決算および国民健康保険事業会計、認定することに賛成いたします。平和、人権に対して、品川区から発信することを願い、以上意見と要望を述べまして、意見表明を終わりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-136"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/623169?Template=document&Id=1224#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2003-01-01&TermEnd=2003-12-31"}],"sourceMeta":{"pages":0,"characters":121867,"voices":302}},{"id":"h15-20031025-9","meetingId":"h15-cm10","date":"2003年10月25日","dateIso":"2003-10-25","committee":"文教委員会","time":"午前０時３３分～午後３時０５分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件整理しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/447915?Template=document&Id=4484#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2003-01-01&TermEnd=2003-12-31"}],"sourceMeta":{"pages":0,"characters":408,"voices":4}}]);
